export type Term = {
  /** Anchor on the glossary page. */
  id: string;
  term: string;
  /** Other spellings that should also match in lesson text. */
  aka?: string[];
  /** One or two plain sentences. Shown in hover cards and search. */
  short: string;
  /** Where to learn more. */
  lesson?: string;
  /** Match exactly (acronyms such as RAG), instead of ignoring case. */
  exact?: boolean;
  /** A term a complete beginner needs first. */
  basic?: boolean;
};

export const glossary: Term[] = [
  { id: 'ai', term: 'Artificial intelligence', aka: ['AI'], basic: true, short: 'Getting computers to do things that usually need a thinking person. Today it mostly means systems that learn from examples.', lesson: '/learn/start/what-is-ai-in-plain-english/' },
  { id: 'api', term: 'API', exact: true, basic: true, short: 'Short for application programming interface: an agreed way for one program to ask another for something. Apps use one to send text to a model and get the answer back.', lesson: '/learn/start/how-apps-use-ai/' },
  { id: 'model', term: 'Model', basic: true, short: 'The part of an AI system that has learned: a big set of numbers, plus the code that uses them. The app around it is a separate thing.', lesson: '/learn/start/how-apps-use-ai/' },
  { id: 'neural-network', term: 'Neural network', aka: ['neural networks'], basic: true, short: 'A model built from layers of simple calculations, each with numbers that can be adjusted. Training tunes those numbers so the answers get closer to right.', lesson: '/learn/foundations/how-models-learn/' },
  { id: 'training', term: 'Training', basic: true, short: 'Showing a model lots of examples and adjusting its numbers a little after each one, so its answers get better. It happens before the model is used.', lesson: '/learn/foundations/how-models-learn/' },
  { id: 'generative-ai', term: 'Generative AI', basic: true, short: 'AI that makes new things, such as text, pictures, sound or code, instead of only sorting or labelling things.', lesson: '/learn/start/what-is-ai-in-plain-english/' },
  { id: 'vector', term: 'Vector', basic: true, short: 'A list of numbers. AI uses vectors to stand for words, sentences or pictures, so that similar things get similar numbers.', lesson: '/learn/foundations/tokens-and-embeddings/' },
  { id: 'loss', term: 'Loss', aka: ['loss function'], short: 'A single number that says how wrong a model’s predictions are on some examples. Training tries to make it smaller.', lesson: '/learn/foundations/how-models-learn/' },
  { id: 'gradient-descent', term: 'Gradient descent', aka: ['backpropagation', 'backprop'], short: 'Training by repeatedly nudging every number in the model in the direction that reduces the loss. Backpropagation is how those directions are worked out.', lesson: '/learn/foundations/how-models-learn/' },
  { id: 'overfitting', term: 'Overfitting', short: 'When a model learns its training examples too closely, including their noise, and does worse on new data.', lesson: '/learn/foundations/classical-ml-essentials/' },
  { id: 'precision-recall', term: 'Precision and recall', aka: ['precision', 'recall', 'F1'], short: 'Precision: of the items flagged, how many were right. Recall: of the items that should have been flagged, how many were found.', lesson: '/learn/foundations/classical-ml-essentials/' },
  { id: 'data-leakage', term: 'Data leakage', aka: ['leakage'], short: 'When information that would not be available at prediction time sneaks into training or evaluation, making results look better than they will be.', lesson: '/learn/foundations/classical-ml-essentials/' },
  { id: 'top-p', term: 'Top-p sampling', aka: ['nucleus sampling', 'top-k'], short: 'Choosing the next token only from the smallest set of likely tokens whose probabilities add up to p. Top-k keeps a fixed number of tokens instead.', lesson: '/learn/foundations/inside-a-transformer/' },
  { id: 'rope', term: 'RoPE', aka: ['rotary position embedding', 'positional encoding'], exact: true, short: 'A way of telling a transformer where each token sits in the sequence by rotating its query and key vectors by an angle that depends on position.', lesson: '/learn/foundations/inside-a-transformer/' },
  { id: 'lora-qlora', term: 'QLoRA', exact: true, short: 'LoRA fine-tuning on top of a base model whose weights are stored in 4 bits, which cuts the memory needed to fine-tune large models.', lesson: '/learn/llm/fine-tuning-in-practice/' },
  { id: 'dpo', term: 'DPO', aka: ['direct preference optimisation'], exact: true, short: 'Direct preference optimisation: training a model on pairs of preferred and rejected answers without a separate reward model.', lesson: '/learn/llm/fine-tuning-in-practice/' },
  { id: 'hnsw', term: 'HNSW', exact: true, short: 'Hierarchical navigable small world: a graph-based index for fast approximate nearest-neighbour search over vectors. Trades memory for speed and recall.', lesson: '/learn/rag-agents/vector-search-and-retrieval-metrics/' },
  { id: 'ndcg', term: 'nDCG', aka: ['MRR'], short: 'Normalised discounted cumulative gain: a retrieval score that rewards putting the most relevant results near the top of the list.', lesson: '/learn/rag-agents/vector-search-and-retrieval-metrics/' },
  { id: 'speculative-decoding', term: 'Speculative decoding', short: 'A small draft model proposes several tokens and the big model checks them in one pass, giving the same output faster when most drafts are accepted.', lesson: '/learn/serving/inference-optimisation/' },
  { id: 'flashattention', term: 'FlashAttention', short: 'An exact way to compute attention that works in small tiles so it rarely touches slow memory, making long prompts faster and lighter.', lesson: '/learn/serving/inference-optimisation/' },
  { id: 'clip', term: 'CLIP', exact: true, short: 'A model trained to match images with their captions, so pictures and text land near each other in the same embedding space.', lesson: '/learn/foundations/multimodal-models/' },
  { id: 'owasp-llm', term: 'OWASP Top 10 for LLM applications', aka: ['OWASP'], short: 'A widely used list of the main security risks in applications built on language models, with prompt injection at the top.', lesson: '/learn/evals/llm-security/' },
  { id: 'drift', term: 'Drift', aka: ['data drift', 'model drift'], short: 'When the inputs a system sees, or the model behind it, change over time so that quality quietly gets worse.', lesson: '/learn/evals/llmops-in-production/' },
  { id: 'canary', term: 'Canary release', aka: ['canary', 'shadow traffic'], short: 'Rolling a change out to a small share of traffic first and watching the numbers before sending everyone to it.', lesson: '/learn/evals/llmops-in-production/' },
  { id: 'cold-start', term: 'Cold start', short: 'The delay when a new server has to load a multi-gigabyte model before it can answer its first request.', lesson: '/learn/infra/kubernetes-and-autoscaling-for-inference/' },
  { id: 'cuda', term: 'CUDA', exact: true, short: 'NVIDIA’s programming platform for GPUs. Most AI software is built on it, which is why changing chip vendors takes real work.', lesson: '/learn/infra/gpu-basics/' },
  { id: 'dcgm', term: 'DCGM', exact: true, short: 'NVIDIA’s tool and library for monitoring GPU health, memory and utilisation in data centres.', lesson: '/learn/infra/gpu-observability-and-capacity-planning/' },
  { id: 'data-parallelism', term: 'Data parallelism', short: 'Every GPU holds a full copy of the model and works on a different slice of the batch.', lesson: '/learn/infra/multi-gpu-parallelism-and-interconnect/' },
  { id: 'expert-parallelism', term: 'Expert parallelism', short: 'Spreading the experts of a mixture-of-experts model across GPUs, with tokens routed to the experts that need them.', lesson: '/learn/infra/multi-gpu-parallelism-and-interconnect/' },
  { id: 'fsdp', term: 'FSDP', aka: ['ZeRO', 'fully sharded data parallel'], exact: true, short: 'Fully sharded data parallel: spreading weights, gradients and optimizer state across GPUs so each one holds only a part.', lesson: '/learn/infra/training-infrastructure/' },
  { id: 'gguf', term: 'GGUF', exact: true, short: 'A single-file model format used by llama.cpp and the tools built on it. It stores quantized weights and metadata together.', lesson: '/learn/local/memory-math-for-local-models/' },
  { id: 'hbm', term: 'HBM', aka: ['high-bandwidth memory'], exact: true, short: 'High-bandwidth memory: stacked memory placed right next to the chip, with several times the bandwidth of the GDDR on cheaper cards.', lesson: '/learn/infra/gpu-basics/' },
  { id: 'infiniband', term: 'InfiniBand', short: 'A high-bandwidth, low-latency network used to link GPU servers together in training and large-scale serving clusters.', lesson: '/learn/infra/multi-gpu-parallelism-and-interconnect/' },
  { id: 'llamacpp', term: 'llama.cpp', short: 'An open-source C and C++ engine that runs quantized models on laptops and desktops, using the GGUF file format.', lesson: '/learn/local/inference-engines-compared/' },
  { id: 'moe', term: 'Mixture of experts', aka: ['MoE'], short: 'A model made of many specialist sub-networks where only a few run for each token, so it stores a lot but computes a little.', lesson: '/learn/infra/multi-gpu-parallelism-and-interconnect/' },
  { id: 'nvlink', term: 'NVLink', aka: ['NVSwitch'], short: 'NVIDIA’s very fast link between GPUs inside a server. It is what makes splitting a model across GPUs practical.', lesson: '/learn/infra/multi-gpu-parallelism-and-interconnect/' },
  { id: 'ollama', term: 'Ollama', short: 'A friendly tool for downloading and running open-weights models on your own computer.', lesson: '/learn/local/run-models-locally/' },
  { id: 'open-weights', term: 'Open weights', aka: ['open-weight', 'open-weights'], short: 'A model whose trained weights you can download and run yourself. Licences differ, so read them before you build on one.', lesson: '/learn/local/private-and-air-gapped-ai/' },
  { id: 'paged-attention', term: 'PagedAttention', short: 'Storing the KV cache in small blocks instead of one big slab, so less memory is wasted and more users fit on a GPU.', lesson: '/learn/serving/kv-cache-and-memory/' },
  { id: 'pipeline-parallelism', term: 'Pipeline parallelism', short: 'Splitting a model into groups of layers, one group per GPU, and passing batches through them in order.', lesson: '/learn/infra/multi-gpu-parallelism-and-interconnect/' },
  { id: 'provisioned-throughput', term: 'Provisioned throughput', aka: ['PTU', 'PTUs'], short: 'Reserved model capacity bought by the hour for steady load and predictable latency, instead of paying per token.', lesson: '/learn/cloud/quotas-capacity-and-regions/' },
  { id: 'safetensors', term: 'Safetensors', short: 'A model file format that stores only numbers, so loading it cannot run hidden code the way a pickled file can.', lesson: '/learn/local/private-and-air-gapped-ai/' },
  { id: 'spot', term: 'Spot instances', aka: ['spot capacity'], short: 'Spare cloud capacity sold at a discount, which the provider can take back at short notice.', lesson: '/learn/infra/gpu-and-accelerator-instances/' },
  { id: 'tensor-core', term: 'Tensor core', aka: ['tensor cores'], short: 'Hardware inside modern NVIDIA GPUs that multiplies small matrices very fast. It is a big part of why GPUs suit neural networks.', lesson: '/learn/infra/gpu-basics/' },
  { id: 'tensor-parallelism', term: 'Tensor parallelism', short: 'Cutting each layer’s matrices across GPUs so they all work on every layer. It needs very fast links between the GPUs.', lesson: '/learn/infra/multi-gpu-parallelism-and-interconnect/' },
  { id: 'tpu', term: 'TPU', exact: true, short: 'Tensor Processing Unit: Google’s own AI accelerator, available on Google Cloud.', lesson: '/learn/infra/gpu-and-accelerator-instances/' },
  { id: 'trainium', term: 'Trainium', aka: ['Inferentia'], short: 'AWS-designed AI chips (Trainium for training, Inferentia for inference), programmed with the Neuron SDK instead of CUDA.', lesson: '/learn/infra/gpu-and-accelerator-instances/' },
  { id: 'utilisation', term: 'Utilisation', aka: ['utilization'], short: 'The share of time hardware spends doing useful work. When you run your own GPUs it drives your cost per token.', lesson: '/learn/local/self-hosting-vs-api-economics/' },
  { id: 'vllm', term: 'vLLM', short: 'An open-source engine for serving language models, known for PagedAttention and continuous batching.', lesson: '/learn/local/inference-engines-compared/' },
  { id: 'vram', term: 'VRAM', aka: ['GPU memory'], exact: true, short: 'The memory on the graphics card itself. The weights and KV cache must fit in it, or be slowly moved in and out.', lesson: '/learn/infra/gpu-basics/' },
  { id: 'agent', term: 'Agent', short: 'A system where a model can choose actions, such as calling tools, and repeat in a loop until a task is done.', lesson: '/learn/rag-agents/agents-and-tool-use/' },
  { id: 'attention', term: 'Attention', short: 'The mechanism that lets each token in a transformer weigh how much every other token matters for its own meaning.', lesson: '/learn/foundations/attention-intuition/' },
  { id: 'availability', term: 'Availability', short: 'The share of time a service works. 99.9% allows about 8.8 hours of downtime a year.', lesson: '/learn/systems/model-routing-and-fallbacks/' },
  { id: 'backoff', term: 'Exponential backoff', aka: ['backoff'], short: 'Retrying a failed call after waits that grow each time, so retries do not pile onto an overloaded service.', lesson: '/learn/systems/model-routing-and-fallbacks/' },
  { id: 'batching', term: 'Continuous batching', aka: ['batching'], short: 'Serving many users on the same chips by swapping finished requests for waiting ones at every step. It keeps hardware busy and prices low.', lesson: '/learn/serving/life-of-a-request/' },
  { id: 'bedrock', term: 'Amazon Bedrock', aka: ['AWS Bedrock', 'Bedrock'], short: 'AWS’s managed service for calling foundation models from several providers through one API.', lesson: '/learn/cloud/what-is-bedrock/' },
  { id: 'chunking', term: 'Chunking', short: 'Splitting documents into passages small enough to be specific and large enough to make sense alone, before indexing them for retrieval.', lesson: '/learn/rag-agents/chunking-and-retrieval-quality/' },
  { id: 'circuit-breaker', term: 'Circuit breaker', short: 'A guard that stops calling a failing service for a short time instead of waiting on every request.', lesson: '/learn/systems/model-routing-and-fallbacks/' },
  { id: 'context-window', term: 'Context window', basic: true, short: 'The most text a model can look at in one go, counted in tokens. What you send and what it writes back both count.', lesson: '/learn/llm/context-window-and-caching/' },
  { id: 'decode', term: 'Decode', aka: ['decoding'], short: 'The phase where a model writes its answer one token at a time. It is limited by memory bandwidth.', lesson: '/learn/serving/life-of-a-request/' },
  { id: 'deep-learning', term: 'Deep learning', short: 'Machine learning with large neural networks of many layers. It learns its own features from raw data.', lesson: '/learn/foundations/ml-to-ai-timeline/' },
  { id: 'distillation', term: 'Distillation', short: 'Training a small model to imitate a larger one, to get most of the quality at a fraction of the cost.', lesson: '/learn/edge/quantization-for-edge/' },
  { id: 'edge', term: 'Edge inference', aka: ['on-device AI', 'edge AI'], short: 'Running a model on the device itself, such as a phone or hearing aid, instead of calling a server.', lesson: '/learn/edge/edge-vs-cloud-inference/' },
  { id: 'embedding', term: 'Embedding', basic: true, aka: ['embeddings'], short: 'A list of numbers that stands for the meaning of a word, sentence or document. Things with similar meanings get numbers that sit close together.', lesson: '/learn/foundations/tokens-and-embeddings/' },
  { id: 'eval', term: 'Eval', aka: ['evals', 'evaluation suite'], short: 'A repeatable test for model behaviour: inputs, a definition of a good answer, and a way to score outputs.', lesson: '/learn/evals/evals-101/' },
  { id: 'fine-tuning', term: 'Fine-tuning', aka: ['fine-tune', 'fine-tuned'], short: 'Further training a model on your own examples to change its style, format or narrow skills. It is a poor way to add facts.', lesson: '/learn/llm/prompting-vs-rag-vs-fine-tuning/' },
  { id: 'foundation-model', term: 'Foundation model', aka: ['foundation models'], short: 'A large model trained on broad data that can be adapted to many tasks, such as a general-purpose language model.', lesson: '/learn/cloud/what-is-bedrock/' },
  { id: 'few-shot', term: 'Few-shot', aka: ['few-shot examples'], short: 'Putting a few worked examples in the prompt so the model copies the pattern.', lesson: '/learn/llm/prompting-and-structured-output/' },
  { id: 'gpu', term: 'GPU', exact: true, short: 'A chip built for massive parallel arithmetic. Almost all model training and most serving runs on GPUs or similar accelerators.', lesson: '/learn/serving/kv-cache-and-memory/' },
  { id: 'guardrails', term: 'Guardrails', short: 'Checks on what goes into and comes out of a model: sensitive data, disallowed topics, unsupported claims.', lesson: '/learn/cloud/cloud-ai-service-map/' },
  { id: 'hallucination', term: 'Hallucination', basic: true, aka: ['hallucinations', 'hallucinate'], short: 'An answer that sounds sure and fluent but is not true. The model writes what sounds likely, and does not check facts.', lesson: '/learn/start/how-a-chatbot-answers/' },
  { id: 'hybrid-search', term: 'Hybrid search', short: 'Combining keyword search and vector search, then merging the results. Catches both exact terms and similar meanings.', lesson: '/learn/rag-agents/chunking-and-retrieval-quality/' },
  { id: 'inference', term: 'Inference', basic: true, short: 'Using a trained model to get an answer. Training builds the model; inference is every use of it afterwards.', lesson: '/learn/serving/life-of-a-request/' },
  { id: 'kv-cache', term: 'KV cache', short: 'Stored keys and values of earlier tokens so that generating each new token does not recompute them. It grows with context length and users.', lesson: '/learn/serving/kv-cache-and-memory/', exact: true },
  { id: 'latency', term: 'Latency', short: 'How long a request takes. For model calls, usually measured as time to first token and total time.', lesson: '/learn/serving/life-of-a-request/' },
  { id: 'llm', term: 'Large language model', basic: true, aka: ['LLM', 'LLMs', 'language model'], short: 'A model trained on a huge amount of text to guess the next token, again and again. Chatbots are built on them.', lesson: '/learn/start/what-is-ai-in-plain-english/' },
  { id: 'llm-judge', term: 'LLM-as-judge', aka: ['model judge', 'judge model'], short: 'Using one model to grade another model’s output against a rubric. It scales, and it has biases that need calibrating.', lesson: '/learn/evals/llm-as-judge-pitfalls/' },
  { id: 'lora', term: 'LoRA', exact: true, short: 'A cheap fine-tuning method that trains a small number of extra parameters instead of the whole model.', lesson: '/learn/llm/prompting-vs-rag-vs-fine-tuning/' },
  { id: 'machine-learning', term: 'Machine learning', basic: true, short: 'Getting a computer to learn the rules from examples, instead of people writing the rules.', lesson: '/learn/start/what-is-ai-in-plain-english/' },
  { id: 'mcp', term: 'Model Context Protocol', aka: ['MCP'], exact: true, short: 'An open standard for describing tools and data sources so that different applications can use them with a model.', lesson: '/learn/rag-agents/agents-and-tool-use/' },
  { id: 'npu', term: 'NPU', exact: true, short: 'A neural processing unit: a small, power-efficient chip designed to run model arithmetic on devices.', lesson: '/learn/edge/quantization-for-edge/' },
  { id: 'parameters', term: 'Parameters', basic: true, aka: ['weights'], short: 'The adjustable numbers inside a model, like tiny dials, set during training. A model with 8 billion parameters has 8 billion of them.', lesson: '/learn/start/what-is-ai-in-plain-english/' },
  { id: 'prefill', term: 'Prefill', short: 'The phase where the model reads the whole prompt in one parallel pass. Its length is your time to first token.', lesson: '/learn/serving/life-of-a-request/' },
  { id: 'pretraining', term: 'Pretraining', short: 'The first, most expensive training stage: learning to predict the next token across a huge body of text.', lesson: '/learn/foundations/training-pipeline/' },
  { id: 'prompt', term: 'Prompt', basic: true, short: 'Everything sent to the model in one go: instructions, background, examples and your question.', lesson: '/learn/llm/prompting-and-structured-output/' },
  { id: 'prompt-caching', term: 'Prompt caching', short: 'Reusing the processed form of a repeated prompt prefix. Cached input is cheaper and faster.', lesson: '/learn/llm/context-window-and-caching/' },
  { id: 'prompt-injection', term: 'Prompt injection', short: 'Text in a document or tool result that tries to give the model new instructions. The defence is permission limits, not a stern prompt.', lesson: '/learn/rag-agents/agents-and-tool-use/' },
  { id: 'quantization', term: 'Quantization', short: 'Storing a model’s numbers in fewer bits to make it smaller and often faster, at some cost in precision.', lesson: '/learn/serving/quantization/' },
  { id: 'rag', term: 'RAG', basic: true, aka: ['retrieval-augmented generation', 'retrieval'], exact: true, short: 'Short for retrieval-augmented generation: the app finds the passages that match a question and puts them in the prompt, so the model answers from them.', lesson: '/learn/rag-agents/rag-from-scratch/' },
  { id: 'recall-at-k', term: 'Recall at k', short: 'The share of questions whose correct passage appears in the top k retrieved results. A way to measure retrieval on its own.', lesson: '/learn/rag-agents/chunking-and-retrieval-quality/' },
  { id: 'reranking', term: 'Reranking', aka: ['reranker'], short: 'A second, more careful model that re-scores retrieved candidates and keeps the best few.', lesson: '/learn/rag-agents/chunking-and-retrieval-quality/' },
  { id: 'rlhf', term: 'RLHF', exact: true, short: 'Reinforcement learning from human feedback: training a model to prefer the answers people rank higher.', lesson: '/learn/foundations/training-pipeline/' },
  { id: 'routing', term: 'Model routing', aka: ['routing', 'router'], short: 'Sending each request to the model that suits it, for example a small model for easy requests and a large one for hard ones.', lesson: '/learn/systems/model-routing-and-fallbacks/' },
  { id: 'sagemaker', term: 'Amazon SageMaker AI', aka: ['SageMaker', 'Amazon SageMaker'], short: 'AWS’s platform for building, training and hosting your own models, as opposed to calling hosted ones.', lesson: '/learn/cloud/bedrock-sagemaker-foundry-vertex/' },
  { id: 'system-prompt', term: 'System prompt', short: 'Standing instructions that set the model’s role and rules, sent at the start of every request.', lesson: '/learn/llm/prompting-and-structured-output/' },
  { id: 'langgraph', term: 'LangGraph', short: 'A runtime for agents described as a graph of nodes and edges around one shared state, with saving, pausing and streaming built in.', lesson: '/learn/rag-agents/langchain-and-langgraph/' },
  { id: 'langchain', term: 'LangChain', short: 'A library of model connections, tools and a ready-made agent, create_agent, that runs on LangGraph.', lesson: '/learn/rag-agents/langchain-and-langgraph/' },
  { id: 'checkpointer', term: 'Checkpointer', short: 'Saves a graph’s state under a thread id so a run can pause, resume or continue a conversation.', lesson: '/learn/rag-agents/langchain-and-langgraph/' },
  { id: 'human-in-the-loop', term: 'Human in the loop', short: 'A design where a run pauses so a person can approve, edit or reject an action before it continues.', lesson: '/learn/rag-agents/langchain-and-langgraph/' },
  { id: 'reducer', term: 'Reducer', short: 'A rule for merging a node’s update into one key of a graph’s state: replace it, or for example append to it.', lesson: '/learn/rag-agents/langchain-and-langgraph/' },
  { id: 'mcp-host', term: 'MCP host', short: 'The app a person talks to, such as an assistant. It owns the model conversation, creates one MCP client per server, and decides what the user must approve.', lesson: '/learn/rag-agents/mcp-in-depth/' },
  { id: 'mcp-server', term: 'MCP server', short: 'A small program or service that offers tools, resources and prompts to a host. It can run locally or remotely, and it cannot read the whole conversation.', lesson: '/learn/rag-agents/mcp-in-depth/' },
  { id: 'stdio-transport', term: 'stdio transport', short: 'An MCP transport where the client starts the server as a subprocess and sends one JSON message per line over its standard input and output.', lesson: '/learn/rag-agents/mcp-in-depth/' },
  { id: 'streamable-http', term: 'Streamable HTTP', short: 'An MCP transport where the server has one URL, each message is an HTTP POST, and the reply is JSON or a stream of events.', lesson: '/learn/rag-agents/mcp-in-depth/' },
  { id: 'confused-deputy', term: 'Confused deputy', short: 'An attack where a trusted server is tricked into using its authority for an attacker, such as an OAuth proxy that skips a user’s consent.', lesson: '/learn/rag-agents/mcp-in-depth/' },
  { id: 'token-passthrough', term: 'Token passthrough', short: 'A forbidden pattern where a server accepts a token not issued for it and forwards it downstream, which breaks audience checks and audit trails.', lesson: '/learn/rag-agents/mcp-in-depth/' },
  { id: 'held-out-set', term: 'Held-out set', short: 'Examples you never look at while editing a prompt or model, kept back to test the final version once. A big gap between tuned and held-out scores is the sign of overfitting.', lesson: '/learn/llm/prompt-patterns-and-optimisation/' },
  { id: 'prompt-chaining', term: 'Prompt chaining', short: 'Splitting a task into fixed steps, each a separate model call that works on the previous step’s output, with optional code checks between steps.', lesson: '/learn/llm/prompt-patterns-and-optimisation/' },
  { id: 'evaluator-optimizer', term: 'Evaluator-optimizer', short: 'A workflow where one model call writes a response and another judges it against clear criteria, looping until it is good enough.', lesson: '/learn/llm/prompt-patterns-and-optimisation/' },
  { id: 'orchestrator-workers', term: 'Orchestrator-workers', short: 'A workflow where one model breaks a task into subtasks it could not list in advance, hands them to worker calls, and merges the results.', lesson: '/learn/llm/prompt-patterns-and-optimisation/' },
  { id: 'dspy', term: 'DSPy', short: 'A framework where you write a program and a metric, and an optimizer tunes its prompts and few-shot examples against that metric.', lesson: '/learn/llm/prompt-patterns-and-optimisation/' },
  { id: 'workflow-llm', term: 'Workflow (LLM)', short: 'A system where code decides the order of model calls, unlike an agent, where the model chooses its own next steps.', lesson: '/learn/llm/prompt-patterns-and-optimisation/' },
  { id: 'reasoning-model', term: 'Reasoning model', short: 'A model that writes its own working, called thinking, before it answers. The thinking is billed as output tokens and adds to the wait.', lesson: '/learn/llm/reasoning-models/' },
  { id: 'thinking-tokens', term: 'Thinking tokens', short: 'Tokens a reasoning model generates before its answer. They are billed as output, count against the output limit, and providers may show only a summary.', lesson: '/learn/llm/reasoning-models/' },
  { id: 'test-time-compute', term: 'Test-time compute', short: 'Computation spent while answering, such as thinking longer, rather than during training. How much it helps depends on how hard the task is.', lesson: '/learn/llm/reasoning-models/' },
  { id: 'reasoning-effort', term: 'Reasoning effort', short: 'A setting that tells a reasoning model how much to think: lower favours speed and fewer tokens, higher thinks more thoroughly. Named differently by each provider.', lesson: '/learn/llm/reasoning-models/' },
  { id: 'pass-at-k', term: 'pass@k', short: 'The likelihood that an agent gets at least one correct solution in k attempts. It suits cases where one success is enough.', lesson: '/learn/evals/evaluating-agents/' },
  { id: 'pass-hat-k', term: 'pass^k', short: 'The probability that all k trials of an agent succeed. It measures consistency, and falls as k grows.', lesson: '/learn/evals/evaluating-agents/' },
  { id: 'agent-trial', term: 'Trial', short: 'One attempt at an eval task. Agents vary, so each task is run for several trials, each from a clean environment.', lesson: '/learn/evals/evaluating-agents/' },
  { id: 'transcript', term: 'Transcript', short: 'The full record of one agent trial, also called a trace or trajectory. Read many of them to check that your graders are fair.', lesson: '/learn/evals/evaluating-agents/' },
  { id: 'grader', term: 'Grader', short: 'The logic that scores part of an agent run: code that checks the result, a model with a rubric, or a human reviewer.', lesson: '/learn/evals/evaluating-agents/' },
  { id: 'vector-database', term: 'Vector database', short: 'A database built to store embeddings and find the nearest ones to a query. Examples on the libraries map include Qdrant, Milvus, Weaviate and the Postgres extension pgvector.', lesson: '/learn/rag-agents/choosing-ai-libraries/' },
  { id: 'llm-gateway', term: 'LLM gateway', short: 'A layer that gives one API in front of many model providers, often adding cost tracking and fallbacks. LiteLLM is an example.', lesson: '/learn/rag-agents/choosing-ai-libraries/' },
  { id: 'source-available', term: 'Source-available licence', short: 'A licence that lets you read and use the code under limits, so it is not an OSI-approved open-source licence. The Elastic License 2.0, used by Arize Phoenix, is one.', lesson: '/learn/rag-agents/choosing-ai-libraries/' },
  { id: 'ai-act-provider', term: 'Provider (AI Act)', short: 'Whoever develops an AI system, or has one developed and releases it under their own name. Providers carry most of the Act’s duties.', lesson: '/learn/evals/eu-ai-act-for-engineers/' },
  { id: 'ai-act-deployer', term: 'Deployer (AI Act)', short: 'Whoever uses an AI system under their own authority, other than for personal non-professional use.', lesson: '/learn/evals/eu-ai-act-for-engineers/' },
  { id: 'gpai-model', term: 'General-purpose AI model', short: 'In the AI Act, a model showing significant generality that can competently do a wide range of distinct tasks. Its providers have their own duties.', lesson: '/learn/evals/eu-ai-act-for-engineers/' },
  { id: 'ai-omnibus', term: 'AI Omnibus', short: 'The 2026 change to the EU AI Act that moved the high-risk start dates to 2 December 2027 and 2 August 2028 and added two bans.', lesson: '/learn/evals/eu-ai-act-for-engineers/' },
  { id: 'dgx', term: 'DGX', short: 'NVIDIA’s name for a complete system built around its GPUs: a desktop box (DGX Spark, DGX Station), an eight-GPU server, or a 72-GPU rack that works as one machine.', lesson: '/learn/infra/multi-gpu-parallelism-and-interconnect/' },
  { id: 'hgx', term: 'HGX', short: 'An NVIDIA baseboard carrying eight GPUs linked by NVLink, which server makers build into their own servers. It is not a machine sold as a DGX.', lesson: '/learn/infra/multi-gpu-parallelism-and-interconnect/' },
  { id: 'nvl72', term: 'NVL72', short: 'An NVIDIA rack design that links 72 GPUs (with 36 Grace CPUs) into one NVLink domain, so a model can be split across the whole rack as if it were one machine.', lesson: '/learn/infra/multi-gpu-parallelism-and-interconnect/' },
  { id: 'superchip', term: 'Superchip', short: 'An NVIDIA module that pairs a Grace CPU with one or two GPUs on a fast link. The GB200 superchip has one CPU and two Blackwell GPUs.', lesson: '/learn/infra/multi-gpu-parallelism-and-interconnect/' },
  { id: 'hyperparameter', term: 'Hyperparameter', short: 'A setting chosen before training, such as the learning rate, batch size or LoRA rank. Unlike a parameter, the training run does not learn it.', lesson: '/learn/llm/parameters-and-hyperparameters/' },
  { id: 'function-calling', term: 'Function calling', short: 'A model API feature where the model returns a structured request to call one of your functions. Your code validates it and runs it.', lesson: '/learn/rag-agents/the-tools-and-ecosystem/' },
  { id: 'agent-skill', term: 'Agent Skill', short: 'A folder with a SKILL.md file of instructions, plus optional scripts, that an agent loads only when a task needs it.', lesson: '/learn/rag-agents/the-tools-and-ecosystem/' },
  { id: 'temperature', term: 'Temperature', basic: true, short: 'A setting for how adventurous the model is when it picks the next token. Low is careful and repeatable. High is more varied and makes more mistakes.', lesson: '/learn/start/how-a-chatbot-answers/' },
  { id: 'throttling', term: 'Throttling', aka: ['rate limit', 'rate limiting', 'rate limits'], short: 'A service refusing or delaying requests because you exceeded your quota or it is overloaded. Usually returned as an HTTP 429 error.', lesson: '/learn/serving/life-of-a-request/' },
  { id: 'token', term: 'Token', basic: true, aka: ['tokens'], short: 'A small piece of text that a model reads and writes: a word or part of a word. Prices and limits are counted in tokens.', lesson: '/learn/foundations/tokens-and-embeddings/' },
  { id: 'tokenizer', term: 'Tokenizer', short: 'The component that splits text into tokens and maps each to a number. Different model families use different ones.', lesson: '/learn/foundations/tokens-and-embeddings/' },
  { id: 'tool-use', term: 'Tool use', aka: ['tool calling', 'function calling', 'tool call', 'tool calls'], short: 'Letting a model request that your code run a function, such as a search, and then using the result.', lesson: '/learn/rag-agents/agents-and-tool-use/' },
  { id: 'transformer', term: 'Transformer', short: 'The neural network design, built on attention, behind almost all modern language models.', lesson: '/learn/foundations/attention-intuition/' },
  { id: 'ttft', term: 'Time to first token', aka: ['TTFT'], short: 'How long you wait before the first piece of the answer arrives. It depends mostly on prompt length and model size.', lesson: '/learn/serving/life-of-a-request/' },
  { id: 'vector-search', term: 'Vector search', aka: ['vector database', 'vector store', 'nearest-neighbour search'], short: 'Finding the stored embeddings closest to a query’s embedding. The retrieval half of RAG.', lesson: '/learn/rag-agents/rag-from-scratch/' },

  // Wave 1 (Nov 2026): skills, classical ML, deep learning, responsible AI, audio
  { id: 'sampling-rate', term: 'sampling rate', basic: true, aka: ['sample rate', 'sampling frequency'], short: 'How many times a second a computer measures a sound. Speech models usually use 16,000 a second, and CDs use 44,100. It sets the highest pitch that can be kept.', lesson: '/learn/audio/how-a-computer-hears/' },
  { id: 'bit-depth', term: 'bit depth', basic: true, aka: ['bits per sample'], short: 'How finely each sample\'s height is measured. 16 bits allow 65,536 possible heights. Fewer bits give a rougher, steppier copy of the wave.', lesson: '/learn/audio/how-a-computer-hears/' },
  { id: 'nyquist-limit', term: 'Nyquist limit', basic: true, aka: ['Nyquist frequency'], short: 'The highest pitch a sampling rate can keep: half the rate. You need more than two samples per wave, so 16,000 samples a second keeps pitches up to 8,000 Hz.', lesson: '/learn/audio/how-a-computer-hears/' },
  { id: 'aliasing', term: 'aliasing', basic: true, short: 'The mistake when a sound is sampled too slowly: a high pitch is recorded as a wrong, lower one. It is like a wheel that seems to spin backwards in a film.', lesson: '/learn/audio/how-a-computer-hears/' },
  { id: 'pitch', term: 'pitch', basic: true, short: 'How high or low a sound seems. It is mostly set by the frequency of the wave: a faster wave sounds higher. Pitch and loudness are separate.', lesson: '/learn/audio/how-a-computer-hears/' },
  { id: 'amplitude', term: 'amplitude', basic: true, aka: ['loudness'], short: 'How tall a sound wave is. A taller wave pushes the air harder and sounds louder. It does not change the pitch.', lesson: '/learn/audio/how-a-computer-hears/' },
  { id: 'waveform', term: 'waveform', basic: true, aka: ['sound wave'], short: 'A picture of a sound drawn as a wavy line: how the air pressure, or the recorded signal, goes up and down over time.', lesson: '/learn/audio/how-a-computer-hears/' },
  { id: 'resampling', term: 'resampling', aka: ['sample rate conversion'], short: 'Changing a recording from one sampling rate to another, for example 48,000 to 16,000 a second, so every clip matches what a model expects.', lesson: '/learn/audio/how-a-computer-hears/' },
  { id: 'codec', term: 'codec', aka: ['audio codec'], short: 'A method that squeezes audio into fewer numbers so it is smaller to store or send, and expands it again for listening. Phone calls and music files use codecs.', lesson: '/learn/audio/how-a-computer-hears/' },
  { id: 'pure-tone', term: 'pure tone', aka: ['sine wave'], short: 'The smoothest possible wave, with one frequency and nothing else. Any real sound can be built by adding pure tones of different pitches and strengths.', lesson: '/learn/audio/spectrograms-and-the-mel-scale/' },
  { id: 'fourier-transform', term: 'Fourier transform', aka: ['FFT', 'fast Fourier transform'], short: 'A calculation that takes a stretch of sound and finds which pure tones it contains and how strong each is. The FFT is the fast way to compute it.', lesson: '/learn/audio/spectrograms-and-the-mel-scale/' },
  { id: 'spectrum', term: 'spectrum', aka: ['frequency spectrum'], short: 'A chart of how much energy a sound has at each frequency, found with a Fourier transform. A spectrogram is many spectra side by side.', lesson: '/learn/audio/spectrograms-and-the-mel-scale/' },
  { id: 'spectrogram', term: 'spectrogram', aka: ['sonogram'], short: 'A picture of sound with time across, frequency up, and brightness showing energy. It is made by taking a Fourier transform of many short, overlapping windows.', lesson: '/learn/audio/spectrograms-and-the-mel-scale/' },
  { id: 'analysis-window', term: 'analysis window', short: 'A short slice of sound, such as 25 ms, that is transformed at one time. Longer windows give sharper pitch but blurrier timing, and short windows the reverse.', lesson: '/learn/audio/spectrograms-and-the-mel-scale/' },
  { id: 'mel-scale', term: 'mel scale', short: 'A pitch scale built from listening tests, so equal steps sound like equal changes in pitch. It spreads out low frequencies and squeezes high ones, like hearing does.', lesson: '/learn/audio/spectrograms-and-the-mel-scale/' },
  { id: 'mel-spectrogram', term: 'mel spectrogram', aka: ['mel-spectrogram'], short: 'A spectrogram whose frequency rows are grouped into bands evenly spaced on the mel scale, giving fewer, ear-like rows. Many speech models read it.', lesson: '/learn/audio/spectrograms-and-the-mel-scale/' },
  { id: 'log-mel-spectrogram', term: 'log-mel spectrogram', aka: ['log mel features'], short: 'A mel spectrogram with the energies put on a logarithmic scale, which matches how loudness is heard. Whisper reads one with 80 bands (128 in large-v3).', lesson: '/learn/audio/spectrograms-and-the-mel-scale/' },
  { id: 'formant', term: 'formant', short: 'A band of frequencies that a voice\'s mouth and throat boost. The first two or three formants largely decide which vowel you hear, as in "ah" or "ee".', lesson: '/learn/audio/spectrograms-and-the-mel-scale/' },
  { id: 'harmonic', term: 'harmonic', aka: ['overtone'], short: 'A frequency that is a whole-number multiple of a sound\'s base pitch. A voice at 120 Hz also has energy at 240, 360 and 480 Hz, which show as stripes in a spectrogram.', lesson: '/learn/audio/spectrograms-and-the-mel-scale/' },
  { id: 'asr', term: 'ASR', exact: true, aka: ['automatic speech recognition', 'speech to text'], short: 'Short for automatic speech recognition: software that turns spoken audio into written text. Whisper is a well-known example.', lesson: '/learn/audio/spectrograms-and-the-mel-scale/' },
  { id: 'neuron', term: 'neuron', basic: true, aka: ['artificial neuron'], short: 'The basic part of a neural network: it multiplies each input by a weight, adds a bias, and passes the total through an activation function.', lesson: '/learn/deep-learning/inside-a-neural-network/' },
  { id: 'hidden-layer', term: 'hidden layer', basic: true, short: 'A layer between the input and the output of a network. Its numbers are not seen directly, and it is where the network builds its own features.', lesson: '/learn/deep-learning/inside-a-neural-network/' },
  { id: 'activation-function', term: 'activation function', basic: true, aka: ['nonlinearity'], short: 'A small function applied to each neuron\'s total, such as ReLU or tanh. Without it, a stack of layers is no more powerful than a single linear layer.', lesson: '/learn/deep-learning/inside-a-neural-network/' },
  { id: 'relu', term: 'ReLU', basic: true, aka: ['rectified linear unit'], short: 'An activation function that keeps positive numbers and turns negative ones into zero. Simple and fast, it is a common default in deep networks.', lesson: '/learn/deep-learning/inside-a-neural-network/' },
  { id: 'tanh', term: 'tanh', aka: ['hyperbolic tangent'], short: 'A smooth S-shaped activation function that squashes any number into the range from -1 to 1.', lesson: '/learn/deep-learning/inside-a-neural-network/' },
  { id: 'softmax', term: 'softmax', short: 'A function that turns a list of scores into probabilities that are all positive and add up to 1. A language model uses it to choose the next token.', lesson: '/learn/deep-learning/inside-a-neural-network/' },
  { id: 'forward-pass', term: 'forward pass', basic: true, aka: ['forward propagation'], short: 'Running an input through a network layer by layer to get its output, computing every value on the way.', lesson: '/learn/deep-learning/inside-a-neural-network/' },
  { id: 'parameter-count', term: 'parameter count', aka: ['number of weights and biases'], short: 'The total number of weights and biases in a model, found by adding weights times neurons and biases layer by layer. A network of 2 inputs, 4 hidden neurons and 1 output has 17.', lesson: '/learn/deep-learning/inside-a-neural-network/' },
  { id: 'vanishing-gradient', term: 'vanishing gradient', short: 'When gradients shrink towards zero as they travel back through many layers, so early layers barely learn. Caused by many small factors multiplying together.', lesson: '/learn/deep-learning/training-deep-networks/' },
  { id: 'exploding-gradient', term: 'exploding gradient', short: 'When gradients grow without limit as they travel back through many layers, so one step can throw the weights far off. Clipping and good initialisation help.', lesson: '/learn/deep-learning/training-deep-networks/' },
  { id: 'weight-initialisation', term: 'weight initialisation', aka: ['Xavier', 'He'], short: 'Choosing the random starting values of the weights. A well-chosen spread, such as Xavier or He, keeps the signal from shrinking or growing from layer to layer.', lesson: '/learn/deep-learning/training-deep-networks/' },
  { id: 'normalisation', term: 'normalisation', aka: ['normalization layer'], short: 'A layer that rescales numbers to a steady mean and spread inside a network, which makes deep networks easier to train. Batch norm, layer norm and RMSNorm are the main kinds.', lesson: '/learn/deep-learning/training-deep-networks/' },
  { id: 'batch-normalisation', term: 'batch normalisation', aka: ['batch norm'], short: 'Normalises each feature across the examples in a batch, then applies a learned scale and shift. It depends on batch size and uses saved averages at test time.', lesson: '/learn/deep-learning/training-deep-networks/' },
  { id: 'layer-normalisation', term: 'layer normalisation', aka: ['layer norm'], short: 'Normalises the features of one example on their own, so it does not depend on batch size. Transformers use it or its simpler cousin RMSNorm.', lesson: '/learn/deep-learning/training-deep-networks/' },
  { id: 'momentum', term: 'momentum', aka: ['SGD with momentum'], short: 'An optimiser trick that keeps a running velocity of past gradients, so steps along a steady direction build up and sideways jitter averages out.', lesson: '/learn/deep-learning/training-deep-networks/' },
  { id: 'adam', term: 'Adam', aka: ['Adam optimiser'], short: 'An optimiser that keeps running averages of each weight\'s gradient and squared gradient, and scales each step by them. It often works with little tuning and is a common default.', lesson: '/learn/deep-learning/training-deep-networks/' },
  { id: 'adamw', term: 'AdamW', aka: ['decoupled weight decay'], short: 'Adam with weight decay applied directly to the weights instead of through the gradient. It is the usual optimiser for training transformers.', lesson: '/learn/deep-learning/training-deep-networks/' },
  { id: 'weight-decay', term: 'weight decay', aka: ['L2 regularisation'], short: 'A regulariser that shrinks every weight slightly towards zero at each step, so large weights have to earn their place.', lesson: '/learn/deep-learning/training-deep-networks/' },
  { id: 'dropout', term: 'dropout', short: 'A regulariser that randomly switches off a fraction of neurons on each training step, so the network cannot rely on any one neuron. Nothing is dropped at test time.', lesson: '/learn/deep-learning/training-deep-networks/' },
  { id: 'learning-rate-warm-up', term: 'learning-rate warm-up', aka: ['warmup'], short: 'Starting training with a very small learning rate and raising it to its peak over the first steps. It avoids wrecking the early, random weights.', lesson: '/learn/deep-learning/training-deep-networks/' },
  { id: 'learning-rate-schedule', term: 'learning-rate schedule', aka: ['LR schedule', 'cosine decay'], short: 'A rule that changes the learning rate during a run, typically a short warm-up followed by a gradual decay such as a cosine curve.', lesson: '/learn/deep-learning/training-deep-networks/' },
  { id: 'gradient-clipping', term: 'gradient clipping', aka: ['clip gradients'], short: 'Scaling the gradient down when its overall size passes a limit, so one unlucky batch cannot make a huge, damaging weight update.', lesson: '/learn/deep-learning/training-deep-networks/' },
  { id: 'batch-size', term: 'batch size', aka: ['minibatch size'], short: 'The number of training examples used to compute one gradient step. Larger batches give steadier gradients but need more memory.', lesson: '/learn/deep-learning/training-deep-networks/' },
  { id: 'epoch', term: 'epoch', basic: true, short: 'One full pass through the whole training dataset. Small models often train for many epochs, while large language models often see most data only about once.', lesson: '/learn/deep-learning/training-deep-networks/' },
  { id: 'backpropagation', term: 'backpropagation', short: 'The method that computes the gradient of the loss for every weight in one backward sweep, using the chain rule from the output back to the inputs.', lesson: '/learn/deep-learning/backprop-from-scratch/' },
  { id: 'computational-graph', term: 'computational graph', aka: ['compute graph'], short: 'A diagram of a calculation as small operations, with a node for each result and arrows from the values it was made from. Backpropagation walks it backwards.', lesson: '/learn/deep-learning/backprop-from-scratch/' },
  { id: 'chain-rule', term: 'chain rule', short: 'The calculus rule that the rate of change of a result passing through stages is the product of each stage\'s own rate of change. It is the basis of backpropagation.', lesson: '/learn/deep-learning/backprop-from-scratch/' },
  { id: 'local-derivative', term: 'local derivative', aka: ['local gradient'], short: 'How much one operation\'s output changes when one input changes slightly. Addition has 1, multiplication has the other input\'s value, and tanh has 1 minus its output squared.', lesson: '/learn/deep-learning/backprop-from-scratch/' },
  { id: 'automatic-differentiation', term: 'automatic differentiation', aka: ['autodiff', 'autograd'], short: 'Software that records the operations in a calculation and computes exact gradients through them by the chain rule. PyTorch\'s autograd is the best-known example.', lesson: '/learn/deep-learning/backprop-from-scratch/' },
  { id: 'numerical-gradient', term: 'numerical gradient', aka: ['gradient check'], short: 'An estimate of a gradient made by nudging an input slightly up and down and dividing the change in output by the size of the nudge. Used to test backpropagation code.', lesson: '/learn/deep-learning/backprop-from-scratch/' },
  { id: 'convolution', term: 'convolution', basic: true, aka: ['convolutional layer', 'conv layer'], short: 'Sliding a small grid of weights over a picture and, at each position, multiplying and adding to get one number. The results form a feature map.', lesson: '/learn/deep-learning/how-computers-see/' },
  { id: 'feature-map', term: 'feature map', basic: true, aka: ['activation map'], short: 'The grid of numbers a filter produces as it slides over a picture. A big value marks a spot where the filter found its pattern.', lesson: '/learn/deep-learning/how-computers-see/' },
  { id: 'stride', term: 'stride', short: 'How many pixels a filter jumps each time it moves. Stride 2 skips every other position and makes the output about half the size.', lesson: '/learn/deep-learning/how-computers-see/' },
  { id: 'receptive-field', term: 'receptive field', short: 'The part of the original picture that can influence one cell in a feature map. It grows as layers are stacked, so deeper cells see bigger things.', lesson: '/learn/deep-learning/how-computers-see/' },
  { id: 'cnn', term: 'CNN', exact: true, aka: ['convolutional neural network'], short: 'A neural network built mainly from convolution layers, often with pooling and a plain layer at the end. Widely used for images and other grid-like data.', lesson: '/learn/deep-learning/how-computers-see/' },
  { id: 'resnet', term: 'ResNet', aka: ['residual network'], short: 'A family of deep networks built from residual blocks, introduced in 2015. The shortcuts let networks with over a hundred layers train well.', lesson: '/learn/deep-learning/how-computers-see/' },
  { id: 'residual-connection', term: 'residual connection', aka: ['skip connection', 'shortcut'], short: 'A shortcut that adds a block\'s input to its output, so the block only learns a correction. It keeps very deep networks trainable.', lesson: '/learn/deep-learning/how-computers-see/' },
  { id: 'intersection-over-union', term: 'intersection over union', aka: ['IoU'], short: 'A score for how well two boxes or masks match: the area they share divided by the area they cover together. 1 is a perfect match, 0 is no overlap.', lesson: '/learn/deep-learning/how-computers-see/' },
  { id: 'object-detection', term: 'object detection', basic: true, aka: ['detection'], short: 'Finding each object in a picture and drawing a box around it with a label, rather than giving one label to the whole picture.', lesson: '/learn/deep-learning/how-computers-see/' },
  { id: 'segmentation', term: 'segmentation', aka: ['image segmentation'], short: 'Labelling every pixel of a picture, for example which pixels are road, car or sky. Instance segmentation also separates one car from the next.', lesson: '/learn/deep-learning/how-computers-see/' },
  { id: 'diffusion-model', term: 'diffusion model', basic: true, aka: ['diffusion'], short: 'An image generator trained to remove noise. It starts from pure noise and cleans it up step by step, guided by a text prompt.', lesson: '/learn/deep-learning/diffusion-models/' },
  { id: 'denoising', term: 'denoising', basic: true, short: 'Removing noise from a picture or other data. A diffusion model is trained to predict the noise so it can be taken away a little at a time.', lesson: '/learn/deep-learning/diffusion-models/' },
  { id: 'forward-process', term: 'forward process', aka: ['noising process'], short: 'In diffusion, the step-by-step addition of noise to a real picture until only noise is left. It needs no learning.', lesson: '/learn/deep-learning/diffusion-models/' },
  { id: 'noise-schedule', term: 'noise schedule', short: 'The plan for how much noise is added at each step of the forward process. Early steps add little and later steps add more.', lesson: '/learn/deep-learning/diffusion-models/' },
  { id: 'latent-space', term: 'latent space', aka: ['latent representation'], short: 'A compressed, smaller form of a picture that a model works on instead of raw pixels. Latent diffusion denoises it and a decoder turns it back into a picture.', lesson: '/learn/deep-learning/diffusion-models/' },
  { id: 'guidance-scale', term: 'guidance scale', aka: ['CFG scale', 'classifier-free guidance'], short: 'A knob for how hard a generator follows the prompt. Higher values obey more but give less variety, and values that are too high can cause artefacts.', lesson: '/learn/deep-learning/diffusion-models/' },
  { id: 'sampler', term: 'sampler', aka: ['scheduler'], short: 'The rule that turns the network\'s noise guess into the next, cleaner picture, and chooses which steps to visit. It affects speed and quality.', lesson: '/learn/deep-learning/diffusion-models/' },
  { id: 'negative-prompt', term: 'negative prompt', short: 'Text describing what to steer away from. In common tools it replaces the empty prompt in the guidance step, so the image is pushed away from it.', lesson: '/learn/deep-learning/diffusion-models/' },
  { id: 'linear-regression', term: 'linear regression', basic: true, aka: ['least squares regression'], short: 'Fitting a straight line (or flat sheet) through data to predict a number from one or more inputs.', lesson: '/learn/ml/linear-and-logistic-regression/' },
  { id: 'regression', term: 'regression', basic: true, aka: ['numeric prediction'], short: 'A prediction task where the answer is a number, such as a mark, a price or a delivery time, rather than a category.', lesson: '/learn/ml/linear-and-logistic-regression/' },
  { id: 'residual', term: 'residual', basic: true, short: 'The real value minus the model\'s prediction for one example. Positive when the point sits above the line, negative when below.', lesson: '/learn/ml/linear-and-logistic-regression/' },
  { id: 'squared-error', term: 'squared error', basic: true, aka: ['sum of squared errors', 'SSE'], short: 'Each miss multiplied by itself and then added up, so misses above and below cannot cancel and large misses count much more.', lesson: '/learn/ml/linear-and-logistic-regression/' },
  { id: 'mean-squared-error', term: 'mean squared error', aka: ['MSE'], short: 'The average of the squared misses over all examples. Lower is better, and zero means every prediction was exact.', lesson: '/learn/ml/linear-and-logistic-regression/' },
  { id: 'least-squares', term: 'least squares', aka: ['ordinary least squares', 'OLS'], short: 'The rule that picks the line whose total squared error is the smallest. For one input there is a direct formula for it.', lesson: '/learn/ml/linear-and-logistic-regression/' },
  { id: 'slope', term: 'slope', basic: true, aka: ['gradient of the line', 'coefficient'], short: 'How much the prediction goes up for one extra unit of an input, for example marks gained per extra hour of revision.', lesson: '/learn/ml/linear-and-logistic-regression/' },
  { id: 'intercept', term: 'intercept', basic: true, short: 'The value the line predicts when every input is zero, where it crosses the up axis. It is the bias term of a neuron.', lesson: '/learn/ml/linear-and-logistic-regression/' },
  { id: 'coefficient', term: 'coefficient', aka: ['regression weight'], short: 'One fitted number multiplying an input in a linear model. It says how much the prediction moves per unit of that input, holding the others fixed.', lesson: '/learn/ml/linear-and-logistic-regression/' },
  { id: 'logistic-regression', term: 'logistic regression', aka: ['logit model'], short: 'A model for yes/no questions: a weighted sum of the inputs squashed by a sigmoid into a probability between 0 and 1.', lesson: '/learn/ml/linear-and-logistic-regression/' },
  { id: 'sigmoid', term: 'sigmoid', aka: ['logistic function'], short: 'An S-shaped function that turns any number into a value between 0 and 1: 0 maps to 0.5, large numbers towards 1, very negative ones towards 0.', lesson: '/learn/ml/linear-and-logistic-regression/' },
  { id: 'decision-threshold', term: 'decision threshold', basic: true, aka: ['cut-off', 'classification threshold'], short: 'The probability above which a model says yes. 0.5 is a common default, but the best value depends on the cost of each kind of mistake.', lesson: '/learn/ml/linear-and-logistic-regression/' },
  { id: 'decision-boundary', term: 'decision boundary', aka: ['separating line'], short: 'The place where a classifier switches its answer. With one input it is a point on the axis, with two a line, with more a flat sheet.', lesson: '/learn/ml/linear-and-logistic-regression/' },
  { id: 'log-loss', term: 'log loss', aka: ['cross-entropy', 'logistic loss'], short: 'The loss for probabilities: minus the log of the probability given to what really happened. Confident wrong answers cost a lot.', lesson: '/learn/ml/linear-and-logistic-regression/' },
  { id: 'decision-tree', term: 'decision tree', basic: true, aka: ['classification tree', 'regression tree'], short: 'A model that predicts by asking a chain of yes/no questions about the inputs, learned from labelled examples. Each leaf gives an answer.', lesson: '/learn/ml/decision-trees-and-random-forests/' },
  { id: 'impurity', term: 'impurity', aka: ['node impurity'], short: 'A number for how mixed the classes are in a group. It is 0 when the group is all one class and highest when classes are evenly mixed.', lesson: '/learn/ml/decision-trees-and-random-forests/' },
  { id: 'gini-impurity', term: 'Gini impurity', aka: ['Gini index'], short: 'A common impurity score: 1 minus the sum of squared class shares. A 50/50 two-class group scores 0.5 and a pure group scores 0.', lesson: '/learn/ml/decision-trees-and-random-forests/' },
  { id: 'entropy', term: 'entropy', aka: ['information entropy'], short: 'An impurity score measured in bits: 0 for a pure group and 1 bit for an even two-class mix. Splits are chosen to lower it.', lesson: '/learn/ml/decision-trees-and-random-forests/' },
  { id: 'pruning', term: 'pruning', aka: ['tree pruning'], short: 'Cutting back branches of a grown tree that do not help on held-out data, so the tree is simpler and overfits less.', lesson: '/learn/ml/decision-trees-and-random-forests/' },
  { id: 'bagging', term: 'bagging', aka: ['bootstrap aggregating'], short: 'Training many models on random resamples of the rows, drawn with replacement, then averaging or voting their answers to lower variance.', lesson: '/learn/ml/decision-trees-and-random-forests/' },
  { id: 'bootstrap-sample', term: 'bootstrap sample', aka: ['resample with replacement'], short: 'A new dataset the same size as the original, built by picking rows at random with replacement. About 37% of rows are left out of each.', lesson: '/learn/ml/decision-trees-and-random-forests/' },
  { id: 'random-forest', term: 'random forest', aka: ['RF'], short: 'Many decision trees, each grown on a bootstrap sample with a random subset of inputs considered at each split, voting together.', lesson: '/learn/ml/decision-trees-and-random-forests/' },
  { id: 'out-of-bag-error', term: 'out-of-bag error', aka: ['OOB score'], short: 'An accuracy estimate from a forest where each row is predicted only by the trees that did not see it, so no data is set aside.', lesson: '/learn/ml/decision-trees-and-random-forests/' },
  { id: 'feature-importance', term: 'feature importance', aka: ['variable importance'], short: 'A score for how much each input contributed to a tree model. The impurity-based kind comes from training data and favours inputs with many values.', lesson: '/learn/ml/decision-trees-and-random-forests/' },
  { id: 'permutation-importance', term: 'permutation importance', aka: ['shuffle importance'], short: 'How much a model\'s score drops on held-out data when one input\'s values are shuffled. A safer check than impurity-based importance.', lesson: '/learn/ml/decision-trees-and-random-forests/' },
  { id: 'boosting', term: 'boosting', aka: ['gradient boosting', 'GBDT'], short: 'Building a model from many small trees in sequence, each fitted to the mistakes (residuals) left by the ones before it.', lesson: '/learn/ml/gradient-boosting/' },
  { id: 'stump', term: 'stump', aka: ['decision stump'], short: 'A tree with a single question and two leaves. The smallest tree, often used as the weak learner in a first boosting example.', lesson: '/learn/ml/gradient-boosting/' },
  { id: 'learning-rate', term: 'learning rate', aka: ['shrinkage'], short: 'The fraction of each new tree that is added in boosting (or the step size in gradient descent). Smaller needs more rounds but is more cautious.', lesson: '/learn/ml/gradient-boosting/' },
  { id: 'early-stopping', term: 'early stopping', aka: ['patience'], short: 'Stopping training when the validation score has not improved for a set number of rounds, then keeping the best round.', lesson: '/learn/ml/gradient-boosting/' },
  { id: 'xgboost', term: 'XGBoost', aka: ['extreme gradient boosting'], short: 'A widely used gradient boosting library, described in a 2016 paper, with regularised trees, handling of sparse data and fast training.', lesson: '/learn/ml/gradient-boosting/' },
  { id: 'lightgbm', term: 'LightGBM', aka: ['light gradient boosting machine'], short: 'A gradient boosting library that bins values into histograms and grows trees leaf-wise, splitting the leaf that lowers loss most.', lesson: '/learn/ml/gradient-boosting/' },
  { id: 'catboost', term: 'CatBoost', aka: ['categorical boosting'], short: 'A gradient boosting library designed around categorical inputs, using ordered boosting to reduce a form of target leakage.', lesson: '/learn/ml/gradient-boosting/' },
  { id: 'bias-in-ai', term: 'bias (in AI)', basic: true, aka: ['AI bias', 'algorithmic bias'], short: 'When an AI system works better for some groups of people than for others, usually because of the examples it learned from or how it was built, not because anyone wanted that.', lesson: '/learn/responsible/when-examples-are-unfair/' },
  { id: 'training-examples', term: 'training examples', basic: true, aka: ['training data', 'examples'], short: 'The examples a computer learns from. If they are lopsided or leave some groups out, what it learns will be lopsided too.', lesson: '/learn/responsible/when-examples-are-unfair/' },
  { id: 'label', term: 'label', basic: true, aka: ['ground truth'], short: 'The right answer attached to an example, such as "star" or "heart". If people made unfair choices when labelling, the computer can copy them.', lesson: '/learn/responsible/when-examples-are-unfair/' },
  { id: 'representation-bias', term: 'representation bias', aka: ['missing groups', 'unrepresentative data'], short: 'A problem where some groups are rare or missing in the training examples, so a system does worse on them.', lesson: '/learn/responsible/when-examples-are-unfair/' },
  { id: 'per-group-accuracy', term: 'per-group accuracy', aka: ['accuracy by group', 'disaggregated evaluation'], short: 'Scoring a system separately for each group, not just overall, because one overall number can hide a group it does badly on.', lesson: '/learn/responsible/when-examples-are-unfair/' },
  { id: 'proxy-variable', term: 'proxy variable', short: 'A piece of information that stands in for something else, such as a postcode standing in for a person\'s background, so a system can be unfair without using the sensitive trait directly.', lesson: '/learn/responsible/when-examples-are-unfair/' },
  { id: 'feedback-loop', term: 'feedback loop', short: 'When a system\'s output changes the data it later learns from, so a small unfairness can grow over time.', lesson: '/learn/responsible/when-examples-are-unfair/' },
  { id: 'fairness-criteria', term: 'fairness criteria', aka: ['demographic parity', 'equal opportunity', 'calibration'], short: 'Different, precise ways of saying a system is fair to groups. Except in special cases they cannot all be true at once, so people must choose and explain.', lesson: '/learn/responsible/when-examples-are-unfair/' },
  { id: 'misinformation', term: 'misinformation', basic: true, aka: ['false information', 'fake news'], short: 'False or misleading information that spreads, whether or not the person sharing it knows it is wrong.', lesson: '/learn/responsible/real-or-fake/' },
  { id: 'deepfake', term: 'deepfake', basic: true, aka: ['fake video', 'fake voice'], short: 'A picture, video or voice made or changed by AI to look or sound like a real person doing or saying something they did not.', lesson: '/learn/responsible/real-or-fake/' },
  { id: 'lateral-reading', term: 'lateral reading', basic: true, short: 'Checking a source by leaving its page and opening new tabs to see what other trusted places say about it. Fact-checkers do this.', lesson: '/learn/responsible/real-or-fake/' },
  { id: 'reverse-image-search', term: 'reverse image search', basic: true, short: 'A search that starts from a picture instead of words, to find where else it has appeared and whether an older or original copy exists.', lesson: '/learn/responsible/real-or-fake/' },
  { id: 'watermark', term: 'watermark', basic: true, aka: ['AI watermark', 'SynthID'], short: 'A hidden mark added to a picture, sound or text when an AI makes it, which a computer can sometimes detect. It can be missing or removed, so it is only one clue.', lesson: '/learn/responsible/real-or-fake/' },
  { id: 'content-credentials', term: 'content credentials', basic: true, aka: ['C2PA', 'provenance'], short: 'A signed record attached to a file that says how it was made and edited. It shows where a file came from, not whether what it shows is true.', lesson: '/learn/responsible/real-or-fake/' },
  { id: 'provenance', term: 'provenance', aka: ['origin', 'source history'], short: 'The history of where something came from and how it has been changed, which helps people decide how far to trust it.', lesson: '/learn/responsible/real-or-fake/' },
  { id: 'c2pa', term: 'C2PA', exact: true, aka: ['Coalition for Content Provenance and Authenticity'], short: 'An open standard for attaching signed, tamper-evident records of how a file was made to pictures, audio and video.', lesson: '/learn/responsible/real-or-fake/' },
  { id: 'voice-cloning', term: 'voice cloning', basic: true, aka: ['voice clone', 'AI voice'], short: 'Using AI to copy how a real person sounds from a short recording, which scammers can use to fake calls from someone you know.', lesson: '/learn/responsible/real-or-fake/' },
  { id: 'family-safe-word', term: 'family safe word', basic: true, aka: ['code word', 'safe word'], short: 'A secret word a family agrees on in person, to check that a worrying call or message really comes from them. Never post it online.', lesson: '/learn/responsible/real-or-fake/' },
  { id: 'private-information', term: 'private information', basic: true, aka: ['personal information', 'personal details'], short: 'Facts that can tell a stranger who you are or how to find you, such as your full name, school, address, phone number, passwords and photos of you or your friends.', lesson: '/learn/responsible/ai-and-your-private-life/' },
  { id: 'noticeboard-test', term: 'noticeboard test', basic: true, short: 'A quick check before you type something into a chatbot: would you pin it on the school noticeboard for everyone to read? If not, keep it out of the chat.', lesson: '/learn/responsible/ai-and-your-private-life/' },
  { id: 'chat-history', term: 'chat history', basic: true, aka: ['saved chats'], short: 'A list of your past chats that an app stores so you can return to them. It also means the company keeps a copy, so check how long and who can see it.', lesson: '/learn/responsible/ai-and-your-private-life/' },
  { id: 'privacy-settings', term: 'privacy settings', basic: true, aka: ['privacy controls'], short: 'Switches in an app that decide what it stores and shares, such as whether your chats are saved or used to improve its AI. Defaults differ between apps.', lesson: '/learn/responsible/ai-and-your-private-life/' },
  { id: 'human-review', term: 'human review', basic: true, aka: ['chat review'], short: 'When trained people at a company read a small sample of chats to check quality and safety. Some apps say they do this, so do not type anything you would not want a reviewer to see.', lesson: '/learn/responsible/ai-and-your-private-life/' },
  { id: 'memorisation', term: 'memorisation', aka: ['data memorisation'], short: 'When a model repeats text that was in its training data. It is rare, but it is one reason not to put sensitive details into a chatbot.', lesson: '/learn/responsible/ai-and-your-private-life/' },
  { id: 'ai-companion', term: 'AI companion', basic: true, aka: ['companion chatbot', 'social chatbot'], short: 'A chatbot designed to act like a friend or partner and keep you chatting. It is still a program that does not feel or truly remember you, and experts advise care for under-18s.', lesson: '/learn/responsible/ai-and-your-private-life/' },
  { id: 'study-buddy', term: 'study buddy', basic: true, aka: ['AI tutor use'], short: 'Using AI to help you learn by explaining, quizzing you or checking your reasoning, while you do the thinking and write the answers yourself.', lesson: '/learn/responsible/ai-and-school/' },
  { id: 'academic-integrity', term: 'academic integrity', basic: true, aka: ['honest schoolwork'], short: 'Doing and handing in work that is truly your own, and being open about any help you had, including help from AI, as your school\'s rules require.', lesson: '/learn/responsible/ai-and-school/' },
  { id: 'ai-use-note', term: 'AI use note', basic: true, aka: ['AI disclosure', 'AI statement'], short: 'A short line saying how you used AI in a piece of work, for example: I used AI to quiz me and check my spelling, and I wrote the answers myself.', lesson: '/learn/responsible/ai-and-school/' },
  { id: 'prompt-makeover', term: 'prompt makeover', basic: true, aka: ['prompt rewrite'], short: 'Improving a vague prompt by adding a clear task, who it is for, a shape or example, and a request for steps, so the answer is more useful.', lesson: '/learn/responsible/ai-and-school/' },
  { id: 'ai-agent', term: 'AI agent', basic: true, short: 'A program that uses an AI model to work towards a goal. Unlike a plain chatbot, it can use tools and take actions, looping through think, act and look at the result.', lesson: '/learn/start/what-is-an-ai-agent/' },
  { id: 'agent-loop', term: 'agent loop', basic: true, aka: ['think-act-observe loop'], short: 'The repeating cycle of an agent: think about the next step, act by using a tool, look at the result, then think again until the job is done or a limit is reached.', lesson: '/learn/start/what-is-an-ai-agent/' },
  { id: 'python', term: 'Python', basic: true, short: 'A programming language, very widely used for AI work because it is readable and has many libraries for data and models.', lesson: '/learn/skills/python-first-steps/' },
  { id: 'error-message', term: 'Error message', basic: true, aka: ['traceback', 'exception'], short: 'What Python prints when it cannot continue. Its last line names the kind of error, and the line number says where to look.', lesson: '/learn/skills/python-first-steps/' },
  { id: 'pyodide', term: 'Pyodide', short: 'A copy of Python compiled to run inside a web browser, so code in a lesson can run on your own device without a server.', lesson: '/learn/skills/python-first-steps/' },
  { id: 'bag-of-words', term: 'Bag of words', basic: true, aka: ['word counts'], short: 'A way to turn text into numbers by counting how often each word appears and ignoring the order of the words.', lesson: '/learn/skills/your-first-model/' },
  { id: 'naive-bayes', term: 'Naive Bayes', short: 'A simple classifier that learns from counts: each word votes for a label by how often it appeared with that label, as if words did not affect each other.', lesson: '/learn/skills/your-first-model/' },
  { id: 'classifier', term: 'Classifier', basic: true, short: 'A model that puts each example into one of a fixed set of groups, such as spam or not spam.', lesson: '/learn/skills/your-first-model/' },
  { id: 'additive-smoothing', term: 'Additive smoothing', aka: ['add-one smoothing', 'Laplace smoothing'], short: 'Adding a small amount, often 1, to every count so a word never seen with a label does not make its whole score zero.', lesson: '/learn/skills/your-first-model/' },
  { id: 'peeking-at-the-test-set', term: 'Peeking at the test set', aka: ['test-set leakage'], short: 'Letting the test examples influence what you build, for instance by fixing the exact mistakes you saw there. The test score then looks better than it should.', lesson: '/learn/skills/your-first-model/' },
  { id: 'supervised-learning', term: 'Supervised learning', basic: true, aka: ['learning from labels', 'labelled learning'], short: 'Learning from examples that come with the right answers. The computer compares its guess with the answer and improves, like a student checking work against a teacher\'s marks.', lesson: '/learn/start/three-ways-machines-learn/' },
  { id: 'unsupervised-learning', term: 'Unsupervised learning', basic: true, aka: ['learning without labels'], short: 'Learning from examples that have no right answers attached. The computer looks for patterns by itself, such as groups of similar things, and people decide what the groups mean.', lesson: '/learn/start/three-ways-machines-learn/' },
  { id: 'clustering', term: 'Clustering', basic: true, aka: ['cluster', 'group finding'], short: 'Sorting things into groups so that items in a group are more alike than items in other groups. It needs no labels, and you usually choose how many groups to look for.', lesson: '/learn/start/three-ways-machines-learn/' },
  { id: 'reinforcement-learning', term: 'Reinforcement learning', basic: true, aka: ['RL', 'learning from rewards'], short: 'Learning by trying actions and getting rewards or penalties. The learner slowly discovers which actions earn the most points over time, with no one showing it the right move.', lesson: '/learn/start/three-ways-machines-learn/' },
  { id: 'reward', term: 'Reward', basic: true, aka: ['reward signal', 'points'], short: 'A score that tells a learner how well it just did. Positive rewards encourage what it did, and negative ones discourage it. The choice of reward strongly shapes what is learned.', lesson: '/learn/start/three-ways-machines-learn/' },
  { id: 'self-supervised-learning', term: 'Self-supervised learning', aka: ['self supervised'], short: 'Learning where the labels come from the data itself. A chatbot hides the next word in a text and tries to guess it, so no person has to write the answers.', lesson: '/learn/start/three-ways-machines-learn/' },
  { id: 'k-means', term: 'k-means', aka: ['k means clustering'], short: 'A simple clustering method. Pick k centres, put every item with its nearest centre, move each centre to the middle of its group, and repeat until nothing changes.', lesson: '/learn/start/three-ways-machines-learn/' },
  { id: 'k-nearest-neighbours', term: 'k-nearest neighbours', aka: ['kNN', 'nearest neighbour'], short: 'A way to label a new item by finding the k most similar labelled examples and taking a vote. There is no training step, only a comparison with stored examples.', lesson: '/learn/start/three-ways-machines-learn/' },
  { id: 'q-learning', term: 'Q-learning', aka: ['tabular Q-learning'], short: 'A reinforcement learning method that keeps a score for each action in each situation. After every move it nudges that score towards the reward received plus what looks best next.', lesson: '/learn/start/three-ways-machines-learn/' },
  { id: 'rule-based-system', term: 'Rule-based system', basic: true, aka: ['rule based', 'if-then rules'], short: 'A program that decides by following rules written by people, such as "if it is rainy, take an umbrella". It is easy to check but fails on cases nobody wrote a rule for.', lesson: '/learn/start/computers-that-decide-and-plan/' },
  { id: 'expert-system', term: 'Expert system', aka: ['expert systems'], short: 'An older kind of AI that reasons over a large set of if-then rules written down by human experts. They were widely used in the 1980s, before neural networks took over many jobs.', lesson: '/learn/start/computers-that-decide-and-plan/' },
  { id: 'game-tree', term: 'Game tree', basic: true, aka: ['look-ahead tree', 'search tree'], short: 'A diagram of every way a game could go: each position branches into the moves available from it. A computer can read the tree to pick a move that leads to a win.', lesson: '/learn/start/computers-that-decide-and-plan/' },
  { id: 'minimax', term: 'Minimax', aka: ['min-max', 'minimax search'], short: 'A search method for two-player games. A player picks the move whose worst-case outcome is best, assuming the opponent also plays as well as they can.', lesson: '/learn/start/computers-that-decide-and-plan/' },

  // Wave 1 (Nov 2026): skills, classical ML, deep learning, responsible AI, audio
  { id: 'missing-value', term: 'missing value', basic: true, aka: ['NaN'], short: 'A cell in a table with no value recorded. Models usually cannot use it as it is, so you drop the row, fill the blank with a typical value, or fill it and add a flag.', lesson: '/learn/ml/getting-data-ready/' },
  { id: 'imputation', term: 'imputation', aka: ['filling blanks'], short: 'Filling a missing value with a typical one, such as the average or the median, worked out from the training rows only.', lesson: '/learn/ml/getting-data-ready/' },
  { id: 'outlier', term: 'outlier', basic: true, aka: ['extreme value'], short: 'A value far from the rest. It may be a typing error to fix, or a real unusual case to keep, and it can drag averages and straight-line fits a long way.', lesson: '/learn/ml/getting-data-ready/' },
  { id: 'placeholder-value', term: 'placeholder value', aka: ['sentinel value'], short: 'A number typed in to mean unknown, such as 999 or -1. The model reads it as a real value, so turn it into a proper blank before training.', lesson: '/learn/ml/getting-data-ready/' },
  { id: 'feature', term: 'feature', basic: true, aka: ['column', 'input variable'], short: 'One measurable input to a model, such as the size of a house. Each row of a table becomes a list of feature values the model learns from.', lesson: '/learn/ml/getting-data-ready/' },
  { id: 'feature-engineering', term: 'feature engineering', aka: ['building features'], short: 'Making new columns from existing ones, such as a ratio, an age worked out from dates, or a formula from the problem, so the pattern is easier for the model to find.', lesson: '/learn/ml/getting-data-ready/' },
  { id: 'one-hot-encoding', term: 'one-hot encoding', aka: ['dummy variables'], short: 'Turning a category into one yes-or-no column per value, so a house in Brook becomes Abbey 0, Brook 1, Castle 0, Dale 0. It adds no false order between categories.', lesson: '/learn/ml/getting-data-ready/' },
  { id: 'normalisation-scaling', term: 'normalisation (scaling)', aka: ['standardisation', 'min-max scaling'], short: 'Rescaling number columns to comparable ranges, for example 0 to 1. It matters for distance-based models and gradient descent, and not for decision trees.', lesson: '/learn/ml/getting-data-ready/' },
  { id: 'target-encoding', term: 'target encoding', aka: ['mean encoding'], short: 'Replacing a category with the average answer for that category. It uses the answer column, so it leaks unless computed from the training rows only.', lesson: '/learn/ml/getting-data-ready/' },
  { id: 'data-pipeline', term: 'data pipeline', aka: ['preprocessing pipeline'], short: 'A fixed chain of preparation steps and a model, fitted on the training data and applied unchanged to new data, so no step can learn from the test set.', lesson: '/learn/ml/getting-data-ready/' },
  { id: 'label-noise', term: 'label noise', aka: ['wrong labels'], short: 'Mistakes or disagreements in the answer column. They put a ceiling on how well any model can score, so check a sample of labels by hand.', lesson: '/learn/ml/getting-data-ready/' },
  { id: 'underfitting', term: 'underfitting', basic: true, aka: ['high bias fit'], short: 'A model too simple for the pattern. Both training and test error are high, and more data does not fix it; a more flexible model or better features can.', lesson: '/learn/ml/overfitting-and-bias-variance/' },
  { id: 'bias-of-a-model', term: 'bias (of a model)', aka: ['systematic error'], short: 'Error from a model being wrong in the same way every time, usually because it is too simple, like a straight line fitted to a wave.', lesson: '/learn/ml/overfitting-and-bias-variance/' },
  { id: 'variance-of-a-model', term: 'variance (of a model)', aka: ['sensitivity to the sample'], short: 'How much a fitted model changes when it is trained on a different sample of data. A very flexible model has high variance and fits the noise.', lesson: '/learn/ml/overfitting-and-bias-variance/' },
  { id: 'bias-variance-trade-off', term: 'bias-variance trade-off', short: 'Making a model more flexible lowers bias but raises variance. The best model sits where their sum, plus the noise nobody can remove, is lowest.', lesson: '/learn/ml/overfitting-and-bias-variance/' },
  { id: 'irreducible-error', term: 'irreducible error', aka: ['noise floor'], short: 'The random scatter in the data that no model can predict. Test error cannot fall far below it, so chasing it means fitting noise.', lesson: '/learn/ml/overfitting-and-bias-variance/' },
  { id: 'regularisation', term: 'regularisation', aka: ['weight penalty'], short: 'Holding a model back so it cannot chase noise, for example by charging it for large weights. Ridge shrinks weights smoothly; lasso pushes some to exactly zero.', lesson: '/learn/ml/overfitting-and-bias-variance/' },
  { id: 'cross-validation', term: 'cross-validation', aka: ['k-fold cross-validation'], short: 'Splitting the training data into parts, training on all but one and scoring on that one, then rotating. The average score is a steadier guide than a single split.', lesson: '/learn/ml/overfitting-and-bias-variance/' },
  { id: 'learning-curve', term: 'learning curve', short: 'A plot of training and test error against the number of training examples. It shows whether you need more data or a different model.', lesson: '/learn/ml/overfitting-and-bias-variance/' },
  { id: 'double-descent', term: 'double descent', short: 'The finding that in very large models, test error can fall again after the point where the model fits the training data exactly, unlike the classic U shape.', lesson: '/learn/ml/overfitting-and-bias-variance/' },
  { id: 'sample-size', term: 'sample size', basic: true, aka: ['N', 'number of test cases'], short: 'How many cases a score is measured on. Uncertainty shrinks with the square root of it, so four times the cases halves the width of the range.', lesson: '/learn/ml/is-the-difference-real/' },
  { id: 'standard-error', term: 'standard error', short: 'How much a measured score would typically wobble if you drew a different sample. For a pass rate p on n cases it is the square root of p times (1 - p), over n.', lesson: '/learn/ml/is-the-difference-real/' },
  { id: 'bootstrap', term: 'bootstrap', short: 'Estimating how much a score varies by drawing many samples with replacement from your own data and recomputing the score each time.', lesson: '/learn/ml/is-the-difference-real/' },
  { id: 'confidence-interval', term: 'confidence interval', aka: ['CI'], short: 'A range for the true value built so that, over many repeats of the experiment, about 95 percent of such ranges would contain it.', lesson: '/learn/ml/is-the-difference-real/' },
  { id: 'paired-comparison', term: 'paired comparison', aka: ['paired test'], short: 'Comparing two models on the same cases and looking at the case-by-case differences. It removes shared difficulty and gives a tighter interval.', lesson: '/learn/ml/is-the-difference-real/' },
  { id: 'a-b-test', term: 'A/B test', basic: true, aka: ['split test', 'controlled experiment'], short: 'Showing two versions to randomly chosen groups of users and comparing an outcome. Random assignment spreads other differences evenly across both groups.', lesson: '/learn/ml/is-the-difference-real/' },
  { id: 'p-value', term: 'p-value', short: 'How often a gap at least this big would appear by chance if there were really no difference. It is not the chance that B is better, and it says nothing about size.', lesson: '/learn/ml/is-the-difference-real/' },
  { id: 'effect-size', term: 'effect size', aka: ['size of the difference'], short: 'How big a difference is, in units people care about, such as 3 more passes per 100. Report it with its interval rather than only whether it is significant.', lesson: '/learn/ml/is-the-difference-real/' },
  { id: 'multiple-comparisons', term: 'multiple comparisons', aka: ['multiple testing'], short: 'Running many comparisons raises the chance that one looks like a winner by luck: twenty tries at the 5 percent level give about a 64 percent chance of a false alarm.', lesson: '/learn/ml/is-the-difference-real/' },
  { id: 'statistical-power', term: 'statistical power', short: 'The chance that a test catches a real difference of a given size. It rises with more cases and a larger gap, and is used to plan how many cases are needed.', lesson: '/learn/ml/is-the-difference-real/' },
  { id: 'base-rate', term: 'base rate', basic: true, aka: ['prevalence'], short: 'How common something is before any test result. When it is rare, most positive results are false alarms: with a 1 percent base rate, about 9 of 108 positives are real.', lesson: '/learn/ml/is-the-difference-real/' },

  // Wave 1 (Nov 2026): skills, classical ML, deep learning, responsible AI, audio
  { id: 'tool-description', term: 'Tool description', aka: ['tool spec', 'tool schema'], short: 'The name, plain-language description and parameter schema a model reads to decide whether and how to call a tool. They are loaded into its context, so they work as prompt text.', lesson: '/learn/rag-agents/designing-tools-for-agents/' },
  { id: 'poka-yoke', term: 'Poka-yoke', aka: ['mistake-proofing'], short: 'Designing an interface so that mistakes are hard to make, for example by requiring absolute file paths or using enums. Anthropic applies the idea to the arguments of agent tools.', lesson: '/learn/rag-agents/designing-tools-for-agents/' },
  { id: 'tool-namespacing', term: 'Tool namespacing', aka: ['tool prefixes'], short: 'Grouping related tools under a common prefix, such as asana_search and jira_search, so a model can tell overlapping tools apart when many are available.', lesson: '/learn/rag-agents/designing-tools-for-agents/' },
  { id: 'response-format-parameter', term: 'Response format parameter', aka: ['concise or detailed responses'], short: 'A tool parameter that lets the model choose how much a result returns, such as concise or detailed, so it only pays for identifiers and fields when it needs them.', lesson: '/learn/rag-agents/designing-tools-for-agents/' },
  { id: 'tool-execution-error', term: 'Tool execution error', aka: ['isError result'], short: 'A failure reported inside a tool result, such as invalid input or an API failure, so the model can read the message and retry. MCP marks it with isError true and separates it from protocol errors.', lesson: '/learn/rag-agents/designing-tools-for-agents/' },
  { id: 'idempotency-key', term: 'Idempotency key', aka: ['idempotent request'], short: 'A unique value sent with a request so that a retry returns the first result instead of repeating the action. It keeps a retried refund or booking from happening twice.', lesson: '/learn/rag-agents/designing-tools-for-agents/' },
  { id: 'tool-annotations', term: 'Tool annotations', aka: ['readOnlyHint', 'destructiveHint'], short: 'MCP hints that describe a tool, such as whether it is read-only, destructive, idempotent or open-world. They are hints only and clients must treat them as untrusted unless the server is trusted.', lesson: '/learn/rag-agents/designing-tools-for-agents/' },
  { id: 'tool-search', term: 'Tool search', aka: ['dynamic tool loading', 'deferred tools'], short: 'A pattern where the model searches a catalogue and only the definitions it needs are loaded into context, which saves tokens and keeps selection accurate when there are many tools.', lesson: '/learn/rag-agents/designing-tools-for-agents/' },
  { id: 'context-engineering', term: 'Context engineering', aka: ['context curation'], short: 'Choosing what tokens enter the model\'s context at each step: system prompt, tools, retrieved data, history and notes. It extends prompt engineering to whole agent runs.', lesson: '/learn/rag-agents/agent-memory-and-context-engineering/' },
  { id: 'context-rot', term: 'Context rot', aka: ['long-context degradation'], short: 'The tendency for a model\'s recall and accuracy to fall as the amount of text in its context grows, even when the text fits in the window.', lesson: '/learn/rag-agents/agent-memory-and-context-engineering/' },
  { id: 'compaction', term: 'Compaction', aka: ['context summarisation'], short: 'Summarising a conversation that is nearing the window limit and continuing from the summary. It keeps a long run going but can lose details that only matter later.', lesson: '/learn/rag-agents/agent-memory-and-context-engineering/' },
  { id: 'tool-result-clearing', term: 'Tool result clearing', aka: ['context editing'], short: 'Removing old raw tool outputs from the history once the agent no longer needs them. It is one of the lightest forms of context compaction.', lesson: '/learn/rag-agents/agent-memory-and-context-engineering/' },
  { id: 'structured-note-taking', term: 'Structured note-taking', aka: ['agentic memory', 'scratchpad file'], short: 'The agent regularly writes notes, such as a to-do list or NOTES.md, outside the context window and reads them back later to keep track of long tasks.', lesson: '/learn/rag-agents/agent-memory-and-context-engineering/' },
  { id: 'episodic-memory', term: 'Episodic memory', aka: ['past-experience memory'], short: 'Stored records of what an agent did or saw in earlier sessions, often reused as examples. It sits beside semantic memory (facts) and procedural memory (instructions).', lesson: '/learn/rag-agents/agent-memory-and-context-engineering/' },
  { id: 'semantic-memory', term: 'Semantic memory', aka: ['fact memory'], short: 'Stored facts and concepts an agent keeps about a user or domain, such as preferences. It is a type of memory, not the same as semantic search, which is a retrieval method.', lesson: '/learn/rag-agents/agent-memory-and-context-engineering/' },
  { id: 'just-in-time-retrieval', term: 'Just-in-time retrieval', aka: ['lazy context loading'], short: 'Keeping lightweight references such as file paths or queries and loading the content with tools only when needed, instead of putting everything in the context up front.', lesson: '/learn/rag-agents/agent-memory-and-context-engineering/' },
  { id: 'memory-poisoning', term: 'Memory poisoning', aka: ['memory injection'], short: 'An attack or accident in which wrong or malicious content is written into an agent\'s long-term memory or knowledge base and then influences later sessions.', lesson: '/learn/rag-agents/agent-memory-and-context-engineering/' },
  { id: 'multi-agent-system', term: 'Multi-agent system', aka: ['multi-agent architecture'], short: 'A system in which several LLM agents, each using tools in a loop, work together on one task instead of a single agent doing all of it.', lesson: '/learn/rag-agents/multi-agent-systems/' },
  { id: 'evaluator-optimiser', term: 'Evaluator-optimiser', aka: ['generate and critique loop'], short: 'A pattern in which one model call writes an answer, another checks it against criteria and sends feedback, and the writer revises.', lesson: '/learn/rag-agents/multi-agent-systems/' },
  { id: 'hand-off', term: 'Hand-off', aka: ['handoff', 'decentralised pattern'], short: 'Passing control of a conversation, with its state, from one agent to another specialist, which then carries on as the active agent.', lesson: '/learn/rag-agents/multi-agent-systems/' },
  { id: 'agent2agent-protocol', term: 'Agent2Agent protocol', aka: ['A2A'], short: 'An open protocol for communication between independent, opaque agents built by different vendors, using agent cards, tasks and messages.', lesson: '/learn/rag-agents/multi-agent-systems/' },
  { id: 'agent-card', term: 'Agent Card', aka: ['A2A agent card'], short: 'A JSON document in which an A2A agent describes its identity, skills, endpoint and authentication needs so that other agents can discover it.', lesson: '/learn/rag-agents/multi-agent-systems/' },
  { id: 'agentic-ai-foundation', term: 'Agentic AI Foundation', aka: ['AAIF'], short: 'A Linux Foundation-directed foundation that hosts open agent projects; its A2A announcement of 27 August 2026 names MCP and AGENTS.md as sibling projects.', lesson: '/learn/rag-agents/multi-agent-systems/' },
  { id: 'coding-agent', term: 'Coding agent', aka: ['agentic coding'], short: 'A model with tools for reading files, running commands, editing code and running tests, which loops until its checks pass or a limit is reached.', lesson: '/learn/llm/ai-assisted-software-development/' },
  { id: 'agents-md', term: 'AGENTS.md', aka: ['agent instruction file'], short: 'An open file format described as a README for coding agents, holding setup commands, test commands and conventions for a repository.', lesson: '/learn/llm/ai-assisted-software-development/' },
  { id: 'package-hallucination', term: 'Package hallucination', aka: ['slopsquatting'], short: 'When a code model recommends a software package that does not exist, which an attacker could then register with malicious code.', lesson: '/learn/llm/ai-assisted-software-development/' },
  { id: 'sandbox', term: 'Sandbox', aka: ['agent sandbox'], short: 'An operating-system level limit on the files and network a coding agent\'s commands can reach, so a mistake or an injected instruction does less harm.', lesson: '/learn/llm/ai-assisted-software-development/' },
  { id: 'indirect-prompt-injection', term: 'Indirect prompt injection', aka: ['repository injection'], short: 'Instructions hidden in data an agent reads, such as a README, web page or tool result, that try to steer the model against its user.', lesson: '/learn/llm/ai-assisted-software-development/' },
  { id: 'byte-pair-encoding', term: 'byte-pair encoding', aka: ['BPE'], short: 'A way to build a token vocabulary: start from single bytes or characters and repeatedly merge the most frequent adjacent pair into a new token until the vocabulary reaches the chosen size.', lesson: '/learn/deep-learning/build-a-tokenizer/' },
  { id: 'byte-level-bpe', term: 'byte-level BPE', aka: ['BBPE', 'byte-level byte-pair encoding'], short: 'BPE that starts from the 256 byte values instead of characters, so any text can be encoded and no input is ever unknown. Used by GPT-2 and many later models.', lesson: '/learn/deep-learning/build-a-tokenizer/' },
  { id: 'pre-tokenisation', term: 'pre-tokenisation', aka: ['pre-tokenization'], short: 'The first step of many tokenizers: a pattern splits text into words, numbers and symbols, and merges are only allowed inside each piece.', lesson: '/learn/deep-learning/build-a-tokenizer/' },
  { id: 'special-token', term: 'special token', aka: ['control token', 'reserved token'], short: 'A reserved token that marks structure rather than text, such as the end of a document or the start of an assistant message. Users should not be able to type one by accident.', lesson: '/learn/deep-learning/build-a-tokenizer/' },
  { id: 'chat-template', term: 'chat template', aka: ['prompt template for chat'], short: 'The code that turns a list of chat messages into the exact text, special tokens included, that a chat model was trained on. A wrong template quietly lowers answer quality.', lesson: '/learn/deep-learning/build-a-tokenizer/' },
  { id: 'glitch-token', term: 'glitch token', aka: ['under-trained token'], short: 'A token that is in the tokenizer\'s vocabulary but was almost never seen while the model trained, so the model handles it unpredictably.', lesson: '/learn/deep-learning/build-a-tokenizer/' },
  { id: 'token-healing', term: 'token healing', aka: ['prompt boundary healing'], short: 'A trick that backs up one token at the end of a prompt and makes the first new token start with those characters, avoiding an awkward token boundary.', lesson: '/learn/deep-learning/build-a-tokenizer/' },
  { id: 'sentencepiece', term: 'SentencePiece', short: 'A library that trains subword tokenizers, with BPE or the unigram method, directly from raw text and treats spaces as an ordinary symbol, so it needs no language-specific word splitting.', lesson: '/learn/deep-learning/build-a-tokenizer/' },
  { id: 'rmsnorm', term: 'RMSNorm', aka: ['root mean square normalisation'], short: 'A normalisation that rescales a vector by its root mean square without subtracting the mean. Cheaper than LayerNorm and common in current LLMs.', lesson: '/learn/deep-learning/modern-llm-architecture/' },
  { id: 'pre-norm', term: 'pre-norm', aka: ['pre-layer normalisation'], short: 'Placing the normalisation at the input of each attention or feed-forward sub-block, inside the residual branch. It trains deep stacks more stably than normalising after the residual add.', lesson: '/learn/deep-learning/modern-llm-architecture/' },
  { id: 'swiglu', term: 'SwiGLU', aka: ['gated feed-forward', 'gated MLP'], short: 'A feed-forward layer with three matrices: one projection, passed through a smooth activation, multiplies a second projection element by element before the result is projected back.', lesson: '/learn/deep-learning/modern-llm-architecture/' },
  { id: 'grouped-query-attention', term: 'grouped-query attention', aka: ['GQA'], short: 'Attention in which several query heads share one set of keys and values. The KV cache shrinks by the ratio of query heads to KV heads with little loss in quality.', lesson: '/learn/deep-learning/modern-llm-architecture/' },
  { id: 'multi-query-attention', term: 'multi-query attention', aka: ['MQA'], short: 'The extreme case of grouped-query attention: every query head shares a single key head and value head, which makes the KV cache smallest but can cost some quality.', lesson: '/learn/deep-learning/modern-llm-architecture/' },
  { id: 'multi-head-latent-attention', term: 'multi-head latent attention', aka: ['MLA'], short: 'DeepSeek\'s attention variant. It stores one small compressed latent per token and layer, from which keys and values are rebuilt, instead of caching full keys and values for every head.', lesson: '/learn/deep-learning/modern-llm-architecture/' },
  { id: 'sliding-window-attention', term: 'sliding-window attention', aka: ['local attention', 'banded attention'], short: 'Attention in which each token sees only the last W tokens, so that layer\'s KV cache stops growing at W. Often mixed with full-attention layers.', lesson: '/learn/deep-learning/modern-llm-architecture/' },
  { id: 'active-parameters', term: 'active parameters', aka: ['activated parameters'], short: 'In a mixture-of-experts model, the parameters actually used for one token. Compute per token follows this number, while memory follows the total.', lesson: '/learn/deep-learning/modern-llm-architecture/' },
  { id: 'expert-router', term: 'expert router', aka: ['MoE router', 'gating network'], short: 'A small layer in a mixture-of-experts model that scores the experts for each token and sends the token to the top few.', lesson: '/learn/deep-learning/modern-llm-architecture/' },
  { id: 'position-interpolation', term: 'position interpolation', aka: ['positional interpolation'], short: 'A way to extend a RoPE model\'s context by scaling position indices down so that longer inputs fall inside the angles seen in training, followed by a little fine-tuning.', lesson: '/learn/deep-learning/modern-llm-architecture/' },
  { id: 'yarn', term: 'YaRN', aka: ['Yet another RoPE extensioN'], short: 'A method for stretching a RoPE model\'s context window that rescales fast and slow rotation frequencies differently. It needs far less fine-tuning than earlier methods.', lesson: '/learn/deep-learning/modern-llm-architecture/' },
  { id: 'state-space-model', term: 'state-space model', aka: ['SSM', 'Mamba'], short: 'A sequence layer that carries a fixed-size state forward and updates it for each token, so cost grows linearly with length. Mamba makes the update depend on the input token.', lesson: '/learn/deep-learning/modern-llm-architecture/' },
  { id: 'tied-embeddings', term: 'tied embeddings', aka: ['weight tying', 'shared embeddings'], short: 'Using one matrix both to look up token embeddings and to produce output scores, which saves one vocabulary-by-width matrix of parameters.', lesson: '/learn/deep-learning/modern-llm-architecture/' },
  { id: 'scaling-law', term: 'scaling law', aka: ['scaling laws', 'neural scaling law'], short: 'An empirical rule that a model\'s loss falls as a smooth power law as parameters, training data or compute grow, so results from small runs can be used to plan large ones.', lesson: '/learn/deep-learning/scaling-laws/' },
  { id: 'power-law', term: 'power law', aka: ['log-log straight line'], short: 'A relationship where one quantity changes as another raised to a fixed power. It plots as a straight line on log-log axes, and loss against compute follows one over a wide range.', lesson: '/learn/deep-learning/scaling-laws/' },
  { id: 'compute-optimal', term: 'compute-optimal', aka: ['Chinchilla-optimal'], short: 'Training with the split of parameters and tokens that gives the lowest loss for a fixed compute budget. In the Chinchilla study this came to about 20 tokens per parameter.', lesson: '/learn/deep-learning/scaling-laws/' },
  { id: 'chinchilla', term: 'Chinchilla', aka: ['Chinchilla scaling'], short: 'DeepMind\'s 70-billion-parameter model trained on 1.4 trillion tokens, and the finding behind it that parameters and tokens should grow together for a fixed compute budget.', lesson: '/learn/deep-learning/scaling-laws/' },
  { id: '6nd-rule', term: '6ND rule', aka: ['C = 6ND', '6 N D estimate'], short: 'The estimate that training a dense transformer costs about 6 x parameters x tokens FLOPs: roughly 2 for the forward pass and 4 for the backward pass per parameter per token.', lesson: '/learn/deep-learning/scaling-laws/' },
  { id: 'model-flops-utilisation', term: 'model FLOPs utilisation', aka: ['MFU'], short: 'The share of a chip\'s peak arithmetic speed that goes into useful model computation. Published large dense-model training runs have reported roughly 40 per cent.', lesson: '/learn/deep-learning/scaling-laws/' },
  { id: 'over-training', term: 'over-training', aka: ['over-trained model', 'training past compute-optimal'], short: 'Training a model on far more tokens than the compute-optimal amount, so it is smaller and cheaper to serve at the same quality. Many production models are trained this way.', lesson: '/learn/deep-learning/scaling-laws/' },
  { id: 'tokens-per-parameter', term: 'tokens per parameter', aka: ['data-to-parameter ratio'], short: 'Training tokens divided by model parameters. Chinchilla found about 20 for compute-optimal training, while heavily over-trained models use hundreds or more.', lesson: '/learn/deep-learning/scaling-laws/' },
  { id: 'isoflop-curve', term: 'IsoFLOP curve', aka: ['IsoFLOP profile'], short: 'A plot of loss against model size for runs that all use the same training compute. Its lowest point is the compute-optimal model size for that budget.', lesson: '/learn/deep-learning/scaling-laws/' },
  { id: 'reward-model', term: 'reward model', aka: ['preference model'], short: 'A model trained on human rankings of answers to output a score for any answer, standing in for a person during reinforcement learning.', lesson: '/learn/deep-learning/rl-post-training/' },
  { id: 'kl-penalty', term: 'KL penalty', aka: ['KL leash', 'KL divergence penalty'], short: 'A term subtracted from the reward in proportion to how far the policy\'s probabilities have drifted from a frozen reference model, to limit over-optimisation.', lesson: '/learn/deep-learning/rl-post-training/' },
  { id: 'reference-policy', term: 'reference policy', aka: ['reference model'], short: 'The frozen copy of a model from before reinforcement learning started. The KL penalty measures how far the trained model has drifted from it.', lesson: '/learn/deep-learning/rl-post-training/' },
  { id: 'ppo', term: 'PPO', exact: true, aka: ['proximal policy optimisation'], short: 'A reinforcement learning method that updates a policy from sampled rewards and clips each update so probabilities cannot change too much in one step. Used in classic RLHF.', lesson: '/learn/deep-learning/rl-post-training/' },
  { id: 'grpo', term: 'GRPO', exact: true, aka: ['group relative policy optimisation'], short: 'A PPO variant that samples a group of answers per prompt and scores each against the group\'s mean and spread, so no separate value model is needed.', lesson: '/learn/deep-learning/rl-post-training/' },
  { id: 'advantage-rl', term: 'advantage (RL)', aka: ['advantage estimate'], short: 'How much better an outcome was than expected. In GRPO it is the answer\'s reward minus the group mean, divided by the group standard deviation.', lesson: '/learn/deep-learning/rl-post-training/' },
  { id: 'rlvr', term: 'RLVR', exact: true, aka: ['reinforcement learning with verifiable rewards'], short: 'Reinforcement learning where a program checks the answer, such as a unit test or an exact match on a maths result, instead of a learned reward model giving the score.', lesson: '/learn/deep-learning/rl-post-training/' },
  { id: 'reward-hacking', term: 'reward hacking', aka: ['over-optimisation', 'Goodhart\'s law'], short: 'When a model learns to score highly on the reward without doing what the reward was meant to measure, such as editing unit tests instead of fixing the code.', lesson: '/learn/deep-learning/rl-post-training/' },
  { id: 'constitutional-ai', term: 'Constitutional AI', aka: ['RLAIF', 'reinforcement learning from AI feedback'], short: 'Anthropic\'s method of training with feedback from a model guided by written principles rather than human harm labels, followed by RL on the AI preference scores.', lesson: '/learn/deep-learning/rl-post-training/' },
  { id: 'document-parsing', term: 'Document parsing', aka: ['PDF parsing', 'document extraction'], short: 'The step that turns a file such as a PDF, scan or slide deck into text, structure and metadata before chunking and embedding. Faults here are silent and cap RAG quality.', lesson: '/learn/rag-agents/reading-real-documents/' },
  { id: 'text-layer', term: 'Text layer', aka: ['embedded text', 'PDF text layer'], short: 'The characters, with their positions on the page, stored inside a born-digital PDF. A scan has none, so a text extractor returns nothing for it.', lesson: '/learn/rag-agents/reading-real-documents/' },
  { id: 'born-digital-pdf', term: 'Born-digital PDF', aka: ['native PDF'], short: 'A PDF produced directly by software, so it contains a text layer, as opposed to a PDF made by scanning paper.', lesson: '/learn/rag-agents/reading-real-documents/' },
  { id: 'reading-order', term: 'Reading order', aka: ['text flow order'], short: 'The sequence in which a person reads the blocks on a page. PDFs do not store it, so a parser must infer it, especially for columns, sidebars and footnotes.', lesson: '/learn/rag-agents/reading-real-documents/' },
  { id: 'layout-analysis', term: 'Layout analysis', aka: ['page segmentation', 'layout detection'], short: 'Finding the regions of a page, such as columns, headings, tables, figures, headers and footers, and the order to read them in, usually with a trained model.', lesson: '/learn/rag-agents/reading-real-documents/' },
  { id: 'ocr', term: 'OCR', exact: true, aka: ['optical character recognition'], short: 'Software that reads the text in an image of a page. It works on scans and photos but can confuse look-alike shapes such as 8 and B or 0 and O.', lesson: '/learn/rag-agents/reading-real-documents/' },
  { id: 'page-furniture', term: 'Page furniture', aka: ['headers and footers', 'running header'], short: 'Text repeated on many pages, such as a title line, a confidentiality notice or a page number. Left in, it appears in every chunk and blurs retrieval.', lesson: '/learn/rag-agents/reading-real-documents/' },
  { id: 'table-structure-recognition', term: 'Table structure recognition', aka: ['table extraction'], short: 'Recovering a table\'s rows, columns, header cells and merged cells from a page, so that each value stays attached to its labels.', lesson: '/learn/rag-agents/reading-real-documents/' },
  { id: 'layout-aware-chunking', term: 'Layout-aware chunking', aka: ['structure-aware chunking'], short: 'Splitting a document along its headings, sections, tables and figures instead of a fixed length, keeping captions with their figures and carrying the section path into each chunk.', lesson: '/learn/rag-agents/reading-real-documents/' },
  { id: 'character-error-rate', term: 'Character error rate', aka: ['CER'], short: 'The edit distance between extracted text and the correct text, divided by the correct text\'s length. Zero is perfect. An average can hide a wrong key field.', lesson: '/learn/rag-agents/reading-real-documents/' },
  { id: 'word-error-rate', term: 'Word error rate', aka: ['WER'], short: 'The same measure as character error rate, counted over whole words, so one wrong digit counts as one wrong word.', lesson: '/learn/rag-agents/reading-real-documents/' },
  { id: 'late-interaction', term: 'Late interaction', aka: ['multi-vector retrieval', 'MaxSim'], short: 'A scoring method that keeps one vector per token or image patch and, for each query vector, takes its best match in the document before adding the scores. Used by ColBERT and ColPali.', lesson: '/learn/rag-agents/reading-real-documents/' },
  { id: 'colpali', term: 'ColPali', aka: ['visual document retrieval'], short: 'A retrieval model that embeds page images as one vector per image patch and scores queries by late interaction, so it can search pages without OCR or layout parsing.', lesson: '/learn/rag-agents/reading-real-documents/' },
  { id: 'vidore', term: 'ViDoRe', aka: ['Visual Document Retrieval Benchmark'], short: 'A benchmark of page-level retrieval tasks over visually rich documents, introduced with ColPali, used to compare text-extraction pipelines with page-image retrieval.', lesson: '/learn/rag-agents/reading-real-documents/' },
  { id: 'gold-set-for-parsing', term: 'Gold set (for parsing)', aka: ['parsing test set'], short: 'A small sample of real pages with hand-checked correct text, reading order and table cells, used to score a parser before and after every change.', lesson: '/learn/rag-agents/reading-real-documents/' },
  { id: 'error-analysis', term: 'error analysis', aka: ['open coding and counting'], short: 'Reading real transcripts, noting what went wrong, grouping the notes into named failure types and counting them, so you fix the biggest problem first.', lesson: '/learn/evals/building-an-eval-dataset/' },
  { id: 'open-coding', term: 'open coding', aka: ['free-text annotation'], short: 'Writing open-ended notes about each example without a fixed checklist, so you can notice failures you did not expect. Borrowed from qualitative research.', lesson: '/learn/evals/building-an-eval-dataset/' },
  { id: 'failure-taxonomy', term: 'failure taxonomy', aka: ['failure modes list'], short: 'A short list of named kinds of failure, built by grouping your notes on real examples and used to decide which checks to build.', lesson: '/learn/evals/building-an-eval-dataset/' },
  { id: 'criteria-drift', term: 'criteria drift', aka: ['rubric drift'], short: 'The finding that you need criteria to grade outputs, but grading outputs is how you discover your criteria, so a rubric changes as you read.', lesson: '/learn/evals/building-an-eval-dataset/' },
  { id: 'cohen-s-kappa', term: 'Cohen\'s kappa', short: 'A score for how much two labellers agree after removing the agreement expected by chance: (observed minus chance) divided by (1 minus chance).', lesson: '/learn/evals/building-an-eval-dataset/' },
  { id: 'inter-annotator-agreement', term: 'inter-annotator agreement', aka: ['labeller agreement'], short: 'How consistently different people give the same label to the same item. Low agreement usually means the rubric is vague.', lesson: '/learn/evals/building-an-eval-dataset/' },
  { id: 'eval-slice', term: 'eval slice', aka: ['coverage slice'], short: 'A tagged subset of eval cases, such as one topic, language or difficulty, scored separately so an overall average cannot hide a weak spot.', lesson: '/learn/evals/building-an-eval-dataset/' },
  { id: 'synthetic-test-case', term: 'synthetic test case', aka: ['generated test case'], short: 'A test input written by a model, often from a grid of dimensions such as topic and mood. Useful to start, but generic and not evidence of real traffic.', lesson: '/learn/evals/building-an-eval-dataset/' },
  { id: 'faithfulness', term: 'faithfulness', aka: ['groundedness'], short: 'Whether every claim in an answer is supported by the source text the model was given, regardless of whether the source is true.', lesson: '/learn/evals/why-models-make-things-up/' },
  { id: 'factuality', term: 'factuality', aka: ['factual accuracy'], short: 'Whether a statement is true in the real world, checked against an outside reference rather than the text the model was given.', lesson: '/learn/evals/why-models-make-things-up/' },
  { id: 'abstention', term: 'abstention', aka: ['refusal to answer', 'saying "I don\'t know"'], short: 'When a model declines to answer because it lacks support, instead of guessing. Useful when it is calibrated, harmful when it refuses answerable questions.', lesson: '/learn/evals/why-models-make-things-up/' },
  { id: 'sycophancy', term: 'sycophancy', aka: ['agreeing with the user'], short: 'A tendency of assistants to match the user\'s stated views or premises over the truth, linked in research to preferences in human feedback data.', lesson: '/learn/evals/why-models-make-things-up/' },
  { id: 'exposure-bias', term: 'exposure bias', aka: ['train-test mismatch in generation'], short: 'A mismatch: models train on real text but at generation time continue from their own earlier output, so early mistakes can compound.', lesson: '/learn/evals/why-models-make-things-up/' },
  { id: 'factscore', term: 'FActScore', aka: ['atomic fact precision'], short: 'A metric that splits a long answer into atomic facts and reports the share supported by a reliable knowledge source.', lesson: '/learn/evals/why-models-make-things-up/' },
  { id: 'self-consistency', term: 'self-consistency', aka: ['majority voting over samples'], short: 'Sampling several answers and keeping the most common one, or treating disagreement between samples as a warning sign. Costs several calls.', lesson: '/learn/evals/why-models-make-things-up/' },
  { id: 'decision-ladder', term: 'Decision ladder', aka: ['complexity ladder'], short: 'An ordering of ways to solve a problem from simplest to most complex: a person, code and rules, search, a trained model, one LLM call, an agent. Pick the lowest rung that meets the bar.', lesson: '/learn/systems/when-not-to-use-an-llm/' },
  { id: 'cost-of-being-wrong', term: 'Cost of being wrong', aka: ['cost of error'], short: 'What an incorrect output costs the user or the business, including who notices and how much it takes to fix. It decides how much checking and human review a feature needs.', lesson: '/learn/systems/when-not-to-use-an-llm/' },
  { id: 'heuristic-baseline', term: 'Heuristic baseline', aka: ['rules baseline'], short: 'A simple rule, keyword search or regex used as the first version. Anything more complex has to beat it on a measured test, not just in a demo.', lesson: '/learn/systems/when-not-to-use-an-llm/' },
  { id: 'fallback-chain', term: 'Fallback chain', aka: ['graceful degradation'], short: 'The ordered steps used when a model is wrong, slow or down, usually ending in a plain rule or a person, such as "I am not sure, let me get a colleague".', lesson: '/learn/systems/when-not-to-use-an-llm/' },
  { id: 'build-buy-or-call', term: 'Build, buy or call', aka: ['build versus buy'], short: 'The choice of where a capability comes from: a finished product, a model API you wrap in your own prompts and checks, or a model you host or fine-tune yourself.', lesson: '/learn/systems/when-not-to-use-an-llm/' },
  { id: 'benchmark-contamination', term: 'Benchmark contamination', aka: ['test set leakage'], short: 'When a benchmark\'s questions or answers appear in a model\'s training data, so a high score may reflect memory rather than ability.', lesson: '/learn/llm/choosing-and-comparing-models/' },
  { id: 'benchmark-saturation', term: 'Benchmark saturation', aka: ['ceiling effect'], short: 'When top models all score near the maximum on a test, so it no longer separates them and small gaps carry no information.', lesson: '/learn/llm/choosing-and-comparing-models/' },
  { id: 'human-preference-arena', term: 'Human-preference arena', aka: ['arena leaderboard'], short: 'A leaderboard built from people choosing the better of two anonymous model answers. The votes are turned into ratings with a statistical model.', lesson: '/learn/llm/choosing-and-comparing-models/' },
  { id: 'bradley-terry-model', term: 'Bradley-Terry model', aka: ['BT model', 'pairwise ranking model'], short: 'A model in which the chance that one item beats another depends only on the difference of their strengths. It turns head-to-head votes into ratings.', lesson: '/learn/llm/choosing-and-comparing-models/' },
  { id: 'elo-rating', term: 'Elo rating', aka: ['Elo score'], short: 'A rating scale from chess where a 400-point gap means 10 to 1 odds of winning. Arenas show model strengths on a similar scale.', lesson: '/learn/llm/choosing-and-comparing-models/' },
  { id: 'style-control', term: 'Style control', aka: ['length and format adjustment'], short: 'An adjustment that removes the effect of answer length and markdown formatting from preference votes, so ratings reflect substance more than presentation.', lesson: '/learn/llm/choosing-and-comparing-models/' },
  { id: 'open-source-ai-definition', term: 'Open Source AI Definition', aka: ['OSAID'], short: 'The Open Source Initiative\'s definition: users must be free to use, study, modify and share the system, with data information, code and parameters under approved terms.', lesson: '/learn/llm/choosing-and-comparing-models/' },
  { id: 'version-pinning', term: 'Version pinning', aka: ['model pinning'], short: 'Calling an exact model version instead of a moving alias, and logging it, so behaviour changes can be tied to a model change and migrations are planned.', lesson: '/learn/llm/choosing-and-comparing-models/' },
  { id: 'model-deprecation', term: 'Model deprecation', aka: ['model retirement'], short: 'A provider\'s announcement that a model will stop being available on a date, usually with a notice period and a recommended replacement.', lesson: '/learn/llm/choosing-and-comparing-models/' },
  { id: 'demographic-parity', term: 'demographic parity', aka: ['statistical parity', 'same approval rate'], short: 'A fairness criterion that asks for the same share of each group to get the positive decision, such as approval. It ignores whether the groups differ in who would actually succeed.', lesson: '/learn/responsible/fairness-for-builders/' },
  { id: 'equal-opportunity', term: 'equal opportunity', aka: ['true positive rate parity'], short: 'A fairness criterion that asks that people who would truly succeed have the same chance of a positive decision in every group, so the true positive rate is equal.', lesson: '/learn/responsible/fairness-for-builders/' },
  { id: 'equalised-odds', term: 'equalised odds', aka: ['equalized odds'], short: 'A fairness criterion that asks for both the true positive rate and the false positive rate to be equal across groups.', lesson: '/learn/responsible/fairness-for-builders/' },
  { id: 'predictive-parity', term: 'predictive parity', aka: ['equal precision', 'PPV parity'], short: 'A fairness criterion that asks that a positive decision be right equally often in every group, so precision (positive predictive value) is equal.', lesson: '/learn/responsible/fairness-for-builders/' },
  { id: 'calibration-within-groups', term: 'calibration within groups', aka: ['group calibration'], short: 'A score is calibrated within groups if, in every group, people given a score of 0.8 turn out positive about 80% of the time. The score then means the same thing for everyone.', lesson: '/learn/responsible/fairness-for-builders/' },
  { id: 'fairness-impossibility-result', term: 'fairness impossibility result', aka: ['Kleinberg trade-off', 'Chouldechova result'], short: 'When groups have different base rates, calibration, equal error rates and equal precision cannot all hold at once, except for a perfect predictor or in special cases.', lesson: '/learn/responsible/fairness-for-builders/' },
  { id: 'model-card', term: 'model card', short: 'A short document shipped with a model that states its intended use, how it was evaluated, and how well it works for different groups and conditions, so users know where it can and cannot be trusted.', lesson: '/learn/responsible/fairness-for-builders/' },
  { id: 'datasheet-for-datasets', term: 'datasheet for datasets', aka: ['dataset datasheet'], short: 'A document that describes a dataset: why it was made, what it contains, how it was collected, and what it should and should not be used for.', lesson: '/learn/responsible/fairness-for-builders/' },
  { id: 'membership-inference', term: 'membership inference', aka: ['membership inference attack'], short: 'An attack that tries to tell whether a particular record was in a model\'s training data, by studying how the model behaves on it.', lesson: '/learn/responsible/privacy-engineering-for-ai/' },
  { id: 'training-data-extraction', term: 'training data extraction', aka: ['extraction attack', 'regurgitation'], short: 'An attack, or an accident, in which a model outputs text it memorised from its training data, such as names, phone numbers or code, word for word.', lesson: '/learn/responsible/privacy-engineering-for-ai/' },
  { id: 'differential-privacy', term: 'differential privacy', aka: ['DP'], short: 'A mathematical limit on how much any answer can reveal about one person: adding or removing a single record changes the odds of every output by at most a factor of e to the epsilon.', lesson: '/learn/responsible/privacy-engineering-for-ai/' },
  { id: 'privacy-budget', term: 'privacy budget', aka: ['epsilon', 'privacy loss'], short: 'The total amount of privacy loss (epsilon) a data set may spend. Each answer uses some, with simple composition adding them up, and a system must stop when the budget is gone.', lesson: '/learn/responsible/privacy-engineering-for-ai/' },
  { id: 'laplace-mechanism', term: 'Laplace mechanism', short: 'A way to answer a numeric query privately by adding noise from a Laplace distribution whose scale is the query\'s sensitivity divided by epsilon.', lesson: '/learn/responsible/privacy-engineering-for-ai/' },
  { id: 'dp-sgd', term: 'DP-SGD', exact: true, aka: ['differentially private SGD'], short: 'Training a neural network with differential privacy: clip each example\'s gradient so no one example dominates, add noise to the averaged gradient, and track the total privacy cost.', lesson: '/learn/responsible/privacy-engineering-for-ai/' },
  { id: 'federated-learning', term: 'federated learning', aka: ['FL', 'FedAvg'], short: 'Training a shared model while the data stays on users\' devices or sites: each trains locally and sends an update, and a server averages the updates. Updates can still leak.', lesson: '/learn/responsible/privacy-engineering-for-ai/' },
  { id: 'secure-aggregation', term: 'secure aggregation', short: 'A cryptographic protocol that lets a server learn only the sum of many clients\' updates, not any single client\'s, used with federated learning.', lesson: '/learn/responsible/privacy-engineering-for-ai/' },
  { id: 'machine-unlearning', term: 'machine unlearning', aka: ['unlearning'], short: 'Making a trained model behave as if certain data had never been in its training set. Exact unlearning usually needs retraining, and approximate methods give weaker guarantees.', lesson: '/learn/responsible/privacy-engineering-for-ai/' },
  { id: 'purpose-limitation', term: 'purpose limitation', short: 'A data-protection principle: personal data may be collected only for a specific, stated purpose, and not reused for an unrelated one without checking that it is allowed.', lesson: '/learn/responsible/privacy-engineering-for-ai/' },
  { id: 'specification-gaming', term: 'specification gaming', aka: ['reward gaming'], short: 'Behaviour that satisfies the literal objective or reward without achieving what the designer intended, such as covering a camera so it sees no mess.', lesson: '/learn/responsible/teaching-a-model-to-behave/' },
  { id: 'goal-misgeneralisation', term: 'goal misgeneralisation', aka: ['goal misgeneralization'], short: 'When a system keeps its skills in a new situation but pursues the wrong goal, because the goal it learned only matched the intended one in training.', lesson: '/learn/responsible/teaching-a-model-to-behave/' },
  { id: 'red-teaming', term: 'red teaming', aka: ['AI red-teaming'], short: 'A structured test in which people, or other models, deliberately try to make an AI system fail or misbehave, to find and fix problems before real users meet them.', lesson: '/learn/responsible/teaching-a-model-to-behave/' },
  { id: 'dangerous-capability-evaluation', term: 'dangerous-capability evaluation', aka: ['frontier capability eval'], short: 'A test of whether a model can do tasks that would significantly help someone cause severe harm. A failed test is a floor on risk, not proof the capability is absent.', lesson: '/learn/responsible/teaching-a-model-to-behave/' },
  { id: 'coordinated-vulnerability-disclosure', term: 'coordinated vulnerability disclosure', aka: ['CVD', 'responsible disclosure'], short: 'Reporting a flaw privately to the vendor, giving time to fix it, and publishing details afterwards, so users are protected and the finder is credited.', lesson: '/learn/responsible/teaching-a-model-to-behave/' },

  // Wave 1 (Nov 2026): skills, classical ML, deep learning, responsible AI, audio


  // Wave 1 (Nov 2026): skills, classical ML, deep learning, responsible AI, audio
  { id: 'user-item-matrix', term: 'user-item matrix', aka: ['ratings matrix'], short: 'A grid with people down the side and items across the top, where each filled cell is a rating, play or purchase. Most cells are blank, and recommenders try to guess the blanks.', lesson: '/learn/ml/recommenders-and-ranking/' },
  { id: 'collaborative-filtering', term: 'collaborative filtering', aka: ['CF'], short: 'Recommending using only behaviour: items liked by the same people count as similar, whatever they are about. It needs no description of the items, but it cannot place a brand-new item or person.', lesson: '/learn/ml/recommenders-and-ranking/' },
  { id: 'item-item-similarity', term: 'item-item similarity', aka: ['neighbourhood method'], short: 'A recommender that scores an item for someone from their own ratings of similar items, where similar means rated alike by the same people.', lesson: '/learn/ml/recommenders-and-ranking/' },
  { id: 'matrix-factorisation', term: 'matrix factorisation', aka: ['latent factor model'], short: 'A recommender that gives every person and item a short list of hidden numbers and predicts a rating from how well the two lists line up, using their dot product plus biases.', lesson: '/learn/ml/recommenders-and-ranking/' },
  { id: 'cold-start-problem', term: 'cold-start problem', short: 'The difficulty of recommending to a new person or recommending a new item, because there is no behaviour yet to learn from. Fixes include popularity, a few questions and item features.', lesson: '/learn/ml/recommenders-and-ranking/' },
  { id: 'two-tower-model', term: 'two-tower model', aka: ['dual encoder'], short: 'A model with one network for the person or query and another for the item, scoring a pair by the dot product of their vectors. Item vectors can be precomputed and searched fast.', lesson: '/learn/ml/recommenders-and-ranking/' },
  { id: 'candidate-generation', term: 'candidate generation', aka: ['retrieval stage'], short: 'The first, fast stage of a recommender or search system that cuts a huge catalogue down to a few hundred items for a slower, richer model to rank.', lesson: '/learn/ml/recommenders-and-ranking/' },
  { id: 're-ranking', term: 're-ranking', aka: ['final ordering stage'], short: 'The last stage that adjusts a ranked list with rules, such as removing rejected items, boosting fresh ones and keeping the list varied and fair.', lesson: '/learn/ml/recommenders-and-ranking/' },
  { id: 'hit-rate-at-k', term: 'hit rate at k', aka: ['leave-one-out hit rate'], short: 'The share of people whose hidden favourite item shows up in the top k recommendations. A simple offline test of whether a recommender finds what people like.', lesson: '/learn/ml/recommenders-and-ranking/' },
  { id: 'filter-bubble', term: 'filter bubble', aka: ['recommendation feedback loop'], short: 'A narrowing of what a person is shown because the system learns from clicks on what it already showed, which makes similar things more likely to be shown again.', lesson: '/learn/ml/recommenders-and-ranking/' },
  { id: 'multisided-fairness', term: 'multisided fairness', aka: ['provider fairness'], short: 'The idea that a recommender can be unfair to the people receiving lists and to the creators, sellers or hosts whose items fill them, and that the two aims can conflict.', lesson: '/learn/ml/recommenders-and-ranking/' },
  { id: 'seasonal-naive', term: 'seasonal naive', aka: ['seasonal naive forecast'], short: 'A baseline forecast that repeats the value from the same point in the last cycle, such as the same month last year. Any real forecasting model should beat it.', lesson: '/learn/ml/time-series-forecasting/' },
  { id: 'mase', term: 'MASE', exact: true, aka: ['mean absolute scaled error'], short: 'A forecast error divided by the error that seasonal naive makes on the training data. Below 1 beats that baseline, and it works when actual values are zero, unlike MAPE.', lesson: '/learn/ml/time-series-forecasting/' },
  { id: 'mape', term: 'MAPE', exact: true, aka: ['mean absolute percentage error'], short: 'The average miss as a percentage of the actual value. It is undefined at zero, huge near zero, and scores over-forecasts and under-forecasts of equal size differently.', lesson: '/learn/ml/time-series-forecasting/' },
  { id: 'rolling-origin-backtest', term: 'rolling-origin backtest', aka: ['time series cross-validation'], short: 'Evaluating a forecast by repeatedly training on everything before a point in time, forecasting what follows, then moving the point forward and averaging the scores.', lesson: '/learn/ml/time-series-forecasting/' },
  { id: 'lag-features', term: 'lag features', aka: ['lagged inputs'], short: 'Inputs for a forecasting model made from earlier values of the series, such as the value one step ago or a year ago, so ordinary models can predict the next value.', lesson: '/learn/ml/time-series-forecasting/' },
  { id: 'exponential-smoothing', term: 'exponential smoothing', aka: ['ETS', 'Holt-Winters'], short: 'A forecasting method that averages past values with weights that fade exponentially with age. Holt\'s version adds a trend term, and Holt-Winters adds a seasonal term.', lesson: '/learn/ml/time-series-forecasting/' },
  { id: 'arima', term: 'ARIMA', exact: true, aka: ['autoregressive integrated moving average'], short: 'A forecasting family that models how each value relates to earlier values and earlier forecast errors, after differencing to remove trend.', lesson: '/learn/ml/time-series-forecasting/' },
  { id: 'forecast-horizon', term: 'forecast horizon', aka: ['prediction horizon'], short: 'How far ahead a forecast looks, such as the next 12 months. Error normally grows with the horizon, so scores should be reported for the horizon you actually need.', lesson: '/learn/ml/time-series-forecasting/' },
  { id: 'zero-shot-forecasting', term: 'zero-shot forecasting', aka: ['pretrained forecaster'], short: 'Forecasting a new series with a model pretrained on many other series and not trained further on this one. Claims should be checked against simple baselines on your own data.', lesson: '/learn/ml/time-series-forecasting/' },
  { id: 'inertia', term: 'inertia', aka: ['within-cluster sum of squares'], short: 'The total squared distance from every point to the centre of its own cluster. Lower means tighter clusters, but it always falls as k grows.', lesson: '/learn/ml/clustering-and-dimensionality-reduction/' },
  { id: 'silhouette-score', term: 'silhouette score', aka: ['silhouette coefficient'], short: 'A score from -1 to 1 for a clustering: how much closer each point is to its own cluster than to the nearest other cluster, averaged. It favours compact, round clusters.', lesson: '/learn/ml/clustering-and-dimensionality-reduction/' },
  { id: 'dbscan', term: 'DBSCAN', exact: true, aka: ['density-based clustering'], short: 'A clustering method that grows clusters from crowded regions (core points within a radius eps), allows any shape, and labels isolated points as noise.', lesson: '/learn/ml/clustering-and-dimensionality-reduction/' },
  { id: 'hierarchical-clustering', term: 'hierarchical clustering', aka: ['agglomerative clustering', 'dendrogram'], short: 'Clustering that starts with every point alone and repeatedly merges the closest clusters, giving a tree (dendrogram) that you cut at a chosen level.', lesson: '/learn/ml/clustering-and-dimensionality-reduction/' },
  { id: 'principal-component-analysis', term: 'principal component analysis', aka: ['PCA'], short: 'A linear method that finds the directions along which the data vary most. Keeping the first two or three gives the flat view that preserves the most spread.', lesson: '/learn/ml/clustering-and-dimensionality-reduction/' },
  { id: 'explained-variance', term: 'explained variance', aka: ['explained variance ratio'], short: 'The share of a dataset\'s total spread that lies along one principal component. The shares add up to 1 across all components.', lesson: '/learn/ml/clustering-and-dimensionality-reduction/' },
  { id: 't-sne', term: 't-SNE', aka: ['t-distributed stochastic neighbour embedding'], short: 'A non-linear method that draws high-dimensional data in 2D so that near neighbours stay near. Cluster sizes and gaps in its pictures are unreliable and depend on perplexity.', lesson: '/learn/ml/clustering-and-dimensionality-reduction/' },
  { id: 'umap', term: 'UMAP', exact: true, aka: ['uniform manifold approximation and projection'], short: 'A non-linear dimension-reduction method, often used like t-SNE to draw embeddings in 2D. Its pictures also depend on settings such as the number of neighbours.', lesson: '/learn/ml/clustering-and-dimensionality-reduction/' },
  { id: 'anomaly-detection', term: 'anomaly detection', basic: true, aka: ['outlier detection', 'novelty detection'], short: 'Finding rare points, events or series that differ from normal, usually without many labelled examples. Alerts need a threshold chosen by cost.', lesson: '/learn/ml/anomaly-detection/' },
  { id: 'masking', term: 'masking', aka: ['masking effect'], short: 'When several outliers inflate the mean and standard deviation so much that a plain z-score no longer flags any of them.', lesson: '/learn/ml/anomaly-detection/' },
  { id: 'median-absolute-deviation', term: 'median absolute deviation', aka: ['MAD', 'modified z-score'], short: 'The median distance of values from their median. A robust measure of spread; the modified z-score built on it flags values above about 3.5.', lesson: '/learn/ml/anomaly-detection/' },
  { id: 'isolation-forest', term: 'isolation forest', aka: ['iForest'], short: 'An anomaly detector built from random trees that cut columns at random. Points that need few cuts to be isolated get high anomaly scores.', lesson: '/learn/ml/anomaly-detection/' },
  { id: 'reconstruction-error', term: 'reconstruction error', aka: ['autoencoder anomaly score'], short: 'How badly a model trained on normal data rebuilds its input. A large error suggests the input is unlike anything seen in training, so it is flagged.', lesson: '/learn/ml/anomaly-detection/' },
  { id: 'alert-fatigue', term: 'alert fatigue', basic: true, aka: ['alarm fatigue'], short: 'Ignoring or missing alerts because there are too many false ones. A threshold or alert budget keeps the volume reviewable.', lesson: '/learn/ml/anomaly-detection/' },
  { id: 'ctc', term: 'CTC', exact: true, aka: ['Connectionist Temporal Classification'], short: 'A way to train and decode speech models without knowing which frame belongs to which letter. The model labels every frame, then repeats are merged and blanks dropped.', lesson: '/learn/audio/speech-recognition/' },
  { id: 'ctc-blank', term: 'CTC blank', aka: ['blank symbol'], short: 'A special output meaning "no new letter in this frame". It lets a model stay quiet between letters and separates genuine double letters, so "l blank l" becomes ll.', lesson: '/learn/audio/speech-recognition/' },
  { id: 'alignment', term: 'Alignment', aka: ['frame alignment'], short: 'In speech recognition, a choice of one symbol for every audio frame. Many different alignments can collapse to the same text, so a text\'s probability is the sum over all of them.', lesson: '/learn/audio/speech-recognition/' },
  { id: 'greedy-decoding', term: 'Greedy decoding', aka: ['best-path decoding'], short: 'Taking the single most likely symbol in every frame and reading out the result. Fast, but it can miss a text that is more probable once all its alignments are added up.', lesson: '/learn/audio/speech-recognition/' },
  { id: 'beam-search', term: 'Beam search', aka: ['beam decoding'], short: 'A search that keeps several of the best candidate outputs at each step instead of one. A wider beam costs more computation and gets closer to the most probable text.', lesson: '/learn/audio/speech-recognition/' },
  { id: 'rnn-t', term: 'RNN-T', exact: true, aka: ['RNN transducer', 'transducer'], short: 'A speech model that, like CTC, can emit text as audio arrives, but also looks at the text already written. It is a common choice for streaming recognition on devices.', lesson: '/learn/audio/speech-recognition/' },
  { id: 'streaming-recognition', term: 'Streaming recognition', aka: ['online ASR'], short: 'Writing words while the person is still talking, using only a little future audio. It lowers delay and usually costs some accuracy compared with reading the whole recording.', lesson: '/learn/audio/speech-recognition/' },
  { id: 'voice-activity-detection', term: 'Voice activity detection', aka: ['VAD'], short: 'A cheap model that says, for each short slice of audio, whether anyone is speaking. It saves compute, finds where utterances start and end, and keeps silence away from the recogniser.', lesson: '/learn/audio/speech-recognition/' },
  { id: 'whisper-hallucination', term: 'Whisper hallucination', aka: ['speech-to-text hallucination'], short: 'Fluent text produced by a speech model that is not in the audio, most often on silence or noise. A study found roughly 1 percent of Whisper transcriptions contained whole invented phrases.', lesson: '/learn/audio/speech-recognition/' },
  { id: 'signal-to-noise-ratio', term: 'Signal-to-noise ratio', aka: ['SNR'], short: 'How much stronger the wanted sound is than the noise, in decibels: 10 times the log of the energy ratio. At 0 dB they are equal, at 10 dB speech has ten times the energy.', lesson: '/learn/audio/noise-suppression-and-hearing-devices/' },
  { id: 'spectral-subtraction', term: 'Spectral subtraction', aka: ['noise subtraction'], short: 'Estimating the noise level at each frequency from a stretch with no speech, then turning each time-frequency cell down by that amount. It can leave short chirping tones called musical noise.', lesson: '/learn/audio/noise-suppression-and-hearing-devices/' },
  { id: 'musical-noise', term: 'Musical noise', aka: ['residual tonal noise'], short: 'Short, isolated tones left in the pauses after noise reduction, where random noise peaks exceeded the estimate. A floor on the gain hides them.', lesson: '/learn/audio/noise-suppression-and-hearing-devices/' },
  { id: 'wiener-filter', term: 'Wiener filter', aka: ['Wiener gain'], short: 'A noise-reduction gain set from the estimated signal-to-noise ratio of each cell: SNR divided by one plus SNR. Cells that look like noise are cut a lot, cells that look like speech very little.', lesson: '/learn/audio/noise-suppression-and-hearing-devices/' },
  { id: 'time-frequency-mask', term: 'Time-frequency mask', aka: ['spectrogram mask'], short: 'A number between 0 and 1 for every time-frequency cell, multiplied into the noisy spectrogram to keep or cut it. Many neural speech enhancers are trained to predict one.', lesson: '/learn/audio/noise-suppression-and-hearing-devices/' },
  { id: 'ideal-ratio-mask', term: 'Ideal ratio mask', aka: ['IRM'], short: 'The mask that gives each cell the share of its energy that belongs to speech, usually with a square root. It needs the clean speech, so it is the target a network learns to estimate.', lesson: '/learn/audio/noise-suppression-and-hearing-devices/' },
  { id: 'beamforming', term: 'Beamforming', aka: ['directional microphone', 'microphone array'], short: 'Combining two or more microphones, with delays, so that sound from one direction is kept and sound from others partly cancels. It assumes the wanted sound is in the chosen direction.', lesson: '/learn/audio/noise-suppression-and-hearing-devices/' },
  { id: 'cardioid', term: 'Cardioid', aka: ['heart-shaped pattern'], short: 'A directional pattern that is most sensitive to the front and has its null directly behind. A two-microphone version delays the rear signal by the time sound takes to cross the gap.', lesson: '/learn/audio/noise-suppression-and-hearing-devices/' },
  { id: 'algorithmic-latency', term: 'Algorithmic latency', aka: ['processing delay', 'group delay'], short: 'The delay a method adds before output can start, mostly set by its analysis window and any look-ahead. For hearing devices, a few milliseconds is about the most that listeners find acceptable in some set-ups.', lesson: '/learn/audio/noise-suppression-and-hearing-devices/' },
  { id: 'haspi', term: 'HASPI', exact: true, aka: ['Hearing Aid Speech Perception Index'], short: 'An objective score that predicts how intelligible processed speech is to a listener with a given hearing loss. It is used alongside listening tests in hearing-aid challenges.', lesson: '/learn/audio/noise-suppression-and-hearing-devices/' },
  { id: 'edit-distance', term: 'Edit distance', aka: ['Levenshtein distance'], short: 'The smallest number of single-item changes (swap, delete, insert) that turn one sequence into another. Word error rate is an edit distance over words.', lesson: '/learn/audio/measuring-audio-quality/' },
  { id: 'text-normalisation', term: 'Text normalisation', short: 'Rewriting text into a standard form before scoring or speaking: case, punctuation, numbers, contractions. Different rules give different error rates.', lesson: '/learn/audio/measuring-audio-quality/' },
  { id: 'mean-opinion-score', term: 'Mean opinion score', aka: ['MOS'], short: 'The average rating, usually from 1 to 5, that listeners give to audio in a listening test. Only comparable within the same test, and needs a confidence interval.', lesson: '/learn/audio/measuring-audio-quality/' },
  { id: 'absolute-category-rating', term: 'Absolute category rating', aka: ['ACR'], short: 'A listening-test method where each clip is rated alone on a five-point scale from Bad to Excellent. It produces a mean opinion score.', lesson: '/learn/audio/measuring-audio-quality/' },
  { id: 'mushra', term: 'MUSHRA', exact: true, short: 'A listening-test method that compares several versions of a clip against a hidden reference and a low-quality anchor, for audio at intermediate quality.', lesson: '/learn/audio/measuring-audio-quality/' },
  { id: 'pesq', term: 'PESQ', exact: true, aka: ['Perceptual evaluation of speech quality'], short: 'An older objective speech-quality score that compares a degraded signal with a clean reference. The ITU standard P.862 was withdrawn in 2024 in favour of P.863.', lesson: '/learn/audio/measuring-audio-quality/' },
  { id: 'polqa', term: 'POLQA', exact: true, aka: ['ITU-T P.863'], short: 'The ITU successor to PESQ: an objective score that compares a degraded speech signal with a clean reference to predict listening quality.', lesson: '/learn/audio/measuring-audio-quality/' },
  { id: 'stoi', term: 'STOI', exact: true, aka: ['Short-time objective intelligibility'], short: 'An objective score that compares noisy or processed speech with clean speech to predict how intelligible it is. It does not measure pleasantness.', lesson: '/learn/audio/measuring-audio-quality/' },
  { id: 'si-sdr', term: 'SI-SDR', exact: true, aka: ['Scale-invariant signal-to-distortion ratio'], short: 'A signal-level score of how close an enhanced or separated signal is to the clean one, in decibels. It ignores how the remaining error sounds.', lesson: '/learn/audio/measuring-audio-quality/' },
  { id: 'dnsmos', term: 'DNSMOS', exact: true, short: 'A learned, no-reference model that estimates listening-test scores for speech, built to judge noise suppressors. It needs no clean recording.', lesson: '/learn/audio/measuring-audio-quality/' },
  { id: 'prosody', term: 'Prosody', short: 'The rhythm, stress and pitch movement of speech: how long sounds last, which words are stressed, and whether a sentence rises like a question.', lesson: '/learn/audio/text-to-speech-and-voice-cloning/' },
  { id: 'grapheme-to-phoneme', term: 'Grapheme to phoneme', aka: ['G2P'], short: 'Converting spelled words into the sounds that are spoken, using a pronunciation dictionary and a learned model for words not in it.', lesson: '/learn/audio/text-to-speech-and-voice-cloning/' },
  { id: 'vocoder', term: 'Vocoder', short: 'The stage of a speech synthesiser that turns an acoustic representation, usually a mel spectrogram, into an audio waveform.', lesson: '/learn/audio/text-to-speech-and-voice-cloning/' },
  { id: 'residual-vector-quantisation', term: 'Residual vector quantisation', aka: ['RVQ'], short: 'Compressing each audio frame into several codes, where each code refines what the previous ones missed. Used in neural audio codecs.', lesson: '/learn/audio/text-to-speech-and-voice-cloning/' },
  { id: 'neural-audio-codec', term: 'Neural audio codec', short: 'A neural network that compresses audio into a stream of discrete codes and decodes it back. Language models can predict those codes to generate speech.', lesson: '/learn/audio/text-to-speech-and-voice-cloning/' },
  { id: 'real-time-factor', term: 'Real-time factor', aka: ['RTF'], short: 'Time taken to generate audio divided by the length of that audio. Below 1 means generation keeps up with playback.', lesson: '/learn/audio/text-to-speech-and-voice-cloning/' },
  { id: 'voice-banking', term: 'Voice banking', short: 'Recording a person\'s speech in advance, often before they lose their voice to illness, so a synthetic voice in their own style can be built for a speech device.', lesson: '/learn/audio/text-to-speech-and-voice-cloning/' },
  { id: 'tensor-arena', term: 'tensor arena', aka: ['activation arena'], short: 'The single block of RAM a microcontroller runtime sets aside for a model\'s input, output and intermediate tensors; its size is set by the largest layers, not by the weights.', lesson: '/learn/edge/inside-a-small-device/' },
  { id: 'activation-memory', term: 'activation memory', aka: ['peak activation memory'], short: 'The working memory a model needs for the values passing between layers; on a simple network it is the largest input plus output of any layer.', lesson: '/learn/edge/inside-a-small-device/' },
  { id: 'flash-and-sram', term: 'flash and SRAM', aka: ['non-volatile memory and working memory'], short: 'On a microcontroller, flash (or MRAM) keeps weights and code when powered off, while SRAM is the fast writable memory that holds activations and the stack.', lesson: '/learn/edge/inside-a-small-device/' },
  { id: 'mram', term: 'MRAM', exact: true, aka: ['magnetoresistive RAM'], short: 'A non-volatile memory used on some microcontrollers in place of flash to hold code and weights, which can be read in place.', lesson: '/learn/edge/inside-a-small-device/' },
  { id: 'mac', term: 'MAC', exact: true, aka: ['multiply-accumulate'], short: 'One multiplication followed by adding the result to a running total, the basic step of neural network arithmetic; hardware vendors usually count it as two operations.', lesson: '/learn/edge/inside-a-small-device/' },
  { id: 'tops', term: 'TOPS', exact: true, aka: ['tera operations per second'], short: 'A vendor\'s peak count of trillions of operations per second, usually 8-bit; check whether it is sparse or dense, since a MAC counts as two operations.', lesson: '/learn/edge/inside-a-small-device/' },
  { id: 'sparse-versus-dense-tops', term: 'sparse versus dense TOPS', aka: ['structured sparsity figure'], short: 'A sparse TOPS figure assumes a specially pruned model and is quoted at twice the dense figure that an ordinary model can reach.', lesson: '/learn/edge/inside-a-small-device/' },
  { id: 'microcontroller', term: 'microcontroller', aka: ['MCU'], short: 'A small, low-power chip with the processor, a few hundred kilobytes to a few megabytes of memory and peripherals on one die, often without an operating system.', lesson: '/learn/edge/inside-a-small-device/' },
  { id: 'cmsis-nn', term: 'CMSIS-NN', aka: ['Cortex-M neural network kernels'], short: 'Arm\'s open library of neural network kernels for Cortex-M processors, with variants for plain C, SIMD instructions and Helium vector instructions.', lesson: '/learn/edge/inside-a-small-device/' },
  { id: 'always-on-cascade', term: 'always-on cascade', aka: ['wake-up cascade'], short: 'A design in which a tiny low-power detector runs continuously and wakes a larger processor or model only when something interesting happens.', lesson: '/learn/edge/inside-a-small-device/' },
  { id: 'model-file-format', term: 'model file format', aka: ['exported model'], short: 'A frozen, device-friendly description of a trained model, such as .tflite, .pte, .onnx or a Core ML model, loaded by a matching runtime.', lesson: '/learn/edge/from-pytorch-to-the-chip/' },
  { id: 'inference-runtime', term: 'inference runtime', aka: ['runtime'], short: 'The library inside an app or firmware that loads an exported model and executes it, such as LiteRT, ExecuTorch, ONNX Runtime or Core ML.', lesson: '/learn/edge/from-pytorch-to-the-chip/' },
  { id: 'delegate', term: 'delegate', aka: ['backend', 'execution provider'], short: 'The runtime component that runs the operators a particular chip supports; ExecuTorch calls it a backend, ONNX Runtime an execution provider.', lesson: '/learn/edge/from-pytorch-to-the-chip/' },
  { id: 'graph-partitioning', term: 'graph partitioning', aka: ['operator fallback'], short: 'Splitting a model so the supported parts run on an accelerator and the rest fall back to the CPU, at the cost of a hand-off at each boundary.', lesson: '/learn/edge/from-pytorch-to-the-chip/' },
  { id: 'operator-support', term: 'operator support', aka: ['op coverage'], short: 'Whether a converter or accelerator can run a given operation; one unsupported operator can force a slow fallback or make conversion fail.', lesson: '/learn/edge/from-pytorch-to-the-chip/' },
  { id: 'ahead-of-time-compilation', term: 'ahead-of-time compilation', aka: ['AOT compilation'], short: 'Compiling a model for a known chip before shipping, which cuts start-up cost and memory use, as opposed to compiling on the device at first run.', lesson: '/learn/edge/from-pytorch-to-the-chip/' },
  { id: 'ml-compiler', term: 'ML compiler', aka: ['deep learning compiler'], short: 'Software such as Apache TVM that takes a model, optimises the graph and generates code for a target chip instead of calling prebuilt kernels.', lesson: '/learn/edge/from-pytorch-to-the-chip/' },
  { id: 'block-size', term: 'Block size', aka: ['buffer size', 'audio block'], short: 'The number of samples handed to your code at a time in a real-time audio or sensor pipeline. At a given sample rate it sets the deadline for processing each block.', lesson: '/learn/edge/real-time-on-a-budget/' },
  { id: 'real-time-deadline', term: 'Real-time deadline', aka: ['processing deadline'], short: 'The time a block of samples lasts (block size divided by sample rate). Output for that block must be ready before it finishes playing, or the listener hears a click or dropout.', lesson: '/learn/edge/real-time-on-a-budget/' },
  { id: 'look-ahead', term: 'Look-ahead', short: 'Future samples or frames an algorithm must wait for before it can answer. A non-causal model with look-ahead adds delay equal to the frames it waits for.', lesson: '/learn/edge/real-time-on-a-budget/' },
  { id: 'causal-model', term: 'Causal model', aka: ['streaming model'], short: 'A model that uses only past and present input, never future input. It adds no look-ahead delay and can carry its state from one block to the next.', lesson: '/learn/edge/real-time-on-a-budget/' },
  { id: 'deadline-miss', term: 'Deadline miss', aka: ['glitch', 'underrun'], short: 'A block whose processing takes longer than the time the block lasts. In audio it is heard as a click or a gap in the sound.', lesson: '/learn/edge/real-time-on-a-budget/' },
  { id: 'tail-latency', term: 'Tail latency', short: 'The slowest few per cent or fraction of a per cent of runs, measured as a high percentile such as p99. Real-time systems are judged on it because one slow block causes a glitch.', lesson: '/learn/edge/real-time-on-a-budget/' },
  { id: 'thermal-throttling', term: 'Thermal throttling', aka: ['thermal slowdown'], short: 'A chip lowering its clock speed when it gets hot, so latency rises during long runs. A short benchmark can miss it.', lesson: '/learn/edge/real-time-on-a-budget/' },
  { id: 'mlperf-tiny', term: 'MLPerf Tiny', aka: ['tinyMLPerf'], short: 'An open benchmark suite from MLCommons for ultra-low-power devices. It measures accuracy, latency and energy on tasks such as keyword spotting and anomaly detection.', lesson: '/learn/edge/real-time-on-a-budget/' },
  { id: 'closed-division', term: 'Closed division', aka: ['MLPerf closed division'], short: 'The strict MLPerf Tiny category in which every submission runs the same model and data and meets the same accuracy target, so results can be compared directly.', lesson: '/learn/edge/real-time-on-a-budget/' },
  { id: 'keyword-spotting', term: 'Keyword spotting', basic: true, aka: ['KWS', 'wake-word detection'], short: 'Listening continuously for a small set of words or one phrase, and waking a larger system when one is heard. It is the standard always-on speech task on small devices.', lesson: '/learn/edge/tinyml-wake-word-detector/' },
  { id: 'false-accept-rate', term: 'False accept rate', aka: ['FAR', 'false alarm rate'], short: 'How often a detector fires when it should not, usually counted as false activations per hour. For wake words the target is very low, near one per week.', lesson: '/learn/edge/tinyml-wake-word-detector/' },
  { id: 'false-reject-rate', term: 'False reject rate', aka: ['FRR', 'miss rate'], short: 'The share of genuine attempts that a detector fails to catch. Raising the threshold lowers false accepts but raises this.', lesson: '/learn/edge/tinyml-wake-word-detector/' },
  { id: 'posterior-smoothing', term: 'Posterior smoothing', aka: ['posterior handling'], short: 'Averaging a detector\'s per-frame outputs over a short time before deciding, so that one noisy frame cannot trigger it. It adds a little delay.', lesson: '/learn/edge/tinyml-wake-word-detector/' },
  { id: 'depthwise-separable-cnn', term: 'Depthwise-separable CNN', aka: ['DS-CNN'], short: 'A convolutional network that splits each convolution into a small filter per channel and a 1x1 mix across channels. It needs far fewer weights and operations, which suits small devices.', lesson: '/learn/edge/tinyml-wake-word-detector/' },
  { id: 'cascade-detector', term: 'Cascade detector', aka: ['two-stage detector'], short: 'A design in which a tiny model runs all the time on a low-power processor and wakes a larger, more accurate model only when it fires, to save power.', lesson: '/learn/edge/tinyml-wake-word-detector/' },
  { id: 'matched-filter', term: 'Matched filter', aka: ['template matching'], short: 'A fixed pattern compared with the incoming signal; the better the match, the higher the score. Used in the lesson as a simple stand-in for a trained detector.', lesson: '/learn/edge/tinyml-wake-word-detector/' },
  { id: 'post-training-quantization', term: 'Post-training quantization', aka: ['PTQ'], short: 'Converting a finished float model to low-precision integers using a small calibration set to measure value ranges, with no retraining.', lesson: '/learn/edge/quantization-for-edge/' },
  { id: 'quantization-aware-training', term: 'Quantization-aware training', aka: ['QAT', 'fake quantization'], short: 'Training with the rounding of low precision simulated in the forward pass, so the model learns to tolerate it. Often needed for small models or below 8 bits.', lesson: '/learn/edge/quantization-for-edge/' },
  { id: 'zero-point', term: 'Zero point', aka: ['zero-point offset'], short: 'The integer that stands for the real value 0 in an affine quantization scheme, where the real value is (integer minus zero point) times scale.', lesson: '/learn/edge/quantization-for-edge/' },
  { id: 'requantization', term: 'Requantization', aka: ['output rescaling'], short: 'The step after an integer layer accumulates in 32 bits: the sum is multiplied by a fixed-point factor and shifted to give the layer\'s 8-bit output.', lesson: '/learn/edge/quantization-for-edge/' },
  { id: 'on-device-language-model', term: 'On-device language model', aka: ['small language model', 'SLM'], short: 'A language model small enough, often a few billion parameters or fewer and compressed to a few bits per weight, to run on a phone, tablet or laptop instead of a server.', lesson: '/learn/edge/small-language-models-on-device/' },
  { id: 'memory-bandwidth-ceiling', term: 'Memory bandwidth ceiling', aka: ['decode speed ceiling'], short: 'The upper limit on tokens per second when generating text: memory bandwidth divided by the bytes read for each token, which is the weights plus the KV cache.', lesson: '/learn/edge/small-language-models-on-device/' },
  { id: 'kv-cache-sharing', term: 'KV cache sharing', aka: ['cross-layer KV sharing'], short: 'Letting some layers reuse the keys and values made by earlier layers instead of storing their own, which cuts KV cache memory; Apple reports 37.5 per cent for its on-device model.', lesson: '/learn/edge/small-language-models-on-device/' },
  { id: 'aicore', term: 'AICore', aka: ['Android AICore'], short: 'The Android system service that runs and updates Gemini Nano on the device, so apps reach the model through ML Kit GenAI instead of shipping it themselves.', lesson: '/learn/edge/small-language-models-on-device/' },
  { id: 'hybrid-inference', term: 'Hybrid inference', aka: ['on-device with cloud fallback'], short: 'A design where a small on-device model handles requests it can, and a larger cloud model takes those it cannot, or those that arrive when the device has no model.', lesson: '/learn/edge/small-language-models-on-device/' },
  { id: 'lora-adapter', term: 'LoRA adapter', aka: ['low-rank adapter'], short: 'A small set of extra trained weights added to a frozen base model to specialise it for one task; it works only with the base model version it was trained on.', lesson: '/learn/edge/small-language-models-on-device/' },
  { id: 'staged-rollout', term: 'Staged rollout', aka: ['phased rollout'], short: 'Sending an update to a small share of devices first, watching signals, and widening only if they stay healthy, so a bad update harms few devices.', lesson: '/learn/edge/shipping-to-a-fleet/' },
  { id: 'halt-rule', term: 'Halt rule', aka: ['abort criteria'], short: 'The condition, such as a failure rate at or above a threshold among reporting devices, that automatically stops a rollout from widening.', lesson: '/learn/edge/shipping-to-a-fleet/' },
  { id: 'rule-of-three', term: 'Rule of three', aka: ['zero-failure bound'], short: 'If no failures are seen in n trials, the failure rate is probably below about 3 / n, at roughly 95 per cent confidence.', lesson: '/learn/edge/shipping-to-a-fleet/' },
  { id: 'model-manifest', term: 'Model manifest', aka: ['model metadata'], short: 'A record shipped with a model giving its version, content hash, required runtime, target device classes, thresholds and the version to fall back to.', lesson: '/learn/edge/shipping-to-a-fleet/' },
  { id: 'anti-rollback-protection', term: 'Anti-rollback protection', aka: ['rollback attack defence'], short: 'A rule in secure update systems, such as the Update Framework (TUF), that a device will not install a version older than one it has already seen; a legitimate undo is therefore published as a new, higher version.', lesson: '/learn/edge/shipping-to-a-fleet/' },
  { id: 'federated-averaging', term: 'Federated averaging', short: 'A federated learning method in which each device trains briefly on its own data and the server averages the returned updates into the next shared model.', lesson: '/learn/edge/shipping-to-a-fleet/' },
  { id: 'local-differential-privacy', term: 'Local differential privacy', aka: ['LDP'], short: 'Adding calibrated noise on the device before a value is sent, so the server can learn statistics about many users but not any one user\'s true value.', lesson: '/learn/edge/shipping-to-a-fleet/' },
  { id: 'non-iid-data', term: 'Non-IID data', short: 'Data that differs from device to device, as each user\'s data reflects only their own life; it makes federated training harder than training on one pooled data set.', lesson: '/learn/edge/shipping-to-a-fleet/' },
  { id: 'mlops', term: 'MLOps', aka: ['machine learning operations'], short: 'The practice of automating and monitoring every step of building and running ML systems, from data and training to release and monitoring, so that models stay reliable in production.', lesson: '/learn/systems/from-notebook-to-production/' },
  { id: 'continuous-training', term: 'continuous training', aka: ['CT'], short: 'Automatically retraining and redeploying a model when triggers fire, such as a schedule, new data, falling performance or a shift in the data. Google calls it a property unique to ML systems.', lesson: '/learn/systems/from-notebook-to-production/' },
  { id: 'technical-debt-ml', term: 'technical debt (ML)', aka: ['hidden technical debt'], short: 'The long-term maintenance cost of ML systems that builds up at system level, through data dependencies, entanglement, feedback loops and glue code, rather than inside the model code.', lesson: '/learn/systems/from-notebook-to-production/' },
  { id: 'cace-principle', term: 'CACE principle', aka: ['changing anything changes everything'], short: 'The observation that in an ML model no input is independent: changing one feature, setting or data choice can shift how the model uses all the others.', lesson: '/learn/systems/from-notebook-to-production/' },
  { id: 'glue-code', term: 'glue code', aka: ['pipeline jungle'], short: 'The supporting code written to move data in and out of general-purpose ML packages; in data preparation it can grow into a tangle of joins and intermediate files that is hard to test.', lesson: '/learn/systems/from-notebook-to-production/' },
  { id: 'model-registry', term: 'model registry', short: 'A central store of model versions with metadata, lineage back to the run that made each one, and movable aliases such as production, so releases and rollbacks are controlled steps.', lesson: '/learn/systems/from-notebook-to-production/' },
  { id: 'experiment-tracking', term: 'experiment tracking', aka: ['run tracking'], short: 'Logging each training run\'s code version, parameters, metrics and output files so that results can be compared and a model can be traced back to how it was made.', lesson: '/learn/systems/from-notebook-to-production/' },
  { id: 'data-validation', term: 'data validation', aka: ['data checks'], short: 'Automated checks on each new batch of data, such as schema, range, distribution and volume, run before training so that bad data stops the pipeline instead of reaching the model.', lesson: '/learn/systems/data-pipelines-and-data-quality/' },
  { id: 'data-contract', term: 'data contract', short: 'An explicit agreement between the team producing a dataset and the teams using it, covering schema, field meaning, quality, freshness, ownership and how changes are announced.', lesson: '/learn/systems/data-pipelines-and-data-quality/' },
  { id: 'data-lineage', term: 'data lineage', aka: ['lineage'], short: 'A record of which datasets and jobs produced a given table, so that when bad data is found you can trace it back to its source and forward to everything it affected.', lesson: '/learn/systems/data-pipelines-and-data-quality/' },
  { id: 'training-serving-skew', term: 'training-serving skew', aka: ['train-serve skew'], short: 'A difference between the data or features a model saw in training and what it receives when serving, caused by different code paths, changed data or feedback loops.', lesson: '/learn/systems/data-pipelines-and-data-quality/' },
  { id: 'point-in-time-join', term: 'point-in-time join', aka: ['as-of join'], short: 'A join that gives each training row the feature value as it stood at that row\'s own time, so that no information from after the prediction moment leaks into training.', lesson: '/learn/systems/data-pipelines-and-data-quality/' },
  { id: 'weak-supervision', term: 'weak supervision', aka: ['labelling functions'], short: 'Creating training labels by combining many noisy rules or models, called labelling functions, instead of labelling every item by hand. Snorkel is a well-known example.', lesson: '/learn/systems/data-pipelines-and-data-quality/' },
  { id: 'confident-learning', term: 'confident learning', aka: ['label-error detection'], short: 'A method for finding mislabelled examples by flagging items where a model, scored on data it did not train on, confidently disagrees with the given label.', lesson: '/learn/systems/data-pipelines-and-data-quality/' },
  { id: 'batch-inference', term: 'Batch inference', aka: ['batch scoring', 'offline prediction'], short: 'Running a model on many inputs on a schedule and storing the predictions to be looked up later, instead of computing each one when a request arrives.', lesson: '/learn/systems/batch-vs-online-inference-and-feature-stores/' },
  { id: 'online-inference', term: 'Online inference', aka: ['real-time inference', 'online prediction'], short: 'Running a model when a request arrives and returning the answer straight away, so it can use what the user has just done.', lesson: '/learn/systems/batch-vs-online-inference-and-feature-stores/' },
  { id: 'streaming-features', term: 'Streaming features', aka: ['real-time features', 'near-real-time features'], short: 'Feature values computed continuously from a flow of events, for example orders in the last 30 minutes, and kept up to date for the model.', lesson: '/learn/systems/batch-vs-online-inference-and-feature-stores/' },
  { id: 'feature-store', term: 'Feature store', short: 'A service that keeps feature definitions and values in one place so training and serving use the same numbers, with a history for training and a fast store for live lookups.', lesson: '/learn/systems/batch-vs-online-inference-and-feature-stores/' },
  { id: 'offline-store', term: 'Offline store', short: 'The part of a feature store that holds the full time-stamped history of feature values, used to build training sets and to feed batch scoring.', lesson: '/learn/systems/batch-vs-online-inference-and-feature-stores/' },
  { id: 'online-store', term: 'Online store', short: 'The part of a feature store that keeps only the latest value of each feature per entity, so a live service can read it with very low latency.', lesson: '/learn/systems/batch-vs-online-inference-and-feature-stores/' },
  { id: 'materialisation', term: 'Materialisation', aka: ['feature materialization'], short: 'The job that copies fresh feature values from the offline store into the online store so they are ready for live lookups.', lesson: '/learn/systems/batch-vs-online-inference-and-feature-stores/' },
  { id: 'feature-time-to-live', term: 'Feature time-to-live', aka: ['feature TTL'], short: 'The longest age a feature value may have, measured back from the event it is joined to, before it is treated as missing.', lesson: '/learn/systems/batch-vs-online-inference-and-feature-stores/' },
  { id: 'ml-test-score', term: 'ML Test Score', short: 'A rubric from Google researchers of 28 tests and monitoring checks for ML systems, in four groups of seven, scored by the weakest group.', lesson: '/learn/systems/testing-and-deploying-ml-models/' },
  { id: 'champion-model', term: 'Champion model', aka: ['champion and challenger'], short: 'The model currently serving production, against which any new candidate must be compared before it is released.', lesson: '/learn/systems/testing-and-deploying-ml-models/' },
  { id: 'model-validation-gate', term: 'Model validation gate', aka: ['release gate'], short: 'An automatic check between training and release that passes a candidate model only if it beats the current one overall and does not fall below limits on important slices.', lesson: '/learn/systems/testing-and-deploying-ml-models/' },
  { id: 'golden-test', term: 'Golden test', short: 'A test that compares a partly trained model with a stored earlier result; it is hard to maintain and says little about why it failed.', lesson: '/learn/systems/testing-and-deploying-ml-models/' },
  { id: 'traffic-mirroring', term: 'Traffic mirroring', short: 'Copying live requests to a new model while users still get the old model\'s answers, so the new one can be tested on real traffic without exposing anyone.', lesson: '/learn/systems/testing-and-deploying-ml-models/' },
  { id: 'interleaving', term: 'Interleaving', aka: ['interleaved evaluation'], short: 'Comparing two rankers by merging their results into one list and crediting user clicks, so each user effectively judges both.', lesson: '/learn/systems/testing-and-deploying-ml-models/' },
  { id: 'guardrail-metric', term: 'Guardrail metric', short: 'A measure, such as latency or error rate, watched during an experiment to make sure a change that improves the target metric is not harming something else.', lesson: '/learn/systems/testing-and-deploying-ml-models/' },
  { id: 'a-a-test', term: 'A/A test', aka: ['null test'], short: 'An experiment in which both groups get the identical experience, used to check the experiment system: about 5 percent of runs should look significant at a 95 percent level.', lesson: '/learn/systems/testing-and-deploying-ml-models/' },
  { id: 'covariate-shift', term: 'covariate shift', aka: ['input drift'], short: 'A change in the distribution of a model\'s inputs while the rule linking inputs to correct answers stays the same, for example a new group of customers arriving.', lesson: '/learn/systems/monitoring-and-drift/' },
  { id: 'label-shift', term: 'label shift', aka: ['prior shift', 'target shift'], short: 'A change in how common each outcome is, while the inputs seen for each outcome look the same, for example twice as much fraud as in the training data.', lesson: '/learn/systems/monitoring-and-drift/' },
  { id: 'concept-drift', term: 'concept drift', aka: ['posterior shift'], short: 'A change in the right answer for the same input, so a model that was correct becomes wrong even though its inputs look unchanged.', lesson: '/learn/systems/monitoring-and-drift/' },
  { id: 'population-stability-index', term: 'population stability index', aka: ['PSI'], short: 'A drift score that compares the share of values in each bin now with the share in a reference, summing (current minus reference) times the log of their ratio. Common bands are 0.1 and 0.25.', lesson: '/learn/systems/monitoring-and-drift/' },
  { id: 'kolmogorov-smirnov-test', term: 'Kolmogorov-Smirnov test', aka: ['KS test', 'two-sample KS'], short: 'A test that compares two samples by the largest gap between their cumulative distributions. The statistic runs from 0 (identical) to 1, and it gives a p-value.', lesson: '/learn/systems/monitoring-and-drift/' },
  { id: 'label-delay', term: 'label delay', aka: ['feedback delay'], short: 'The time between a model making a prediction and the true outcome becoming known, which limits how soon accuracy can be measured in production.', lesson: '/learn/systems/monitoring-and-drift/' },
  { id: 'data-slice', term: 'data slice', short: 'A subset of the data, such as one region or device type, whose metrics are tracked separately because a good overall average can hide a failing group.', lesson: '/learn/systems/monitoring-and-drift/' },
  { id: 'degenerate-feedback-loop', term: 'degenerate feedback loop', aka: ['exposure bias loop'], short: 'When a system\'s predictions influence the data it later learns from, so what it already favours gets even more favoured, as in popularity bias in recommenders.', lesson: '/learn/systems/ml-system-design-interviews/' },
  { id: 'delay-period', term: 'delay period', aka: ['label maturity gap'], short: 'A gap left between training data and the test period in time-based validation because the newest examples do not have final labels yet, as in fraud detection.', lesson: '/learn/systems/ml-system-design-interviews/' },
  { id: 'precision-at-k', term: 'precision at k', aka: ['precision top-k'], short: 'The share of the top k items or alerts that are truly relevant or fraudulent, used when reviewers can only check k cases a day.', lesson: '/learn/systems/ml-system-design-interviews/' },
  { id: 'champion-challenger', term: 'champion-challenger', aka: ['shadow challenger'], short: 'Running a new model alongside the current one, scoring the same traffic and comparing results, before it replaces the current one.', lesson: '/learn/systems/ml-system-design-interviews/' },

  // Wave 1 (Nov 2026): skills, classical ML, deep learning, responsible AI, audio
  { id: 'constrained-decoding', term: 'Constrained decoding', aka: ['grammar-constrained decoding', 'guided generation'], short: 'Choosing each next token only from those that can still lead to an output a grammar or schema accepts, so the result always parses. It guarantees shape, not that the content is right.', lesson: '/learn/llm/structured-output-in-depth/' },
  { id: 'token-mask', term: 'Token mask', aka: ['grammar mask', 'logit mask'], short: 'The step in constrained decoding that removes every token that cannot continue a valid output by setting its probability to zero. The remaining probabilities are rescaled to add up to one.', lesson: '/learn/llm/structured-output-in-depth/' },
  { id: 'json-mode', term: 'JSON mode', aka: ['json_object mode'], short: 'An API setting that makes the output valid JSON but does not check it against any schema, so keys and values can still be wrong. Schema-constrained output is the stronger option.', lesson: '/learn/llm/structured-output-in-depth/' },
  { id: 'structured-outputs', term: 'Structured outputs', aka: ['schema-constrained output', 'strict mode'], short: 'An API feature where you give a JSON Schema and the model\'s reply is forced to match it, within the subset of the schema language the provider supports.', lesson: '/learn/llm/structured-output-in-depth/' },
  { id: 'json-schema', term: 'JSON Schema', aka: ['schema'], short: 'A standard way to describe the shape of JSON: which keys exist, their types, which are required and which values are allowed. Providers accept different subsets of it.', lesson: '/learn/llm/structured-output-in-depth/' },
  { id: 'stop-reason', term: 'Stop reason', aka: ['finish reason', 'stop_reason'], short: 'A field in an API response saying why generation ended, such as finishing normally, hitting the token limit or refusing. Check it before parsing structured output.', lesson: '/learn/llm/structured-output-in-depth/' },
  { id: 'repair-loop', term: 'Repair loop', aka: ['validate-and-retry loop'], short: 'Code that checks a model\'s output, sends the error back for a corrected answer, and gives up after a fixed number of tries, falling back to a safe default or a person.', lesson: '/learn/llm/structured-output-in-depth/' },
  { id: 'standalone-question-rewriting', term: 'Standalone question rewriting', aka: ['conversational query rewriting'], short: 'Turning a follow-up such as "what about the battery?" into a question that makes sense alone by using the chat history, so the search has something to match.', lesson: '/learn/rag-agents/query-understanding-for-rag/' },
  { id: 'hyde', term: 'HyDE', aka: ['hypothetical document embeddings'], short: 'A retrieval trick: a model writes a made-up answer to the question and the search uses that text instead of the question. The made-up answer may contain false details.', lesson: '/learn/rag-agents/query-understanding-for-rag/' },
  { id: 'multi-query-retrieval', term: 'Multi-query retrieval', aka: ['RAG-Fusion', 'query expansion'], short: 'Asking a model for several paraphrases of a question, searching with each one and merging the ranked lists, usually with reciprocal rank fusion. It raises recall and adds searches.', lesson: '/learn/rag-agents/query-understanding-for-rag/' },
  { id: 'query-decomposition', term: 'Query decomposition', aka: ['sub-question splitting'], short: 'Splitting a compound question into simpler sub-questions, searching for each and combining the results. It helps when the answer needs facts that sit in different passages.', lesson: '/learn/rag-agents/query-understanding-for-rag/' },
  { id: 'query-routing', term: 'Query routing', aka: ['retrieval routing', 'adaptive RAG'], short: 'Deciding where a query goes before searching: which index, which metadata filter, or no retrieval at all. It is a classification problem and can be evaluated like one.', lesson: '/learn/rag-agents/query-understanding-for-rag/' },
  { id: 'vocabulary-mismatch', term: 'Vocabulary mismatch', aka: ['lexical gap'], short: 'When the words a person uses differ from the words in the documents, such as "dog" and "pet". Keyword search misses these; embedding search usually copes better.', lesson: '/learn/rag-agents/query-understanding-for-rag/' },
  { id: 'needle-in-a-haystack-test', term: 'needle-in-a-haystack test', aka: ['NIAH'], short: 'A long-context test that hides one fact (the needle) in long filler text (the haystack) and asks the model to find it; easy versions overstate real long-input skill.', lesson: '/learn/llm/long-context-or-rag/' },
  { id: 'cache-hit-rate', term: 'cache hit rate', short: 'The share of requests that find a reusable cached prompt prefix still stored; it decides whether caching saves money.', lesson: '/learn/llm/long-context-or-rag/' },
  { id: 'cache-write-premium', term: 'cache write premium', short: 'The extra price some providers charge, as a multiple of the normal input price, for storing a prompt prefix in the cache.', lesson: '/learn/llm/long-context-or-rag/' },
  { id: 'long-context-stuffing', term: 'long-context stuffing', aka: ['context stuffing'], short: 'Putting a whole document collection into every prompt instead of retrieving the few passages a question needs.', lesson: '/learn/llm/long-context-or-rag/' },
  { id: 'self-route', term: 'Self-Route', short: 'A hybrid method that sends each query to RAG first and falls back to long context when the model judges the retrieved passages cannot answer it.', lesson: '/learn/llm/long-context-or-rag/' },
  { id: 'knowledge-graph', term: 'knowledge graph', short: 'A store of entities (people, projects, parts) and the relations between them, which retrieval can walk instead of only comparing text similarity.', lesson: '/learn/rag-agents/graphrag-and-knowledge-graphs/' },
  { id: 'graphrag', term: 'GraphRAG', aka: ['graph RAG'], short: 'Retrieval-augmented generation that uses a knowledge graph built from the documents, often with community summaries, to answer multi-hop and whole-collection questions.', lesson: '/learn/rag-agents/graphrag-and-knowledge-graphs/' },
  { id: 'multi-hop-question', term: 'multi-hop question', short: 'A question whose answer needs facts from several passages linked through shared entities, so no single passage resembles the whole question.', lesson: '/learn/rag-agents/graphrag-and-knowledge-graphs/' },
  { id: 'community-detection', term: 'community detection', short: 'An algorithm, such as Leiden, that splits a graph into groups of nodes more densely linked to each other than to the rest.', lesson: '/learn/rag-agents/graphrag-and-knowledge-graphs/' },
  { id: 'community-report', term: 'community report', short: 'A model-written summary of one group of closely related entities, used in GraphRAG to answer questions about the whole collection.', lesson: '/learn/rag-agents/graphrag-and-knowledge-graphs/' },
  { id: 'global-search', term: 'global search', short: 'The GraphRAG query mode that answers whole-collection questions by combining partial answers drawn from community reports in a map-reduce pattern.', lesson: '/learn/rag-agents/graphrag-and-knowledge-graphs/' },
  { id: 'local-search', term: 'local search', short: 'The GraphRAG query mode that starts from entities named in the question and gathers their neighbours, linked passages and reports.', lesson: '/learn/rag-agents/graphrag-and-knowledge-graphs/' },
  { id: 'entity-resolution', term: 'entity resolution', aka: ['entity linking'], short: 'Deciding that different mentions, such as Priya and P. Nair, refer to the same entity, so the graph does not split one thing into several nodes.', lesson: '/learn/rag-agents/graphrag-and-knowledge-graphs/' },
  { id: 'parent-child-chunks', term: 'parent-child chunks', aka: ['small-to-big retrieval'], short: 'Searching small chunks for precision, then returning their larger parent chunk so the model gets the surrounding context.', lesson: '/learn/rag-agents/graphrag-and-knowledge-graphs/' },
  { id: 'text-to-sql', term: 'Text-to-SQL', aka: ['NL2SQL', 'natural language to SQL'], short: 'Using a language model to turn a plain-language question into a SQL query, which the database then runs to produce the answer.', lesson: '/learn/rag-agents/text-to-sql-and-data-agents/' },
  { id: 'schema-linking', term: 'Schema linking', aka: ['table and column selection'], short: 'Choosing which tables and columns of a database are relevant to a question, so that only those are described to the model in the prompt.', lesson: '/learn/rag-agents/text-to-sql-and-data-agents/' },
  { id: 'semantic-layer', term: 'Semantic layer', aka: ['metrics layer'], short: 'A shared set of definitions, such as what counts as revenue, kept in views or a metrics tool so that every query uses the same meaning instead of re-deriving it.', lesson: '/learn/rag-agents/text-to-sql-and-data-agents/' },
  { id: 'execution-accuracy', term: 'Execution accuracy', aka: ['EX'], short: 'A text-to-SQL score that runs the predicted and the gold query and counts the prediction as right when both return the same rows.', lesson: '/learn/rag-agents/text-to-sql-and-data-agents/' },
  { id: 'exact-match', term: 'Exact match', aka: ['exact set match'], short: 'A text-to-SQL score that compares the predicted SQL with the gold SQL as text, so it rejects correct queries that are merely written differently.', lesson: '/learn/rag-agents/text-to-sql-and-data-agents/' },
  { id: 'test-suite-accuracy', term: 'Test-suite accuracy', aka: ['distilled test suites'], short: 'Scoring a generated query by requiring the same rows as the gold query on several databases built to tell queries apart, which catches queries that got lucky on one.', lesson: '/learn/rag-agents/text-to-sql-and-data-agents/' },
  { id: 'gold-query', term: 'Gold query', aka: ['reference query', 'ground-truth SQL'], short: 'The query a person wrote or checked as the correct answer to a question, used as the reference when scoring generated queries.', lesson: '/learn/rag-agents/text-to-sql-and-data-agents/' },
  { id: 'verified-query', term: 'Verified query', aka: ['curated query'], short: 'A fixed, human-checked query that runs whenever a user question matches it, used instead of a generated one for the most important questions.', lesson: '/learn/rag-agents/text-to-sql-and-data-agents/' },
  { id: 'row-level-security', term: 'Row-level security', aka: ['row security policy', 'RLS'], short: 'A database feature that limits which rows each role may read or change, so a query run as a user only sees what that user is allowed to see.', lesson: '/learn/rag-agents/text-to-sql-and-data-agents/' },
  { id: 'computer-use-agent', term: 'Computer-use agent', aka: ['screen agent', 'GUI agent'], short: 'An AI agent that works by looking at screenshots and sending mouse and keyboard actions, so it can use software that has no API.', lesson: '/learn/rag-agents/computer-use-and-browser-agents/' },
  { id: 'accessibility-tree', term: 'Accessibility tree', aka: ['ARIA snapshot'], short: 'A text outline of a web page listing each element\'s role and name, such as a button or a heading, which can be given to a model instead of or beside a screenshot.', lesson: '/learn/rag-agents/computer-use-and-browser-agents/' },
  { id: 'grounding-ui', term: 'Grounding (UI)', aka: ['element grounding'], short: 'Turning a plan such as "add it to the basket" into the exact element or screen position to click.', lesson: '/learn/rag-agents/computer-use-and-browser-agents/' },
  { id: 'confirmation-gate', term: 'Confirmation gate', aka: ['approval step'], short: 'A rule that a person must approve irreversible actions, such as spending money or sending data out, before an agent carries them out.', lesson: '/learn/rag-agents/computer-use-and-browser-agents/' },
  { id: 'domain-allow-list', term: 'Domain allow-list', aka: ['URL allow-list'], short: 'A list of the only websites an agent\'s browser may visit, so a page cannot send the agent, or its data, somewhere else.', lesson: '/learn/rag-agents/computer-use-and-browser-agents/' },
  { id: 'agent-sandbox', term: 'Agent sandbox', aka: ['isolated browser', 'disposable VM'], short: 'A throwaway browser or virtual machine with no personal logins or saved details, used so that a fooled agent has little it can steal or damage.', lesson: '/learn/rag-agents/computer-use-and-browser-agents/' },
  { id: 'perceived-latency', term: 'perceived latency', aka: ['perceived wait'], short: 'How long a wait feels to the user, as opposed to how long the work takes. Streaming shortens it by showing the first words before the whole answer exists.', lesson: '/learn/systems/ux-for-ai-features/' },
  { id: 'live-region', term: 'live region', aka: ['aria-live region'], short: 'A part of a web page that tells screen readers about changes without taking focus. Streaming text should be announced through a small status message, not by making the token container live.', lesson: '/learn/systems/ux-for-ai-features/' },
  { id: 'verifiable-citation', term: 'verifiable citation', aka: ['checkable citation'], short: 'A citation built from a retrieved passage whose quoted text is confirmed to occur in the source, so the user can check the claim. A model-typed link is not verifiable by itself.', lesson: '/learn/systems/ux-for-ai-features/' },
  { id: 'uncertainty-cue', term: 'uncertainty cue', aka: ['confidence cue'], short: 'An interface signal, such as a hedge or a per-claim flag, that tells the user where an answer may be wrong. It helps only when it is calibrated and points to an action.', lesson: '/learn/systems/ux-for-ai-features/' },
  { id: 'cognitive-forcing-function', term: 'cognitive forcing function', aka: ['forcing function'], short: 'A design that makes the user think before seeing or accepting AI output, such as committing to an answer first. It can reduce overreliance, though people often rate it lowest.', lesson: '/learn/systems/ux-for-ai-features/' },
  { id: 'acceptance-rate', term: 'acceptance rate', aka: ['suggestion acceptance'], short: 'The share of AI suggestions that users take. It is easy to measure and can reflect users who do not check, so pair it with sampled audits of accepted output.', lesson: '/learn/systems/ux-for-ai-features/' },
  { id: 'error-escape', term: 'error escape', aka: ['escaped error'], short: 'A wrong output that reaches the user or customer despite checks. Measured by auditing a random sample of approved output, it is the number acceptance and automation rates hide.', lesson: '/learn/systems/human-in-the-loop-design/' },
  { id: 'approval-gate', term: 'approval gate', short: 'A step in code that pauses an agent before an action and waits for a person to approve, edit or reject it. The pause lives in the workflow, not in the prompt.', lesson: '/learn/systems/human-in-the-loop-design/' },
  { id: 'undo-window', term: 'undo window', aka: ['reversal window'], short: 'A set time after an action during which it can be reversed, used where the action is reversible and mistakes are cheap.', lesson: '/learn/systems/human-in-the-loop-design/' },
  { id: 'handoff-packet', term: 'handoff packet', aka: ['escalation packet'], short: 'The context passed to a person when an agent stops: the request, what the agent did and found, what it doubted, its intended action and why it stopped.', lesson: '/learn/systems/human-in-the-loop-design/' },
  { id: 'sampled-audit', term: 'sampled audit', aka: ['random audit'], short: 'Re-checking a random slice of items that were approved automatically, so the error rate of the unreviewed part can be estimated.', lesson: '/learn/systems/human-in-the-loop-design/' },
  { id: 'reviewer-load', term: 'reviewer load', aka: ['review load'], short: 'Items sent to review times minutes per review, divided by reviewer minutes available. Above 100% the queue cannot clear and a backlog grows.', lesson: '/learn/systems/human-in-the-loop-design/' },
  { id: 'reliability-table', term: 'reliability table', aka: ['calibration table'], short: 'Observed error rates for each band of a model\'s confidence score, from labelled data. It shows whether the score ranks errors and whether its stated numbers can be trusted.', lesson: '/learn/systems/human-in-the-loop-design/' },
  { id: 'guardrail', term: 'Guardrail', aka: ['LLM guardrail', 'safety filter'], short: 'A check beside a model that inspects inputs, outputs or tool calls and blocks, changes or flags them. It is a classifier with a threshold and error rates, not a permission boundary.', lesson: '/learn/evals/guardrails-in-practice/' },
  { id: 'false-positive-guardrail', term: 'False positive (guardrail)', aka: ['wrongly blocked request'], short: 'A harmless request that a guardrail blocks. It costs a real user a refusal, and at low base rates it can account for most of a filter\'s blocks.', lesson: '/learn/evals/guardrails-in-practice/' },
  { id: 'guardrail-cascade', term: 'Guardrail cascade', aka: ['layered checks'], short: 'Running cheap checks such as rules and a small classifier on every request and sending only the unclear middle cases to an expensive judge model, to limit delay and cost.', lesson: '/learn/evals/guardrails-in-practice/' },
  { id: 'asynchronous-stream-filtering', term: 'Asynchronous stream filtering', aka: ['async moderation'], short: 'Sending streamed text to the user immediately while a guardrail scans in the background, so harmful text may be shown briefly before a block arrives.', lesson: '/learn/evals/guardrails-in-practice/' },
  { id: 'model-armor', term: 'Model Armor', aka: ['Google Cloud guardrail service'], short: 'Google Cloud service that screens prompts and responses against configurable templates for harm categories, prompt injection, jailbreaks and sensitive data.', lesson: '/learn/evals/guardrails-in-practice/' },
  { id: 'trace', term: 'Trace', aka: ['request trace', 'distributed trace'], short: 'The record of one request or agent run as a tree of timed steps that share a trace ID, so you can open a single run and see what happened.', lesson: '/learn/evals/observability-for-llm-apps/' },
  { id: 'span', term: 'Span', aka: ['trace span'], short: 'One timed step in a trace, such as a model call, retrieval or tool call, with a name, start, duration, status and attributes.', lesson: '/learn/evals/observability-for-llm-apps/' },
  { id: 'own-time', term: 'Own time', aka: ['self time'], short: 'A span\'s duration minus the time covered by its child spans. It shows where the time was really spent, because a parent always includes its children.', lesson: '/learn/evals/observability-for-llm-apps/' },
  { id: 'genai-semantic-conventions', term: 'GenAI semantic conventions', aka: ['OpenTelemetry GenAI conventions'], short: 'OpenTelemetry\'s agreed names for spans, attributes and metrics of LLM calls, agents and tools. As of 1 November 2026 their status is Development, so names may change.', lesson: '/learn/evals/observability-for-llm-apps/' },
  { id: 'head-sampling', term: 'Head sampling', aka: ['up-front sampling'], short: 'Deciding whether to keep a trace at its start, usually from the trace ID. It is cheap but cannot know that a run will fail, so it can discard the traces you most need.', lesson: '/learn/evals/observability-for-llm-apps/' },
  { id: 'tail-sampling', term: 'Tail sampling', aka: ['outcome-based sampling'], short: 'Deciding whether to keep a trace after it finishes, so errors and slow runs can always be kept. It needs a component that holds whole traces until they end.', lesson: '/learn/evals/observability-for-llm-apps/' },
  { id: 'content-capture', term: 'Content capture', aka: ['prompt logging'], short: 'Recording the text of prompts, completions or tool results on traces. The OpenTelemetry GenAI text treats it as sensitive and off by default.', lesson: '/learn/evals/observability-for-llm-apps/' },
  { id: 'recurrent-neural-network', term: 'recurrent neural network', aka: ['RNN'], short: 'A network that reads a sequence one step at a time and carries a fixed-size memory, called the hidden state, from each step to the next, using the same weights at every step.', lesson: '/learn/deep-learning/rnns-and-lstms/' },
  { id: 'hidden-state', term: 'hidden state', aka: ['recurrent state'], short: 'The list of numbers a recurrent network carries from step to step. Everything it knows about the past has to fit in it.', lesson: '/learn/deep-learning/rnns-and-lstms/' },
  { id: 'lstm', term: 'LSTM', exact: true, aka: ['long short-term memory'], short: 'A recurrent network with a separate memory (the cell state) and three gates that control what is forgotten, written and shown, which helps it remember across long gaps.', lesson: '/learn/deep-learning/rnns-and-lstms/' },
  { id: 'gru', term: 'GRU', exact: true, aka: ['gated recurrent unit'], short: 'A lighter relative of the LSTM that merges the forget and input gates into one update gate and merges the cell and hidden state, so it has fewer weights.', lesson: '/learn/deep-learning/rnns-and-lstms/' },
  { id: 'gate', term: 'gate', aka: ['forget gate', 'input gate', 'output gate'], short: 'A small layer whose answer is squashed to a number between 0 and 1 and multiplied into something else, acting like a dimmer switch on what passes through.', lesson: '/learn/deep-learning/rnns-and-lstms/' },
  { id: 'cell-state', term: 'cell state', aka: ['LSTM memory cell'], short: 'The LSTM\'s memory belt. It is changed only by multiplying (forget gate) and adding (input gate), so information can travel along it over many steps.', lesson: '/learn/deep-learning/rnns-and-lstms/' },
  { id: 'backpropagation-through-time', term: 'backpropagation through time', aka: ['BPTT'], short: 'Training a recurrent network by unrolling it into one copy per step and running backpropagation back through all the copies.', lesson: '/learn/deep-learning/rnns-and-lstms/' },
  { id: 'pretext-task', term: 'pretext task', short: 'A made-up exercise whose answer is already in the data, such as filling in a masked word. The exercise is only a means: the useful product is the representation the model builds.', lesson: '/learn/deep-learning/self-supervised-and-transfer-learning/' },
  { id: 'contrastive-learning', term: 'contrastive learning', short: 'Training a model so that two views of the same item get similar embeddings and different items get dissimilar ones.', lesson: '/learn/deep-learning/self-supervised-and-transfer-learning/' },
  { id: 'infonce', term: 'InfoNCE', aka: ['NT-Xent', 'contrastive loss'], short: 'A contrastive loss: a softmax over similarities in which the correct answer is the anchor\'s partner view and every other item in the batch is a negative.', lesson: '/learn/deep-learning/self-supervised-and-transfer-learning/' },
  { id: 'augmentation', term: 'augmentation', basic: true, aka: ['data augmentation'], short: 'Making altered copies of an example, such as cropping, flipping or changing colours. In contrastive learning the augmentations decide which differences the model learns to ignore.', lesson: '/learn/deep-learning/self-supervised-and-transfer-learning/' },
  { id: 'representation', term: 'representation', aka: ['learned features'], short: 'The internal numbers a model builds to describe an input. In pretraining the representation is the part worth keeping and reusing.', lesson: '/learn/deep-learning/self-supervised-and-transfer-learning/' },
  { id: 'transfer-learning', term: 'transfer learning', short: 'Reusing a model trained on one big task as the starting point for a different task that has few labels.', lesson: '/learn/deep-learning/self-supervised-and-transfer-learning/' },
  { id: 'feature-extraction', term: 'feature extraction', aka: ['linear probe', 'frozen features'], short: 'Transfer by freezing a pretrained model and training only a new small classifier on its outputs.', lesson: '/learn/deep-learning/self-supervised-and-transfer-learning/' },
  { id: 'shortcut', term: 'shortcut', aka: ['shortcut learning'], short: 'An easy cue in the training data that lets a model solve its task without learning what you wanted, such as matching two views by their shared background.', lesson: '/learn/deep-learning/self-supervised-and-transfer-learning/' },
  { id: 'zero-shot', term: 'zero-shot', short: 'Using a model on a new task with no weight updates: zero-shot gives no examples, few-shot puts a few examples in the prompt.', lesson: '/learn/deep-learning/self-supervised-and-transfer-learning/' },
  { id: 'autoencoder', term: 'autoencoder', aka: ['AE'], short: 'A network with an encoder that squeezes an input into a short code and a decoder that rebuilds the input from it, trained to make the rebuild match the original.', lesson: '/learn/deep-learning/autoencoders-vaes-and-gans/' },
  { id: 'bottleneck', term: 'bottleneck', short: 'The deliberately small code in the middle of an autoencoder. It forces the network to keep what matters, because it cannot simply copy the input across.', lesson: '/learn/deep-learning/autoencoders-vaes-and-gans/' },
  { id: 'latent-code', term: 'latent code', aka: ['latent', 'latent vector'], short: 'The short list of numbers an encoder produces for an input. A decoder turns it back into something the size of the input.', lesson: '/learn/deep-learning/autoencoders-vaes-and-gans/' },
  { id: 'variational-autoencoder', term: 'variational autoencoder', aka: ['VAE'], short: 'An autoencoder whose encoder outputs a small cloud of codes instead of one, with a penalty that pulls all clouds towards a standard bell curve, so random codes can be decoded into new samples.', lesson: '/learn/deep-learning/autoencoders-vaes-and-gans/' },
  { id: 'reparameterisation-trick', term: 'reparameterisation trick', aka: ['reparameterization trick'], short: 'Writing a random draw as mean plus spread times fixed noise, so the draw stays differentiable and ordinary backpropagation can train a VAE.', lesson: '/learn/deep-learning/autoencoders-vaes-and-gans/' },
  { id: 'generative-adversarial-network', term: 'generative adversarial network', aka: ['GAN'], short: 'A pair of networks trained against each other: a generator makes fake samples and a discriminator tries to tell them from real ones, each improving as the other does.', lesson: '/learn/deep-learning/autoencoders-vaes-and-gans/' },
  { id: 'generator', term: 'generator', aka: ['forger'], short: 'In a GAN, the network that turns random noise into a fake sample and is trained to fool the discriminator.', lesson: '/learn/deep-learning/autoencoders-vaes-and-gans/' },
  { id: 'discriminator', term: 'discriminator', aka: ['detective', 'critic'], short: 'In a GAN, the network that scores a sample from 0 (looks fake) to 1 (looks real), trained to separate real data from the generator\'s fakes.', lesson: '/learn/deep-learning/autoencoders-vaes-and-gans/' },
  { id: 'mode-collapse', term: 'mode collapse', short: 'A GAN failure where the generator covers only some of the kinds of example in the data, for instance one hump of two, because it piles its samples where the discriminator is easiest to fool.', lesson: '/learn/deep-learning/autoencoders-vaes-and-gans/' },
  { id: 'fid', term: 'FID', exact: true, aka: ['Fréchet inception distance'], short: 'A score for how close generated images are to real ones, measured in a feature space of a pretrained network. Lower is better. It can miss lack of variety.', lesson: '/learn/deep-learning/autoencoders-vaes-and-gans/' },
  { id: 'attention-mask', term: 'attention mask', aka: ['causal mask'], short: 'A grid that switches off some token-to-token comparisons in attention. Causal masks hide later tokens, bidirectional masks hide nothing, and prefix masks mix the two.', lesson: '/learn/deep-learning/encoders-decoders-and-objectives/' },
  { id: 'masked-language-modelling', term: 'masked language modelling', aka: ['MLM', 'fill-in-the-blank objective'], short: 'A training task where some tokens are hidden and the model predicts them from the words on both sides. BERT hides about 15% of tokens this way.', lesson: '/learn/deep-learning/encoders-decoders-and-objectives/' },
  { id: 'span-corruption', term: 'span corruption', aka: ['denoising objective'], short: 'T5\'s training task: runs of hidden tokens are each replaced by one sentinel marker, and the model must write out the missing spans.', lesson: '/learn/deep-learning/encoders-decoders-and-objectives/' },
  { id: 'sentinel-token', term: 'sentinel token', short: 'A special marker such as <X> that stands in for a hidden span of text, and labels that span in the target the model must produce.', lesson: '/learn/deep-learning/encoders-decoders-and-objectives/' },
  { id: 'cross-attention', term: 'cross-attention', aka: ['encoder-decoder attention'], short: 'Attention in which the decoder\'s tokens look at the encoder\'s output positions, so what it writes can depend on everything in the input.', lesson: '/learn/deep-learning/encoders-decoders-and-objectives/' },
  { id: 'prefix-language-model', term: 'prefix language model', aka: ['prefix LM'], short: 'A single transformer stack whose mask lets the first few tokens see each other both ways while the rest are written left to right.', lesson: '/learn/deep-learning/encoders-decoders-and-objectives/' },
  { id: 'cross-entropy', term: 'cross-entropy', short: 'The average of minus the log of the probability the model gave to each true token. Zero for a perfect model, larger as the model is more surprised.', lesson: '/learn/deep-learning/encoders-decoders-and-objectives/' },
  { id: 'perplexity', term: 'perplexity', aka: ['PPL'], short: 'Two to the average bits (or e to the average nats) of cross-entropy: the number of equally likely choices the model is, on average, as unsure as.', lesson: '/learn/deep-learning/encoders-decoders-and-objectives/' },
  { id: 'bits-per-byte', term: 'bits per byte', aka: ['BPB'], short: 'Total bits a model needs for some text divided by its length in UTF-8 bytes. Unlike perplexity it does not depend on how the text is cut into tokens.', lesson: '/learn/deep-learning/encoders-decoders-and-objectives/' },
  { id: 'kl-divergence', term: 'KL divergence', aka: ['Kullback-Leibler divergence', 'relative entropy'], short: 'The extra bits per item paid for using one probability distribution when another is true. It is zero only when they match and is not symmetric.', lesson: '/learn/deep-learning/encoders-decoders-and-objectives/' },
  { id: 'mamba', term: 'Mamba', aka: ['selective state-space model', 'S6'], short: 'A state-space model whose step size and read and write vectors are computed from each token, so the state can keep important input and ignore filler.', lesson: '/learn/deep-learning/state-space-models-and-mamba/' },
  { id: 'selective-scan', term: 'selective scan', aka: ['selection mechanism'], short: 'Letting a recurrent layer\'s coefficients depend on the current input, then computing it as a scan, so the model chooses what to remember.', lesson: '/learn/deep-learning/state-space-models-and-mamba/' },
  { id: 'parallel-scan', term: 'parallel scan', aka: ['prefix scan'], short: 'A way to compute all the running states of a linear recurrence in about log2 n rounds, because combining two steps gives another step of the same form.', lesson: '/learn/deep-learning/state-space-models-and-mamba/' },
  { id: 'hybrid-architecture', term: 'hybrid architecture', aka: ['attention-SSM hybrid', 'Jamba-style'], short: 'A model that mixes a few attention layers with many state-space layers, keeping exact lookup while cutting the key-value cache.', lesson: '/learn/deep-learning/state-space-models-and-mamba/' },
  { id: 's4', term: 'S4', exact: true, aka: ['structured state space sequence model'], short: 'An earlier state-space model with fixed coefficients and a special initialisation for long memory, computable as one long convolution.', lesson: '/learn/deep-learning/state-space-models-and-mamba/' },
  { id: 'associative-recall', term: 'associative recall', aka: ['in-context recall'], short: 'The task of finding something that appeared earlier in the context, such as a phone number for a name; fixed-state models tend to be weaker at it than attention.', lesson: '/learn/deep-learning/state-space-models-and-mamba/' },
  { id: 'return', term: 'return', aka: ['discounted return'], short: 'In reinforcement learning, the sum of the rewards an agent collects from now on, with later rewards counted for less by a discount factor.', lesson: '/learn/deep-learning/reinforcement-learning-from-scratch/' },
  { id: 'discount-factor', term: 'discount factor', short: 'A number between 0 and 1 that shrinks each later reward, so a reward that is further away counts for less now.', lesson: '/learn/deep-learning/reinforcement-learning-from-scratch/' },
  { id: 'q-value', term: 'Q-value', aka: ['action value', 'Q(s'], short: 'The return an agent expects if it takes a given action in a given state and then keeps following its policy.', lesson: '/learn/deep-learning/reinforcement-learning-from-scratch/' },
  { id: 'epsilon-greedy', term: 'epsilon-greedy', aka: ['e-greedy exploration'], short: 'A rule that takes a random action with probability epsilon and the best-looking action otherwise, so the agent keeps trying alternatives.', lesson: '/learn/deep-learning/reinforcement-learning-from-scratch/' },
  { id: 'exploration-and-exploitation', term: 'exploration and exploitation', basic: true, aka: ['explore or exploit'], short: 'The trade-off between trying new actions to learn more and using the best action found so far to collect reward.', lesson: '/learn/deep-learning/reinforcement-learning-from-scratch/' },
  { id: 'bootstrapping', term: 'bootstrapping', aka: ['temporal-difference target'], short: 'Updating an estimate using another of the learner\'s own estimates, such as the value of the next state, instead of waiting for the final outcome.', lesson: '/learn/deep-learning/reinforcement-learning-from-scratch/' },
  { id: 'off-policy-learning', term: 'off-policy learning', aka: ['off-policy'], short: 'Learning the value of one way of behaving, such as the best moves, from experience collected by a different way of behaving, such as random exploration.', lesson: '/learn/deep-learning/reinforcement-learning-from-scratch/' },
  { id: 'deadly-triad', term: 'deadly triad', short: 'The combination of function approximation, bootstrapping and off-policy training, which Sutton and Barto identify as a source of instability and divergence in reinforcement learning.', lesson: '/learn/deep-learning/reinforcement-learning-from-scratch/' },
  { id: 'experience-replay', term: 'experience replay', aka: ['replay buffer'], short: 'Storing past moves and training on random samples of them, which breaks the correlation between consecutive observations and steadies learning.', lesson: '/learn/deep-learning/reinforcement-learning-from-scratch/' },
  { id: 'endpointing', term: 'Endpointing', aka: ['end-of-turn detection'], short: 'Deciding that a speaker has finished their turn so a voice agent can answer. A short silence threshold cuts people off; a long one adds delay to every reply.', lesson: '/learn/audio/voice-agents/' },
  { id: 'barge-in', term: 'Barge-in', aka: ['interruption handling'], short: 'Letting a caller interrupt a voice agent mid-reply: the agent stops speaking at once, cancels work in flight and keeps only what the caller heard.', lesson: '/learn/audio/voice-agents/' },
  { id: 'full-duplex-voice-model', term: 'Full-duplex voice model', aka: ['full duplex'], short: 'A speech model that listens while it speaks, as people do, so it can handle overlaps and interruptions without strict turns.', lesson: '/learn/audio/voice-agents/' },
  { id: 'speech-to-speech-model', term: 'Speech-to-speech model', aka: ['S2S model', 'realtime voice model'], short: 'One model that takes audio in and produces audio out, with no separate transcript and synthesis stages in the middle.', lesson: '/learn/audio/voice-agents/' },
  { id: 'cascade-pipeline', term: 'Cascade pipeline', aka: ['chained voice pipeline'], short: 'A voice agent built from separate stages: streaming speech recognition, a text model, then streaming speech synthesis. Each stage can be inspected or replaced.', lesson: '/learn/audio/voice-agents/' },
  { id: 'speculative-generation', term: 'Speculative generation', aka: ['preemptive generation'], short: 'Starting the language model before the end of the user\'s turn is confirmed, to hide waiting time. The work is thrown away if the user keeps talking.', lesson: '/learn/audio/voice-agents/' },
  { id: 'time-to-first-audio', term: 'Time to first audio', aka: ['first-audio latency'], short: 'How long from a request (or the end of the caller\'s turn) until the first sound is heard. In voice agents it is the number users feel.', lesson: '/learn/audio/voice-agents/' },
  { id: 'acoustic-echo-cancellation', term: 'Acoustic echo cancellation', aka: ['AEC'], short: 'Removing the agent\'s own voice, which leaks from speaker to microphone, so it does not hear and interrupt itself.', lesson: '/learn/audio/voice-agents/' },
  { id: 'semantic-cache', term: 'Semantic cache', aka: ['similarity cache'], short: 'A cache that returns a stored answer when a new question is similar enough to an earlier one, measured by embedding similarity against a threshold.', lesson: '/learn/cost/semantic-caching-and-batch-apis/' },
  { id: 'similarity-threshold', term: 'Similarity threshold', aka: ['cache threshold'], short: 'The score above which a semantic cache treats two questions as the same. Too low serves wrong answers; too high gives few hits.', lesson: '/learn/cost/semantic-caching-and-batch-apis/' },
  { id: 'wrong-hit', term: 'Wrong hit', aka: ['false cache hit'], short: 'A cache hit that returns an answer meant for a different question or tenant. It saves a model call but gives the user a wrong answer.', lesson: '/learn/cost/semantic-caching-and-batch-apis/' },
  { id: 'exact-match-cache', term: 'Exact-match cache', aka: ['request-response cache'], short: 'A cache that reuses the stored reply only when the whole request (prompt and settings) is identical. Safe, but it hits rarely on free-text input.', lesson: '/learn/cost/semantic-caching-and-batch-apis/' },
  { id: 'batch-api', term: 'Batch API', short: 'An interface that takes a file of requests, runs them asynchronously and returns results later (often within 24 hours) at a lower price, about half at the major vendors.', lesson: '/learn/cost/semantic-caching-and-batch-apis/' },
  { id: 'retry-after', term: 'Retry-After', aka: ['429 back-off header'], short: 'An HTTP header on a rate-limit response (429) telling the client how long to wait before trying again. Honour it and add exponential backoff.', lesson: '/learn/cost/semantic-caching-and-batch-apis/' },
  { id: 'explainability', term: 'Explainability', aka: ['explainable AI', 'XAI'], short: 'Giving a person a representation of why or how an AI system produced its output; NIST defines it as a representation of the mechanisms underlying the system\'s operation.', lesson: '/learn/responsible/why-did-it-say-that/' },
  { id: 'interpretability', term: 'Interpretability', aka: ['interpretable model'], short: 'Whether a person can follow what a model does, or understand what its output means in context; an interpretable model is one simple enough to read directly.', lesson: '/learn/responsible/why-did-it-say-that/' },
  { id: 'shapley-value', term: 'Shapley value', aka: ['SHAP', 'SHapley Additive exPlanations'], short: 'A feature\'s fair share of the gap between one prediction and a typical one, found by averaging what it adds across combinations of the other features.', lesson: '/learn/responsible/why-did-it-say-that/' },
  { id: 'counterfactual-explanation', term: 'Counterfactual explanation', aka: ['what-if explanation'], short: 'An explanation that says what would need to change in the input to get a different result, such as a lower debt figure that would flip a loan decision.', lesson: '/learn/responsible/why-did-it-say-that/' },
  { id: 'mechanistic-interpretability', term: 'Mechanistic interpretability', aka: ['mech interp'], short: 'Research that tries to explain a neural network from the inside, by finding the features and circuits in its activations, using tools such as probes and sparse autoencoders.', lesson: '/learn/responsible/why-did-it-say-that/' },
  { id: 'sparse-autoencoder', term: 'Sparse autoencoder', aka: ['SAE'], short: 'A small network trained to split a layer\'s activations into many sparse features that people may be able to name; a tool of interpretability research with known limits.', lesson: '/learn/responsible/why-did-it-say-that/' },
  { id: 'probe', term: 'Probe', aka: ['probing classifier'], short: 'A simple classifier trained on a layer\'s activations to test whether some property can be read from them; it shows information is present, not that the model uses it.', lesson: '/learn/responsible/why-did-it-say-that/' },
  { id: 'ai-governance', term: 'AI governance', aka: ['responsible AI programme'], short: 'The routine that lets an organisation say who decides about its AI systems, on what evidence, and what happens when something goes wrong.', lesson: '/learn/responsible/running-ai-governance/' },
  { id: 'ai-inventory', term: 'AI inventory', aka: ['AI register'], short: 'A maintained list of every AI system an organisation builds or buys, each with an owner, purpose and risk tier.', lesson: '/learn/responsible/running-ai-governance/' },
  { id: 'nist-ai-risk-management-framework', term: 'NIST AI Risk Management Framework', aka: ['NIST AI RMF'], short: 'A voluntary US framework, released in January 2023, that organises AI risk work into four functions: Govern, Map, Measure and Manage.', lesson: '/learn/responsible/running-ai-governance/' },
  { id: 'generative-ai-profile', term: 'Generative AI Profile', aka: ['NIST AI 600-1'], short: 'A July 2024 NIST companion to the AI RMF that lists twelve risks new to or worsened by generative AI and suggests actions for each.', lesson: '/learn/responsible/running-ai-governance/' },
  { id: 'iso-iec-42001', term: 'ISO/IEC 42001', aka: ['AI management system standard'], short: 'An ISO standard for AI management systems, published in 2023. Its text is paid, so check iso.org for what it requires.', lesson: '/learn/responsible/running-ai-governance/' },
  { id: 'datasheet-for-a-dataset', term: 'Datasheet for a dataset', aka: ['dataset card'], short: 'A document that records why a dataset was made, what is in it, how it was collected and cleaned, what it should and should not be used for, and who maintains it.', lesson: '/learn/responsible/running-ai-governance/' },
  { id: 'system-card', term: 'System card', aka: ['release card'], short: 'A longer document some AI developers publish with a model release, describing its testing and known risks. Contents vary by company.', lesson: '/learn/responsible/running-ai-governance/' },
  { id: 'serious-incident', term: 'Serious incident', aka: ['AI incident'], short: 'In the EU AI Act, an incident or malfunction leading to death or serious harm to health, serious disruption of critical infrastructure, breach of fundamental-rights obligations, or serious harm to property or the environment.', lesson: '/learn/responsible/running-ai-governance/' },
  { id: 'risk-tier', term: 'Risk tier', aka: ['risk level'], short: 'A level assigned to an AI system from its use, which sets how much review it needs before launch.', lesson: '/learn/responsible/running-ai-governance/' },
  { id: 'automation-bias', term: 'Automation bias', basic: true, aka: ['over-reliance on automation'], short: 'The habit of trusting a machine\'s advice too much, including accepting it when it is wrong. Studies find it in experts as well as beginners.', lesson: '/learn/responsible/human-oversight-and-when-ai-should-not-decide/' },
  { id: 'human-on-the-loop', term: 'Human on the loop', aka: ['human oversight', 'monitoring'], short: 'A design where the system acts by itself and a person watches, samples its work and can step in or stop it.', lesson: '/learn/responsible/human-oversight-and-when-ai-should-not-decide/' },
  { id: 'cognitive-forcing', term: 'Cognitive forcing', aka: ['commit-first design'], short: 'A design that makes a reviewer decide or think before seeing the AI\'s answer, so they rely on it less blindly. Studies show it can reduce over-reliance, though people often like it less.', lesson: '/learn/responsible/human-oversight-and-when-ai-should-not-decide/' },
  { id: 'confidence-based-escalation', term: 'Confidence-based escalation', aka: ['selective review'], short: 'Sending only the items the system is unsure about to a person. It works only if the confidence score really puts the errors among the low-confidence items.', lesson: '/learn/responsible/human-oversight-and-when-ai-should-not-decide/' },
  { id: 'calibration', term: 'Calibration', aka: ['calibrated confidence'], short: 'How well a model\'s stated confidence matches how often it is right. A well-calibrated model that says 80% is right about 80 times in 100.', lesson: '/learn/responsible/human-oversight-and-when-ai-should-not-decide/' },
  { id: 'rubber-stamp-review', term: 'Rubber-stamp review', basic: true, aka: ['token oversight'], short: 'A human check that approves almost everything without real scrutiny, so it adds a signature but no safety. Falling reject rates and shrinking review times are warning signs.', lesson: '/learn/responsible/human-oversight-and-when-ai-should-not-decide/' },
  { id: 'fair-use', term: 'Fair use', aka: ['US fair use doctrine'], short: 'A US legal defence that can excuse some uses of copyrighted work without permission. Courts weigh purpose, the work, the amount used and the effect on the market, case by case.', lesson: '/learn/responsible/where-the-data-comes-from/' },
  { id: 'text-and-data-mining-exception', term: 'Text and data mining exception', aka: ['TDM exception'], short: 'A rule in some countries, including the EU and UK, allowing copying of works for automated analysis under conditions. In the EU rights holders can opt out in a machine-readable way.', lesson: '/learn/responsible/where-the-data-comes-from/' },
  { id: 'opt-out', term: 'Opt-out', aka: ['rights reservation'], short: 'A rights holder\'s signal that their content may not be used for text and data mining or AI training. In the EU it must be expressed in an appropriate, machine-readable way.', lesson: '/learn/responsible/where-the-data-comes-from/' },
  { id: 'robots-txt', term: 'robots.txt', basic: true, aka: ['robots exclusion protocol'], short: 'A file on a website telling crawlers which paths to avoid. The standard calls its rules requests that crawlers are asked to honour, not access control.', lesson: '/learn/responsible/where-the-data-comes-from/' },
  { id: 'creative-commons-licence', term: 'Creative Commons licence', basic: true, aka: ['CC licence'], short: 'A family of public licences that let others reuse a work on conditions such as giving credit (BY), no commercial use (NC), sharing alike (SA) or no changes (ND).', lesson: '/learn/responsible/where-the-data-comes-from/' },
  { id: 'sharealike', term: 'ShareAlike', aka: ['SA', 'share-alike', 'copyleft'], short: 'A licence condition that things you make from the material and share must carry the same or a compatible licence. Whether a trained model counts as such a thing is unsettled.', lesson: '/learn/responsible/where-the-data-comes-from/' },
  { id: 'odbl', term: 'ODbL', aka: ['Open Database Licence'], short: 'A licence for databases that requires attribution and share-alike for derivative databases that you publicly use.', lesson: '/learn/responsible/where-the-data-comes-from/' },
  { id: 'responsible-ai-licence', term: 'Responsible AI licence', aka: ['RAIL', 'OpenRAIL'], short: 'A model licence that is open about use but attaches use restrictions, which the user must pass on to anyone they give the model to.', lesson: '/learn/responsible/where-the-data-comes-from/' },
  { id: 'training-data-summary', term: 'Training data summary', aka: ['public summary of training content'], short: 'A public document that providers of general-purpose AI models in the EU must publish, using the European Commission\'s template, describing the types and sources of data used.', lesson: '/learn/responsible/where-the-data-comes-from/' },
  { id: 'data-provenance', term: 'Data provenance', aka: ['data lineage record'], short: 'A record of where each dataset came from: source, licence, date collected, and what opt-outs were respected. It is what you are asked for when someone questions your data.', lesson: '/learn/responsible/where-the-data-comes-from/' },
  { id: 'watt-hour', term: 'watt-hour', basic: true, aka: ['Wh'], short: 'A unit of energy: one watt of power used for one hour. A 10 W LED bulb on for six minutes uses 1 Wh, and 1,000 Wh make a kilowatt-hour.', lesson: '/learn/responsible/energy-and-water-of-ai/' },
  { id: 'kilowatt-hour', term: 'kilowatt-hour', basic: true, aka: ['kWh'], short: 'The unit of energy on an electricity bill: 1,000 watt-hours, such as a 1,000 W heater running for an hour.', lesson: '/learn/responsible/energy-and-water-of-ai/' },
  { id: 'grid-carbon-intensity', term: 'grid carbon intensity', basic: true, aka: ['carbon intensity of electricity'], short: 'How many grams of carbon dioxide equivalent are released to make one kilowatt-hour of electricity on a grid; it depends on the mix of coal, gas, nuclear, wind, solar and hydro.', lesson: '/learn/responsible/energy-and-water-of-ai/' },
  { id: 'power-usage-effectiveness', term: 'power usage effectiveness', aka: ['PUE'], short: 'A data centre\'s total energy use divided by the energy used by its computers. A value of 1.0 would mean no overhead for cooling or power conversion.', lesson: '/learn/responsible/energy-and-water-of-ai/' },
  { id: 'location-based-emissions', term: 'location-based emissions', aka: ['location-based carbon count'], short: 'A carbon count that uses the average emissions of the grid where the electricity was actually used, with no credit for renewable electricity bought elsewhere.', lesson: '/learn/responsible/energy-and-water-of-ai/' },
  { id: 'market-based-emissions', term: 'market-based emissions', aka: ['market-based carbon count'], short: 'A carbon count that reflects the electricity a company chooses to buy, so renewable purchases can bring it far below the location-based figure.', lesson: '/learn/responsible/energy-and-water-of-ai/' },
  { id: 'embodied-emissions', term: 'embodied emissions', aka: ['embodied carbon'], short: 'The carbon released when equipment such as chips and servers is made, counted separately from the electricity they use later.', lesson: '/learn/responsible/energy-and-water-of-ai/' },
  { id: 'intended-use', term: 'intended use', aka: ['intended purpose'], short: 'What the maker says a device is for: which condition, which patients, which users and which setting. Regulators judge a medical device by this, not by the technology inside.', lesson: '/learn/responsible/medical-and-regulated-ai/' },
  { id: 'software-as-a-medical-device', term: 'software as a medical device', aka: ['SaMD'], short: 'Software that does a medical job, such as diagnosing, monitoring or guiding treatment, on its own and not as part of a physical device.', lesson: '/learn/responsible/medical-and-regulated-ai/' },
  { id: 'predetermined-change-control-plan', term: 'predetermined change control plan', aka: ['PCCP'], short: 'A plan in an FDA marketing submission that describes planned changes to an AI function, how they will be developed and validated, and their impact, so they can be made without a new submission each time.', lesson: '/learn/responsible/medical-and-regulated-ai/' },
  { id: 'clinical-validation', term: 'clinical validation', aka: ['clinical evaluation'], short: 'Evidence that a tool works for its intended use with real patients in the real workflow. It goes beyond a technical test on held-out data.', lesson: '/learn/responsible/medical-and-regulated-ai/' },
  { id: 'external-validation', term: 'external validation', short: 'Testing a model on data from other sites, devices or time periods than the ones it was built on, to see whether its performance holds.', lesson: '/learn/responsible/medical-and-regulated-ai/' },
  { id: 'prospective-study', term: 'prospective study', aka: ['prospective evaluation'], short: 'A study that enrols patients and follows them forward in time, instead of analysing old records. It gives stronger evidence of real-world effect.', lesson: '/learn/responsible/medical-and-regulated-ai/' },
  { id: 'sensitivity-and-specificity', term: 'sensitivity and specificity', aka: ['true positive rate and true negative rate'], short: 'Sensitivity is the share of people with the condition that a test catches. Specificity is the share of people without it that the test correctly clears.', lesson: '/learn/responsible/medical-and-regulated-ai/' },
  { id: 'positive-and-negative-predictive-value', term: 'positive and negative predictive value', aka: ['PPV and NPV'], short: 'PPV is the share of flagged people who really have the condition, and NPV is the share of cleared people who really do not. Both change with how common the condition is.', lesson: '/learn/responsible/medical-and-regulated-ai/' },
  { id: 'notified-body', term: 'notified body', short: 'An independent organisation designated in the EU to assess whether higher-risk medical devices meet the rules before they can be sold.', lesson: '/learn/responsible/medical-and-regulated-ai/' },
  { id: 'captions', term: 'Captions', basic: true, aka: ['subtitles (same language)'], short: 'A text version of the speech and other important sounds in a video, shown in time with it, so that people who cannot hear the audio can follow.', lesson: '/learn/responsible/ai-for-accessibility/' },
  { id: 'alt-text', term: 'Alt text', basic: true, aka: ['alternative text', 'alt attribute'], short: 'A short written description of a picture in a web page\'s code, read aloud by a screen reader. Purely decorative images get an empty alt attribute so they are skipped.', lesson: '/learn/responsible/ai-for-accessibility/' },
  { id: 'screen-reader', term: 'Screen reader', basic: true, short: 'Software that reads what is on a screen aloud, or sends it to a braille display, so a person who is blind or has low vision can use a computer or phone.', lesson: '/learn/responsible/ai-for-accessibility/' },
  { id: 'dysarthria', term: 'Dysarthria', short: 'A speech disability where the muscles used for speaking are weak or hard to control, so speech can be slurred or slow. Speech recognisers trained on typical speech often make more errors on it.', lesson: '/learn/responsible/ai-for-accessibility/' },
  { id: 'cart', term: 'CART', exact: true, aka: ['Communication Access Realtime Translation'], short: 'Live captioning by a trained human captioner, in the room or remotely, typed as people speak.', lesson: '/learn/responsible/ai-for-accessibility/' },
  { id: 'signing-avatar', term: 'Signing avatar', short: 'A computer-animated figure that signs a message. Deaf organisations caution against using avatars in place of human signers, especially for live or important information.', lesson: '/learn/responsible/ai-for-accessibility/' },
  { id: 'risk-based-regulation', term: 'Risk-based regulation', aka: ['risk-tiered'], short: 'A way of regulating AI where the duties grow with the risk of the use or system, as in the EU AI Act, instead of one set of rules for everything.', lesson: '/learn/responsible/ai-rules-around-the-world/' },
  { id: 'deployer', term: 'Deployer', short: 'Under the EU AI Act, whoever uses an AI system under their own authority in a professional setting, as opposed to the provider who develops it and puts it on the market.', lesson: '/learn/responsible/ai-rules-around-the-world/' },
  { id: 'non-statutory-principles', term: 'Non-statutory principles', aka: ['soft law'], short: 'Guidance and principles that a government issues without putting them into an Act of Parliament, leaving existing regulators to apply them. The UK took this approach in its 2023 white paper.', lesson: '/learn/responsible/ai-rules-around-the-world/' },
  { id: 'cure-period', term: 'Cure period', aka: ['right to cure'], short: 'A set time, such as 60 days, in which a company can fix a violation after receiving notice, before a regulator can bring an enforcement action.', lesson: '/learn/responsible/ai-rules-around-the-world/' },
  { id: 'content-labelling', term: 'Content labelling', aka: ['AI labelling', 'provenance marking'], short: 'A duty to mark AI-generated content, visibly for people, in file metadata for machines, or both. The EU, China, India and South Korea each have rules of this kind.', lesson: '/learn/responsible/ai-rules-around-the-world/' },
  { id: 'safe-harbour', term: 'Safe harbour', aka: ['intermediary protection'], short: 'A legal protection that shields an online platform from liability for what its users post, provided it follows set rules. In India it can be lost if the platform breaks the IT Rules.', lesson: '/learn/responsible/ai-rules-around-the-world/' },
  { id: 'dot-product', term: 'dot product', basic: true, aka: ['inner product'], short: 'Multiply two vectors number by number and add the results. A big positive answer means the vectors point the same way; zero means they share nothing.', lesson: '/learn/skills/maths-without-fear/' },
  { id: 'cosine-similarity', term: 'cosine similarity', aka: ['cosine score'], short: 'A score from -1 to 1 for how closely two vectors point the same way, ignoring their length. Search tools use it to find text with a similar meaning.', lesson: '/learn/skills/maths-without-fear/' },
  { id: 'matrix', term: 'matrix', basic: true, short: 'A table of numbers that works like a machine: put a vector in and a new vector comes out. Each layer of a neural network is built from matrices.', lesson: '/learn/skills/maths-without-fear/' },
  { id: 'bayes-rule', term: 'Bayes\' rule', basic: true, aka: ['Bayes\' theorem'], short: 'A way to update how likely something is after new evidence. Counting imaginary people (natural frequencies) makes it easier to follow.', lesson: '/learn/skills/maths-without-fear/' },
  { id: 'natural-frequencies', term: 'natural frequencies', aka: ['frequency format'], short: 'Writing probabilities as counts of people out of a round total, such as 9 out of 98, instead of percentages. Research suggests many people reason more accurately this way.', lesson: '/learn/skills/maths-without-fear/' },
  { id: 'notebook', term: 'notebook', basic: true, aka: ['Jupyter notebook', '.ipynb'], short: 'A document of cells holding text and code, with the output shown under each code cell. Colab, Kaggle and Jupyter all use notebooks.', lesson: '/learn/skills/your-toolkit-notebooks-colab-and-git/' },
  { id: 'restart-and-run-all', term: 'Restart and run all', basic: true, short: 'A notebook command that wipes the kernel\'s memory and runs every cell from the top, so you can check the notebook really produces what it shows.', lesson: '/learn/skills/your-toolkit-notebooks-colab-and-git/' },
  { id: 'git', term: 'git', basic: true, aka: ['version control'], short: 'A tool that saves numbered snapshots of a project, so you can see what changed, go back, and try ideas without losing your work.', lesson: '/learn/skills/your-toolkit-notebooks-colab-and-git/' },
  { id: 'commit', term: 'commit', basic: true, aka: ['save point'], short: 'One saved snapshot of a project in git, with a short message saying what changed.', lesson: '/learn/skills/your-toolkit-notebooks-colab-and-git/' },
  { id: 'staging-area', term: 'staging area', short: 'In git, the place where chosen changes wait after git add, until git commit saves them together as one commit.', lesson: '/learn/skills/your-toolkit-notebooks-colab-and-git/' },
  { id: 'branch', term: 'branch', basic: true, aka: ['git branch'], short: 'A separate line of commits in git. You can try an idea on a branch and merge it back, or drop it, without touching the main line.', lesson: '/learn/skills/your-toolkit-notebooks-colab-and-git/' },
  { id: 'gitignore', term: '.gitignore', aka: ['ignore file'], short: 'A file that lists names git should not track, such as .env files that hold secrets or large data files.', lesson: '/learn/skills/your-toolkit-notebooks-colab-and-git/' },
  { id: 'virtual-environment', term: 'virtual environment', short: 'A self-contained folder with its own copy of Python and its own packages, so different projects do not disturb each other.', lesson: '/learn/skills/your-toolkit-notebooks-colab-and-git/' },
  { id: 'requirements-txt', term: 'requirements.txt', aka: ['pinned versions'], short: 'A text file listing the exact package versions a project used, so anyone can rebuild the same setup with pip install -r.', lesson: '/learn/skills/your-toolkit-notebooks-colab-and-git/' },
  { id: 'ai-winter', term: 'AI winter', basic: true, aka: ['AI winters'], short: 'A time when money and interest in AI dropped, because the big promises had not been met. Historians usually name two, in the 1970s and in the late 1980s into the 1990s.', lesson: '/learn/start/a-short-history-of-ai/' },
  { id: 'turing-test', term: 'Turing test', basic: true, aka: ['imitation game'], short: 'A game suggested by Alan Turing in 1950: if you chat by typed messages and cannot tell the machine from a person, the machine is doing well.', lesson: '/learn/start/a-short-history-of-ai/' },
  { id: 'dartmouth-workshop', term: 'Dartmouth workshop', basic: true, aka: ['Dartmouth summer'], short: 'A 1956 summer project at Dartmouth College, planned in a 1955 proposal that used the words "artificial intelligence". It is often seen as the start of AI as a field.', lesson: '/learn/start/a-short-history-of-ai/' },
  { id: 'imagenet', term: 'ImageNet', basic: true, aka: ['ImageNet challenge'], short: 'A huge collection of photos labelled with what is in them, now over 14 million images. Contests on it helped deep learning take off, especially in 2012.', lesson: '/learn/start/a-short-history-of-ai/' },
  { id: 'automation', term: 'Automation', basic: true, aka: ['automated', 'plain automation'], short: 'A machine that follows fixed steps a person wrote, such as a kettle that switches off when the water boils. It does not learn from examples.', lesson: '/learn/start/ai-around-you/' },
  { id: 'robot', term: 'Robot', basic: true, aka: ['robots'], short: 'A machine that moves in the real world. It may follow fixed programmed steps, use AI, or both, so being a robot does not mean it has AI.', lesson: '/learn/start/ai-around-you/' },
  { id: 'sensor', term: 'Sensor', basic: true, aka: ['sensors'], short: 'A part that measures something in the world, such as movement, heat or sound, and passes it on as a number. Sensing is not the same as understanding what it means.', lesson: '/learn/start/ai-around-you/' },
  { id: 'perception', term: 'Perception', basic: true, aka: ['machine perception'], short: 'Finding meaning in what sensors pick up, such as which face is in a picture or which words are in a sound. AI is often used for this step.', lesson: '/learn/start/ai-around-you/' },
  { id: 'feed', term: 'feed', basic: true, aka: ['news feed', 'timeline'], short: 'A list of posts or videos that an app picks and puts in an order for you, usually by guessing what you will enjoy.', lesson: '/learn/start/how-feeds-and-search-decide/' },
  { id: 'ranking', term: 'ranking', basic: true, short: 'Putting a list of things in order, best first, using a score. Search engines and feeds both rank.', lesson: '/learn/start/how-feeds-and-search-decide/' },
  { id: 'signal', term: 'signal', basic: true, short: 'A clue a computer can measure and use in a score, such as likes, watch time, or who you follow.', lesson: '/learn/start/how-feeds-and-search-decide/' },
  { id: 'personalisation', term: 'personalisation', basic: true, aka: ['personalising'], short: 'Giving different people different results or feeds, based on what the app has learned about them.', lesson: '/learn/start/how-feeds-and-search-decide/' },
  { id: 'watch-time', term: 'watch time', basic: true, short: 'How long people spend watching a video. Apps often use it as a clue that a video was worth showing.', lesson: '/learn/start/how-feeds-and-search-decide/' },
  { id: 'eliza', term: 'ELIZA', exact: true, basic: true, short: 'A 1966 chatbot that spotted keywords and filled in ready-made replies. Some people felt it understood them, though it did not.', lesson: '/learn/start/does-ai-understand/' },
  { id: 'chinese-room', term: 'Chinese room', aka: ['Searle\'s Chinese room'], short: 'A thought experiment asking whether following the right rules for a language is enough to understand it.', lesson: '/learn/start/does-ai-understand/' },
  { id: 'jagged-capabilities', term: 'jagged capabilities', basic: true, aka: ['jagged intelligence'], short: 'The pattern that an AI can do well at hard tasks yet fail at simpler ones, so its skill is uneven.', lesson: '/learn/start/does-ai-understand/' },

  // Wave 1 (Nov 2026): skills, classical ML, deep learning, responsible AI, audio
  { id: 'bounding-box', term: 'bounding box', basic: true, short: 'A rectangle drawn around an object in a picture to show where it is. A detector gives one box for each object it finds.', lesson: '/learn/start/how-ai-finds-things-in-a-picture/' },
  { id: 'confidence-score', term: 'confidence score', basic: true, aka: ['confidence'], short: 'A number that says how sure a model is about an answer, such as 90 out of 100. It is not a promise: a model can be confident and still wrong.', lesson: '/learn/start/how-ai-finds-things-in-a-picture/' },
  { id: 'non-maximum-suppression', term: 'non-maximum suppression', aka: ['NMS'], short: 'A step that keeps the highest-scoring box and removes other boxes that overlap it by more than a set IoU threshold, so each object ends up with one box.', lesson: '/learn/deep-learning/detection-and-segmentation/' },
  { id: 'anchor-box', term: 'anchor box', aka: ['anchors', 'default boxes'], short: 'A reference box of a set size and shape placed at every position in a detector. The network predicts a small shift from an anchor to a nearby real object.', lesson: '/learn/deep-learning/detection-and-segmentation/' },
  { id: 'two-stage-detector', term: 'two-stage detector', aka: ['region-based detector', 'R-CNN family'], short: 'A detector that first proposes regions that might hold objects, then classifies and refines each one. Faster R-CNN is an example.', lesson: '/learn/deep-learning/detection-and-segmentation/' },
  { id: 'one-stage-detector', term: 'one-stage detector', aka: ['single-shot detector'], short: 'A detector that predicts boxes and classes at every position in one pass, with no separate proposal step. YOLO and SSD are examples.', lesson: '/learn/deep-learning/detection-and-segmentation/' },
  { id: 'detr', term: 'DETR', exact: true, aka: ['detection transformer'], short: 'A detector that uses a transformer to output a fixed set of boxes directly, trained with a matching loss, so it needs no anchors and no non-maximum suppression.', lesson: '/learn/deep-learning/detection-and-segmentation/' },
  { id: 'semantic-segmentation', term: 'semantic segmentation', aka: ['pixel classification'], short: 'Giving every pixel in a picture a class label, such as sky or road. It does not separate two objects of the same class.', lesson: '/learn/deep-learning/detection-and-segmentation/' },
  { id: 'instance-segmentation', term: 'instance segmentation', aka: ['instance masks'], short: 'Finding each countable object in a picture and giving it its own pixel mask, so two people standing together are kept apart.', lesson: '/learn/deep-learning/detection-and-segmentation/' },
  { id: 'panoptic-segmentation', term: 'panoptic segmentation', aka: ['panoptic'], short: 'Labelling every pixel with a class and also giving each countable object its own instance number, combining semantic and instance segmentation.', lesson: '/learn/deep-learning/detection-and-segmentation/' },
  { id: 'u-net', term: 'U-Net', short: 'A segmentation network that shrinks the picture to capture context, grows it back for precise outlines, and copies detail across with skip connections.', lesson: '/learn/deep-learning/detection-and-segmentation/' },
  { id: 'segment-anything', term: 'Segment Anything', aka: ['SAM'], short: 'A promptable segmentation model: you give a point or a box and it returns a mask for the object you meant. Trained on over a billion masks.', lesson: '/learn/deep-learning/detection-and-segmentation/' },
  { id: 'average-precision', term: 'average precision', aka: ['AP', 'mAP'], short: 'A score for a detector based on the area under its precision-recall curve. COCO averages it over ten IoU thresholds and over classes.', lesson: '/learn/deep-learning/detection-and-segmentation/' },
  { id: 'ai-exposure', term: 'AI exposure', aka: ['occupational exposure', 'task exposure'], short: 'A rating of how much of an occupation\'s tasks an AI tool could do or speed up. It says a tool could touch the work, not that jobs will be lost or when.', lesson: '/learn/responsible/ai-and-work/' },
  { id: 'task-based-view-of-work', term: 'task-based view of work', aka: ['tasks versus jobs'], short: 'Treating a job as a bundle of separate tasks, each of which AI may help with, replace or leave alone. What happens to the job depends on which tasks, how much time they take and demand.', lesson: '/learn/responsible/ai-and-work/' },
  { id: 'data-labeller', term: 'data labeller', basic: true, aka: ['data annotator', 'data enrichment worker'], short: 'A person who adds the right label to pictures, sounds or text so a computer has examples to learn from. The work is often hidden from the people who use the finished AI.', lesson: '/learn/start/ai-and-careers/' },
  { id: 'ai-evaluator', term: 'AI evaluator', basic: true, aka: ['AI tester', 'model evaluator'], short: 'A person who tests an AI system with many examples to find mistakes, unfair results or unsafe behaviour, before and after release. Job titles for this work vary.', lesson: '/learn/start/ai-and-careers/' },
  { id: 'projection-employment', term: 'projection (employment)', basic: true, aka: ['employment projection'], short: 'A careful estimate of future job numbers under stated assumptions. It is not a promise or a forecast, and statisticians say the uncertainty about AI\'s effects is very high.', lesson: '/learn/start/ai-and-careers/' },
  { id: 'randomised-controlled-trial', term: 'randomised controlled trial', aka: ['RCT', 'field experiment'], short: 'A study that randomly gives some people a tool and not others, then compares them. It is strong for the setting studied, but may not carry over to other jobs or tools.', lesson: '/learn/responsible/ai-and-work/' },
  { id: 'counterfactual-in-labour-studies', term: 'counterfactual (in labour studies)', aka: ['counterfactual employment'], short: 'What would have happened without the thing being studied, estimated here from comparable groups. A gap versus the counterfactual is a pattern, not proof of cause.', lesson: '/learn/responsible/ai-and-work/' },
  { id: 'three-pass-method', term: 'three-pass method', basic: true, aka: ['Keshav method'], short: 'Reading a paper in up to three passes: a quick look at title, abstract, headings and conclusions, then the figures and tables, then re-creating the work if you need to build on it.', lesson: '/learn/skills/reading-an-ai-paper/' },
  { id: 'abstract', term: 'abstract', basic: true, aka: ['paper summary'], short: 'The short summary at the top of a paper. It lists the claims and headline numbers, but the evidence and the doubts are further down, in the tables and ablations.', lesson: '/learn/skills/reading-an-ai-paper/' },
  { id: 'baseline', term: 'baseline', basic: true, aka: ['comparison model'], short: 'An older or simpler method scored in the same way as the new one. Without a fair baseline, a new method\'s score shows little about whether it is better.', lesson: '/learn/skills/reading-an-ai-paper/' },
  { id: 'ablation-study', term: 'ablation study', aka: ['ablation'], short: 'An experiment that removes one part of a method and measures what gets worse. It shows which parts really matter.', lesson: '/learn/skills/reading-an-ai-paper/' },
  { id: 'error-bars', term: 'error bars', basic: true, aka: ['spread', 'standard deviation over runs'], short: 'Marks on a chart or a ± value in a table that show how much a result changes from run to run. A gap smaller than the spread may be luck.', lesson: '/learn/skills/reading-an-ai-paper/' },
  { id: 'preprint', term: 'preprint', basic: true, aka: ['arXiv paper'], short: 'A paper shared publicly before, or without, peer review. arXiv says it moderates submissions but does not peer review them.', lesson: '/learn/skills/reading-an-ai-paper/' },
  { id: 'reproducibility', term: 'reproducibility', aka: ['reproducible research'], short: 'Getting similar results to a paper by using its code and data. Code, data and a checklist make it easier to check whether a result holds.', lesson: '/learn/skills/reading-an-ai-paper/' },
];

export const glossaryById = Object.fromEntries(glossary.map((t) => [t.id, t]));

/** The payload the in-page tooltip script needs. Kept small on purpose. */
export function glossaryForTooltips() {
  return glossary.map((t) => ({
    id: t.id,
    match: [t.term, ...(t.aka ?? [])],
    exact: !!t.exact,
    short: t.short,
  }));
}
